window.__CHEMLAB__ = {"site":{"site":{"name":"大学化学实验学习平台","org":"昆明理工大学理学院","version":"1.1.3","updated":"2026-11-22","copyright":"教材与课程材料（含封面、原文、插图）版权归昆明理工大学理学院所有，仅用于本校课程教学；未经书面许可，不得用于商业用途或对外转载。","credits":"内容整理：昆明理工大学理学院化学实验课程组。图片：教材插图、课程实拍与自制示意图；标注“示意图（AI 生成）”的图片由本机 AI 生成，仅作实验示意。","disclaimer":"本站为课前预习辅助材料，不替代课堂讲授与实验操作。化学实验有风险，具体操作请以指导教师现场要求与实验室安全规程为准。","contact":"如涉侵权或发现内容错误，请在 GitHub 仓库（ZZQLittleBean/Chemistry_Safety_Preview_Platform_KUST）提交 Issue，我们将在核实后处理。"},"announcement":{"image":"assets/announcement.jpg","title":"课前预习：先读安全教育，再看实验详情"},"currentTextbook":"inorganic","textbooks":[{"id":"inorganic","name":"无机化学实验","cover":"assets/book-cover.jpg","order":0,"total":6},{"id":"analytical","name":"分析化学实验","cover":"assets/analytical-cover.jpg","order":1,"total":4}],"updates":[{"version":"1.1.3","date":"2026-11-22","notes":["新增了若干分析化学实验的材料。","实验任务点进度页新增二维码分享按钮，可扫码打开当前页面。"]},{"version":"1.1.2","date":"2026-11-21","notes":["优化预习页的设计与用户操作：左右翻页、完成页替代完成弹窗、悬浮反馈入口、图片放大查看。","调整关于页文字的白色底元件内边距，改善贴边问题。"]},{"version":"1.1.1","date":"2026-11-17","notes":["修订无机化学实验预习材料：规范排版、清理多余与重复格式，补充/精简相关条目。","平台各实验预习材料后续仍可继续补充、增删。"]},{"version":"1.1.0","date":"2026-11-16","notes":["移除含学生人脸的课堂照片，替换为仪器示意图；补齐或缺图处改为表格/示意图"]},{"version":"1.0.0","date":"2026-11-15","notes":["上线无机化学实验 6 个实验的预习材料"]}]},"books":{"analytical":{"id":"analytical","name":"分析化学实验","order":1,"cover":"assets/analytical-cover.jpg","safetyPoster":"assets/safety-analytical.png","intro":"分析化学实验课前预习材料","hidden":false,"visibleAt":"","updateStatus":"updating","experiments":[{"id":"h01","no":1,"name":"水的总硬度测定","full":"实验四十五 水的总硬度的测定","order":1,"hidden":true,"visibleAt":"","cards":4,"points":26,"feedbackUrl":""},{"id":"e02","no":2,"name":"NaOH 溶液的配制与标定","full":"NaOH 溶液的配制与标定","order":2,"hidden":true,"visibleAt":"","cards":4,"points":21,"feedbackUrl":""},{"id":"e03","no":3,"name":"EDTA 溶液的标定","full":"EDTA 溶液的标定","order":3,"hidden":true,"visibleAt":"","cards":4,"points":21,"feedbackUrl":""},{"id":"e04","no":4,"name":"醋酸含量的测定","full":"醋酸含量的测定","order":4,"hidden":true,"visibleAt":"","cards":4,"points":20,"feedbackUrl":""},{"id":"e05","name":"分析基础练习","full":"分析基础练习","no":5,"order":0,"hidden":false,"visibleAt":"","cards":4,"points":25,"feedbackUrl":""},{"id":"e06","name":"EDTA配标+水的硬度","full":"EDTA溶液配制与标定+水的硬度","no":6,"order":0,"hidden":false,"visibleAt":"","cards":4,"points":24,"feedbackUrl":""},{"id":"e07","name":"NaOH标配与醋酸测定","full":"NaOH标准溶液配制与标定及醋酸含量的测定","no":7,"order":0,"hidden":false,"visibleAt":"","cards":4,"points":46,"feedbackUrl":""},{"id":"e08","no":10,"name":"过氧化氢含量的测定","full":"实验四十九 过氧化氢含量的测定","order":6,"hidden":false,"visibleAt":"","cards":4,"points":23,"feedbackUrl":""},{"id":"e09","no":8,"name":"铝盐中铝含量的测定","full":"实验四十七 铝盐中铝含量的测定","order":7,"hidden":false,"visibleAt":"","cards":4,"points":28,"feedbackUrl":""},{"id":"e10","no":9,"name":"高锰酸钾标准溶液的配制与标定","full":"实验四十八 高锰酸钾标准溶液的配制与标定","order":5,"hidden":false,"visibleAt":"","cards":4,"points":27,"feedbackUrl":""},{"id":"e11","name":"邻二氮菲法测铁","full":"邻二氮菲吸光光度法测定铁","no":11,"order":0,"hidden":false,"visibleAt":"","cards":4,"points":26,"feedbackUrl":""}],"coverW":296,"coverH":416,"safetyPosterW":750,"safetyPosterH":1552},"inorganic":{"id":"inorganic","name":"无机化学实验","cover":"assets/book-cover.jpg","order":0,"hidden":false,"visibleAt":"","updateStatus":"updating","safetyPoster":"assets/safety-inorganic.png","intro":"大一《无机化学实验》课前预习材料","experiments":[{"id":"e01","no":1,"name":"基本操作练习及粗食盐的提纯","full":"基本操作练习及粗食盐的提纯","order":1,"hidden":false,"visibleAt":"","cards":4,"points":101,"feedbackUrl":""},{"id":"e02","no":2,"name":"配位解离平衡常数测定","full":"配位解离平衡常数的测定","order":2,"hidden":false,"visibleAt":"","cards":4,"points":106},{"id":"e03","no":3,"name":"硫酸铜晶体制备","full":"用废硫酸铜溶液制备五水合硫酸铜晶体","order":3,"hidden":false,"visibleAt":"","cards":4,"points":64},{"id":"e04","no":4,"name":"溶解平衡","full":"溶解平衡（性质类实验）","order":4,"hidden":false,"visibleAt":"","cards":4,"points":36},{"id":"e05","no":5,"name":"电导率与解离平衡","full":"电导率法测定解离常数 · 解离平衡及水解反应","order":5,"hidden":false,"visibleAt":"","cards":4,"points":110},{"id":"e06","no":6,"name":"氧化还原与原电池","full":"氧化还原与原电池","order":6,"hidden":false,"visibleAt":"","cards":4,"points":49}],"coverW":296,"coverH":416,"safetyPosterW":750,"safetyPosterH":1584}},"exps":{"analytical/e02":{"id":"e02","no":2,"name":"NaOH 溶液的配制与标定","full":"NaOH 溶液的配制与标定","cards":[{"id":"safety","title":"安全教育","hint":"进实验室前先读完","blocks":[{"t":"kv","k":"防潮称量","v":"NaOH极易吸潮，称量要迅速，称后立即密封，避免吸收水分和CO₂。"},{"t":"kv","k":"防腐蚀","v":"NaOH溶液有腐蚀性，避免接触皮肤和眼睛；若不慎沾到，立即用大量水冲洗。"},{"t":"kv","k":"排气泡","v":"滴定前必须排除碱式滴定管尖嘴和橡胶管内的气泡，否则读数偏大，带来误差。"},{"t":"kv","k":"废液处理","v":"滴定废液集中回收，不可直接倒入下水道；酚酞指示剂含乙醇，远离明火。"},{"t":"kv","k":"规范读数","v":"滴定管读数时视线与凹液面最低点相平，读至0.01 mL，避免视差。"}],"count":5,"ai":true},{"id":"purpose","title":"实验目的","hint":"为什么做、依据是什么","blocks":[{"t":"p","text":"学会间接法配制近似浓度的NaOH溶液，并用基准物质邻苯二甲酸氢钾标定其准确浓度。"},{"t":"p","text":"理解基准物质应具备的条件，掌握称量、溶解、滴定和浓度计算的全过程。"},{"t":"p","text":"练习碱式滴定管的洗涤、润洗、排气泡、滴定操作和终点判断。"},{"t":"p","text":"通过酚酞指示剂在化学计量点附近pH≈9.1的变色，学会观察和判断滴定终点。"}],"count":4,"ai":true},{"id":"procedure","title":"实验流程","hint":"按顺序做什么","blocks":[{"t":"p","text":"计算并快速称取配制400 mL 0.1 mol·L⁻¹ NaOH溶液所需固体NaOH，置于100 mL烧杯中，加50 mL蒸馏水溶解。"},{"t":"p","text":"将溶液转移至500 mL试剂瓶中，用50 mL蒸馏水淋洗烧杯两次，洗液并入试剂瓶，再稀释至约400 mL，塞紧橡胶塞摇匀，贴标签备用。"},{"t":"p","text":"在分析天平上准确称取邻苯二甲酸氢钾约0.5 g（称准至0.0001 g）两份，分别放入250 mL锥形瓶中。"},{"t":"p","text":"各加50 mL煮沸后刚冷却的蒸馏水溶解（若溶解不完全可微热后冷却），加入2滴酚酞指示剂。"},{"t":"p","text":"用配制的NaOH溶液润洗碱式滴定管2~3次，装液并排除气泡，调节液面至零刻度附近，记录初读数。"},{"t":"p","text":"用NaOH溶液滴定锥形瓶中的邻苯二甲酸氢钾溶液，边滴边摇，至溶液呈微红色且0.5 min内不褪色即为终点，记录终读数。"},{"t":"p","text":"平行滴定两份，计算每次消耗NaOH溶液的体积，并据邻苯二甲酸氢钾质量和体积计算NaOH的准确浓度。"}],"count":7,"ai":true},{"id":"thinking","title":"实验思考","hint":"做完再想一遍","blocks":[{"t":"h","text":"Q 能否在分析天平上准确称取固体NaOH直接配制成标准溶液？为什么？"},{"t":"p","text":"不能。固体NaOH极易吸收空气中的水分和CO₂，表面潮解并部分转化为Na₂CO₃，称得的质量不能代表纯NaOH的质量，故只能用间接法配制，再用基准物质标定。"},{"t":"h","text":"Q 滴定管在装标准溶液前为什么要用此标准溶液淋洗2~3次？"},{"t":"p","text":"为了除去滴定管内残留的水分和杂质，避免装入的溶液被稀释或污染，保证滴定管内溶液浓度与待装标准溶液一致，减小浓度误差。"},{"t":"h","text":"Q 配制NaOH溶液用的蒸馏水体积，是否需要准确量取？为什么？"},{"t":"p","text":"不需要准确量取。因为所配溶液只是近似浓度，其准确浓度随后用基准物质标定确定，水的体积不影响标定结果。"},{"t":"h","text":"Q 溶解基准物邻苯二甲酸氢钾所用的水的体积，是否需要准确量取？为什么？"},{"t":"p","text":"不需要准确量取。水的体积不影响邻苯二甲酸氢钾的物质的量，只影响滴定终点时溶液的体积和pH突跃范围，只要保证基准物完全溶解且体积不过大即可。"},{"t":"h","text":"Q 为什么用酚酞作指示剂？终点如何判断？"},{"t":"p","text":"邻苯二甲酸氢钾与NaOH反应化学计量点时pH约为9.1，酚酞变色范围约为8.2~10.0，适用。滴至溶液呈微红色且0.5 min内不褪色即为终点。"}],"count":5,"qa":[{"q":"滴加氨水时为什么要逐滴加入并边加边摇？","a":"逐滴加入、边加边摇可以及时观察到沉淀的生成与恰好溶解，避免氨水局部过量导致配合物直接生成而错过中间现象，也能防止反应过于剧烈、溶液溅出。"},{"q":"如何检验配离子的内界与外界？","a":"内界配体在配离子内部，不与溶液中其他离子直接反应；外界离子可被沉淀剂检出。例如向 [Cu(NH₃)₄]SO₄ 溶液中加 BaCl₂ 会产生 BaSO₄ 沉淀，而加 NaOH 不产生 Cu(OH)₂ 沉淀，说明 Cu²⁺ 在内界、SO₄²⁻ 在外界。"},{"q":"银氨溶液为什么必须现配现用？","a":"银氨溶液久置或蒸干会生成雷爆银（Ag₃N 等），受摩擦、震动可能爆炸。使用后应立即加稀盐酸酸化破坏，倒入含银废液瓶，用过即洗，严禁久存、严禁蒸干、严禁倒入水槽。"},{"q":"加入 Na₂S 后沉淀溶解平衡向哪个方向移动？","a":"S²⁻ 与 Ag⁺ 生成更难溶的 Ag₂S，使溶液中 Ag⁺ 浓度大幅降低，AgCl（或 AgI）的溶解平衡向溶解方向移动并转化为 Ag₂S 沉淀。沉淀转化的方向由两种难溶物溶度积的相对大小决定，Ksp 更小的更稳定。"},{"q":"配合物的稳定性用什么衡量？","a":"用稳定常数 K稳（或 β）衡量：K稳 越大，配离子越稳定，解离程度越小。比较不同配体对同一中心离子的配位能力时，可比较对应配离子的 K稳。"},{"q":"为什么配位平衡会受酸度影响？","a":"许多配体（如 NH₃、S₂O₃²⁻、F⁻）是弱碱或弱酸根，加酸会使其质子化、有效浓度下降，配离子随之解离；反之加碱可能生成氢氧化物沉淀。因此配位平衡与酸碱平衡、沉淀平衡相互影响。"}],"ai":true}],"qa":[{"q":"称取NaOH时为什么要快速？","a":"NaOH易吸潮并与CO₂反应，称量时间过长会改变其实际质量，导致配制浓度偏差。"},{"q":"滴定管尖嘴有气泡如何处理？","a":"将滴定管尖嘴向上倾斜，轻捏橡胶管使液体冲出气泡，再调至零刻度附近重新读数。"},{"q":"邻苯二甲酸氢钾溶解不完全怎么办？","a":"可微热使其溶解，但必须冷却至室温后再滴定，以免温度影响指示剂变色和滴定结果。"},{"q":"为什么用煮沸后刚冷却的蒸馏水溶解基准物？","a":"煮沸可除去水中溶解的CO₂，避免CO₂消耗NaOH或影响终点pH，冷却后使用可减少误差。"},{"q":"平行滴定两份结果相差较大怎么办？","a":"检查称量、读数、气泡和终点判断是否一致，必要时重新滴定；一般要求相对偏差较小，否则应重做。"},{"q":"NaOH溶液如何计算准确浓度？","a":"c(NaOH)=m(KHC₈H₄O₄)/(M(KHC₈H₄O₄)×V(NaOH))，其中M=204.2 g·mol⁻¹，V以L计。"}],"ai":true,"order":2,"hidden":true,"visibleAt":"","feedbackUrl":""},"analytical/e03":{"id":"e03","no":3,"name":"EDTA 溶液的标定","full":"EDTA 溶液的标定","cards":[{"id":"safety","title":"安全教育","hint":"进实验室前先读完","blocks":[{"t":"kv","k":"防护装备","v":"实验时须穿实验服、戴护目镜和一次性丁腈手套，避免溶液溅入眼或接触皮肤。"},{"t":"kv","k":"氨水操作","v":"1∶1氨水易挥发且刺激呼吸道，应在通风橱中量取和滴加，避免直接吸入蒸气。"},{"t":"kv","k":"铬黑T","v":"铬黑T指示剂含有机染料，避免误入口中；配制和滴加时防止溅洒，接触后及时洗手。"},{"t":"kv","k":"废液处理","v":"含锌、EDTA及缓冲溶液的滴定废液应集中收集于废液桶，不得直接倒入下水道。"},{"t":"kv","k":"滴定管使用","v":"酸式滴定管使用前检查活塞是否漏液，滴定过程中防止活塞脱落或溶液溅出。"}],"count":5,"ai":true},{"id":"purpose","title":"实验目的","hint":"为什么做、依据是什么","blocks":[{"t":"p","text":"学习EDTA标准溶液的配制和标定方法，掌握由固体试剂配制近似浓度溶液、再用基准物质或标准溶液标定其准确浓度的基本思路。"},{"t":"p","text":"掌握配位滴定的基本原理，理解EDTA与金属离子形成稳定配合物的计量关系，并能根据滴定消耗体积计算EDTA溶液的浓度。"},{"t":"p","text":"了解铬黑T指示剂在配位滴定中的应用及终点颜色变化，认识金属指示剂指示终点的原理。"},{"t":"p","text":"通过用锌标准溶液标定EDTA溶液，训练移液管、容量瓶、滴定管等定量仪器的规范使用和滴定操作技能。"}],"count":4,"ai":true},{"id":"procedure","title":"实验流程","hint":"按顺序做什么","blocks":[{"t":"p","text":"配制0.02 mol·L⁻¹ EDTA溶液300 mL：称取乙二胺四乙酸二钠2.23 g，置于150 mL烧杯中，加50 mL蒸馏水溶解。"},{"t":"p","text":"将溶解后的EDTA溶液移入500 mL试剂瓶中，用蒸馏水稀释至总体积300 mL，摇匀，备用。"},{"t":"p","text":"用移液管准确吸取25.00 mL锌标准溶液，置于250 mL锥形瓶中。"},{"t":"p","text":"滴加1∶1氨水至开始析出白色氢氧化锌沉淀，然后加入pH 10氨性缓冲溶液10 mL和蒸馏水20 mL。"},{"t":"p","text":"加入铬黑T指示剂1～3滴，摇匀，此时溶液呈酒红色。"},{"t":"p","text":"用配制的EDTA溶液滴定，边滴边充分摇动，临近终点时缓慢滴定，直至溶液由酒红色变为纯蓝色即为终点。"},{"t":"p","text":"记录消耗的EDTA溶液体积，平行滴定2～3次，根据锌标准溶液浓度和消耗体积计算EDTA溶液的准确浓度。"}],"count":7,"ai":true},{"id":"thinking","title":"实验思考","hint":"做完再想一遍","blocks":[{"t":"h","text":"Q 配制EDTA标准溶液时常用乙二胺四乙酸二钠盐，而不用乙二胺四乙酸，为什么？"},{"t":"p","text":"乙二胺四乙酸在水中的溶解度较小，而乙二胺四乙酸二钠盐溶解度较大，便于配制成所需浓度的溶液；且二钠盐相对分子质量明确，称量后可直接配制近似浓度溶液，再通过标定获得准确浓度。"},{"t":"h","text":"Q 用锌标准溶液标定EDTA溶液浓度，以铬黑T作指示剂，滴加1∶1氨水的目的是什么？加入氨性缓冲溶液的目的是什么？"},{"t":"p","text":"滴加1∶1氨水是为了调节溶液酸度，使Zn²⁺在弱碱性条件下与铬黑T形成酒红色配合物，同时防止酸度过高影响配合物形成；加入pH 10氨性缓冲溶液是为了将滴定体系稳定控制在pH≈10，保证EDTA与Zn²⁺定量配位并使铬黑T终点颜色变化敏锐。"},{"t":"h","text":"Q 用锌标准溶液标定EDTA溶液浓度，若用二甲酚橙作指示剂，应控制体系的酸度是什么范围？如何控制？"},{"t":"p","text":"用二甲酚橙作指示剂时，一般控制溶液pH在5～6左右。可用六亚甲基四胺缓冲溶液或乙酸-乙酸钠缓冲溶液控制酸度，终点时溶液由紫红色变为亮黄色。"},{"t":"h","text":"Q 用锌标准溶液标定EDTA溶液浓度，若用铬黑T或二甲酚橙作指示剂，这些金属指示剂指示终点的作用原理是什么？终点颜色如何变化？"},{"t":"p","text":"金属指示剂在滴定前与金属离子形成有色配合物，溶液呈现该配合物的颜色；滴定过程中EDTA逐渐夺取金属离子，临近终点时EDTA置换出指示剂，溶液变为游离指示剂的颜色。铬黑T终点由酒红色变为纯蓝色；二甲酚橙终点由紫红色变为亮黄色。"},{"t":"h","text":"Q 若分别用纯金属锌或基准物质作基准物质标定EDTA浓度，根据标定结果，如何计算EDTA的浓度？"},{"t":"p","text":"若用纯金属锌配制锌标准溶液，则c(EDTA)=c(Zn²⁺)×V(Zn²⁺)/V(EDTA)。若用基准物质如ZnO或CaCO₃等，先根据称取质量和摩尔质量计算其物质的量，再由计量比1∶1计算EDTA物质的量，最后除以消耗的EDTA体积得到c(EDTA)。"}],"count":5,"qa":[{"q":"什么情况下用倾析法、常压过滤、减压过滤？","a":"倾析法适合颗粒大、易沉降的固液分离，先倒出上层清液；常压过滤适合一般沉淀分离；减压过滤适合晶体颗粒较大、需要快速抽干的分离，细胶体沉淀容易堵塞滤纸，不宜减压过滤。"},{"q":"蒸发浓缩硫酸铜溶液时为什么要水浴加热？","a":"水浴受热均匀、温度易控，可避免直接加热造成局部过热、液滴飞溅和晶体溅失，也能防止蒸发皿骤热开裂。溶液表面出现晶膜即应停止加热。"},{"q":"铜粉灼烧为什么要反复“研碎—灼烧”三次？","a":"铜粉颗粒内部在首次灼烧时可能未完全氧化，研碎后暴露新鲜表面再灼烧，可使氧化更彻底。氧化不完全会导致后续酸溶残留、产率偏低。"},{"q":"重结晶提纯的原理是什么？为什么要按每克粗产品加 1.2 mL 水？","a":"利用目标物与杂质在溶剂中溶解度随温度变化差异：高温溶解、低温析晶，杂质留在母液中。加水量太少溶解不完全，太多则收率降低，1.2 mL/g 是兼顾溶解与收率的经验值。"},{"q":"产率与收率有什么区别？","a":"产率 = 实际产量 ÷ 理论产量 × 100%，理论产量按 3 g 铜全部转化估算；收率侧重实际得到的合格产品比例。两者都反映操作损失，偏差大时应回查过滤、转移、结晶各步。"},{"q":"含铜废液应该怎么处理？","a":"废硫酸铜溶液、母液、洗涤液均属重金属废液，必须倒入指定含铜废液回收桶，不得倒入水槽；含铜固体残渣单独收集，交由实验室统一处理。"}],"ai":true}],"qa":[{"q":"为什么滴定临近终点时要缓慢滴定并充分摇动？","a":"配位滴定反应速度较慢，尤其临近终点时游离金属离子浓度很低，若滴定过快，局部EDTA过量可能导致终点提前或颜色判断不准；充分摇动可加快反应并保证终点颜色变化均匀。"},{"q":"滴加1∶1氨水时出现白色沉淀，为什么之后又能继续滴定？","a":"滴加氨水至开始析出白色氢氧化锌沉淀，说明溶液酸度已降低到Zn²⁺开始沉淀的范围；随后加入pH 10氨性缓冲溶液，部分锌以配合物形式存在并保持与EDTA的反应活性，滴定过程中EDTA不断夺取Zn²⁺，沉淀可逐渐溶解，终点仍由铬黑T颜色变化指示。"},{"q":"铬黑T指示剂加入1～3滴即可，为什么不宜多加？","a":"铬黑T本身为有机染料，加入过多会使终点颜色过深，影响酒红色到纯蓝色的颜色判断；同时指示剂过多会消耗少量金属离子，使终点产生误差。"},{"q":"平行滴定几次结果相差较大，可能有哪些原因？","a":"可能原因包括：滴定管未润洗或存在气泡；移液管放液不准确；终点颜色判断不一致；滴定速度过快、摇动不充分；缓冲溶液加入量不一致；锥形瓶未洗净等。应规范操作并取平均结果。"},{"q":"如何根据实验数据计算EDTA溶液的浓度？","a":"锌标准溶液与EDTA按1∶1计量关系反应，故c(EDTA)=c(Zn²⁺)×V(Zn²⁺)/V(EDTA)。其中V(Zn²⁺)为移取的锌标准溶液体积，V(EDTA)为滴定消耗的EDTA溶液体积，c(Zn²⁺)由称取纯锌的质量和定容体积计算得到。"}],"ai":true,"order":3,"hidden":true,"visibleAt":"","feedbackUrl":""},"analytical/e04":{"id":"e04","no":4,"name":"醋酸含量的测定","full":"醋酸含量的测定","cards":[{"id":"safety","title":"安全教育","hint":"进实验室前先读完","blocks":[{"t":"kv","k":"通风操作","v":"醋酸易挥发，吸取、稀释和滴定应在通风良好处进行，避免吸入蒸气。"},{"t":"kv","k":"护目防护","v":"佩戴护目镜，防止酸碱溶液溅入眼睛；皮肤接触后立即用大量清水冲洗。"},{"t":"kv","k":"酸碱防护","v":"NaOH标准溶液具有腐蚀性，避免直接接触皮肤和衣物；若不慎沾到，先用大量水冲洗。"},{"t":"kv","k":"移液安全","v":"使用移液管时用洗耳球吸取，严禁用嘴吸；移液管尖端不要插入瓶底以免破损。"},{"t":"kv","k":"废液处理","v":"滴定废液集中回收，不得随意倒入水槽；酚酞乙醇溶液远离明火。"}],"count":5,"ai":true},{"id":"purpose","title":"实验目的","hint":"为什么做、依据是什么","blocks":[{"t":"p","text":"掌握强碱滴定弱酸的基本原理，理解化学计量点pH与指示剂选择之间的关系。"},{"t":"p","text":"学会用NaOH标准溶液直接滴定醋酸，以酚酞为指示剂判断终点，并由消耗体积计算醋酸含量。"},{"t":"p","text":"进一步练习滴定操作，做到滴定速度可控、终点判断准确、读数规范。"},{"t":"p","text":"初步掌握容量瓶和移液管的使用方法，能规范完成溶液的稀释与准确移取。"}],"count":4,"ai":true},{"id":"procedure","title":"实验流程","hint":"按顺序做什么","blocks":[{"t":"p","text":"检查滴定管是否洁净、活塞是否灵活，用NaOH标准溶液润洗滴定管2~3次，排除尖嘴气泡后调节液面至零刻度附近并记录初读数。"},{"t":"p","text":"用清洁的25 mL移液管吸取少量醋酸试液，淋洗移液管内壁2~3次，然后准确吸取25.00 mL醋酸试液，放入250 mL锥形瓶中。"},{"t":"p","text":"平行移取两份醋酸试液，分别置于两个250 mL锥形瓶中，各加入0.1%酚酞指示剂2~3滴，摇匀。"},{"t":"p","text":"用NaOH标准溶液滴定，开始时速度可稍快，接近终点时逐滴加入并不断摇动锥形瓶，观察溶液由无色变为微红色。"},{"t":"p","text":"当溶液呈浅红色且在摇匀后0.5 min内不再褪去时，即为终点，立即记录滴定管读数。"},{"t":"p","text":"按同样操作完成第二份试液的滴定，记录终点读数，并计算两次滴定所用NaOH溶液体积。"},{"t":"p","text":"根据NaOH标准溶液的浓度和消耗体积，计算醋酸试液的总酸度，以CH₃COOH的质量浓度（g·L⁻¹）表示，并比较两次结果。"}],"count":7,"ai":true},{"id":"thinking","title":"实验思考","hint":"做完再想一遍","blocks":[{"t":"h","text":"Q 测定醋酸为什么要用酚酞为指示剂？用甲基橙和中性红是否可以？为什么？"},{"t":"p","text":"强碱滴定弱酸的化学计量点pH约为8.7，落在酚酞变色范围（pH 8.2~10.0）内，故用酚酞。甲基橙变色范围pH 3.1~4.4，终点过早，结果偏低；中性红变色范围pH 6.8~8.0，也偏早，终点误差较大，故不适用。"},{"t":"h","text":"Q 草酸、柠檬酸、酒石酸等多元有机酸能否用NaOH溶液分步滴定？"},{"t":"p","text":"一般不能进行准确的分步滴定。多元有机酸各级解离常数相差不够大（通常需Ka₁/Ka₂≥10⁵才可分步），且滴定突跃不明显，NaOH会同时与多个质子反应，只能测得总酸度。"},{"t":"h","text":"Q 为什么NaOH溶液滴定醋酸结果以总酸度表示？"},{"t":"p","text":"市售醋酸中除CH₃COOH外还含有少量其他弱酸，滴定过程中NaOH同时与这些弱酸作用，消耗的碱量对应所有酸性组分，因此结果表示的是总酸度，以CH₃COOH的质量浓度计。"},{"t":"h","text":"Q 如何正确使用移液管？移液管中溶液放出后，管尖残留的溶液如何处理？"},{"t":"p","text":"先用待吸液润洗移液管内壁2~3次，用洗耳球吸取溶液至刻度以上，调节液面至刻度，保持管垂直、视线与刻度平齐。放液时管尖靠紧锥形瓶内壁，自然流下；管尖残留液不应吹入，因为移液管已按自然流出的体积校准。"}],"count":4,"qa":[{"q":"如何用离子积 Q 与 Ksp 的关系判断沉淀的生成与溶解？","a":"Q > Ksp 时生成沉淀，Q = Ksp 时达到饱和平衡，Q < Ksp 时沉淀溶解。改变溶液中某一离子的浓度，就会改变 Q，从而使平衡向生成或溶解的方向移动。"},{"q":"同离子效应如何影响难溶电解质的溶解度？","a":"加入含有相同离子的强电解质，会使溶解平衡向生成沉淀方向移动，溶解度降低。例如在 AgCl 饱和溶液中加入 NaCl，AgCl 的溶解度明显下降。"},{"q":"沉淀转化的方向由什么决定？","a":"由两种难溶物溶度积的相对大小决定：一般 Ksp 大的难溶物转化为 Ksp 小的难溶物，如 AgCl（白）→ AgI（黄）→ Ag₂S（黑）。转化能否发生还取决于两种沉淀剂浓度的相对大小。"},{"q":"为什么测定 Ksp 时必须恒温并取上层清液？","a":"难溶电解质的溶解度随温度变化，必须恒温静置使体系达到平衡；取上层清液可避免吸入底部固体。若吸入固体，测得的溶液浓度偏高，Ksp 计算结果偏大。"},{"q":"为什么不同电解质类型的 Ksp 不能直接比较？","a":"Ksp 与溶解度 S 的换算关系随电解质类型不同：AB 型 Ksp = S²，A₂B 型 Ksp = 4S³。只有同类型电解质才能用 Ksp 直接比较溶解度大小。"},{"q":"配位溶解为什么能使沉淀溶解？","a":"配位剂与沉淀中的金属离子生成稳定配离子，使金属离子浓度大幅降低，Q < Ksp，沉淀随之溶解。例如 AgCl 可溶于氨水生成 [Ag(NH₃)₂]⁺。"}],"ai":true}],"qa":[{"q":"滴定终点浅红色在0.5 min内褪去，能否直接读数？","a":"不能。应继续滴加NaOH至浅红色保持0.5 min不褪去，再记录读数；否则终点未到，结果偏低。"},{"q":"滴定过程中溶液出现深红色，应如何处理？","a":"说明NaOH过量，结果会偏高。该次数据应弃去，重新移取试液滴定；接近终点时应逐滴加入并充分摇匀。"},{"q":"为什么移液管要用待吸液润洗，而锥形瓶不用？","a":"移液管润洗是为了消除管内残留水对试液浓度的稀释；锥形瓶只需洁净，不能润洗，否则瓶内试液量会增多，导致结果偏高。"},{"q":"醋酸挥发对测定结果有何影响？如何减小？","a":"醋酸挥发会使试液中醋酸含量降低，测定结果偏小。应缩短操作时间，吸取和稀释时避免剧烈摇动，及时加盖或尽快滴定。"},{"q":"两次平行滴定结果相差较大，可能原因有哪些？","a":"可能原因包括：移液管未润洗或放液不规范、滴定管读数误差、终点判断不一致、滴定速度过快、锥形瓶未摇匀、醋酸挥发等。应规范操作并重新平行测定。"}],"ai":true,"order":4,"hidden":true,"visibleAt":"","feedbackUrl":""},"analytical/e05":{"id":"e05","name":"分析基础练习","cards":[{"id":"safety","title":"安全教育","hint":"进入实验室前先读完","blocks":[{"t":"kv","k":"电子天平","v":"电子天平应放置在稳固、防震、防尘且无阳光直射的实验台上，避免气流干扰；称量易挥发或腐蚀性物质时必须加盖密闭，防止吸入或腐蚀皮肤。"},{"t":"kv","k":"容量瓶禁忌","v":"严禁在容量瓶内溶解固体或加热容量瓶，以免玻璃膨胀破裂划伤手部；碱性溶液不可在容量瓶中久存，配好后应及时转移到塑料瓶等合适容器中，防止磨口玻璃塞粘连和瓶口碎裂。"},{"t":"kv","k":"滴定管选择与检漏","v":"酸式滴定管装酸，碱式滴定管装碱，强氧化剂如高锰酸钾不得用碱式管，以免腐蚀乳胶管漏液；滴定前必须严格检漏，滴定过程中左手不能离开活塞任其自流，摇瓶不可过猛。"},{"t":"kv","k":"移液管检查","v":"使用移液管前必须仔细检查管口和尖嘴是否有破损或裂痕，以免划伤手部或将玻璃碎屑引入溶液；移液管须用待装液润洗，装液后排尽尖嘴气泡。"},{"t":"kv","k":"个体防护与溅洒","v":"滴定腐蚀性或毒性试剂时，有条件必须全程佩戴护目镜和防腐蚀手套；一旦发生酸碱溅洒，应立即用大量清水冲洗，并根据需要进行中和处理。"},{"t":"kv","k":"废液处理","v":"实验废液应倒入指定废液桶，不得随意倾倒；破损玻璃器皿和老化乳胶管应及时更换处理，避免碱液漏出造成灼伤。"},{"t":"p","text":"总结：本实验主要风险为酸碱腐蚀、玻璃器皿破裂划伤、易挥发腐蚀试剂吸入及滴定管漏液灼伤，须佩戴护目镜和防腐蚀手套、严格检漏润洗并规范处理废液。"}],"count":7},{"id":"purpose","title":"实验目的","hint":"为什么做、依据是什么","blocks":[{"t":"p","text":"练习电子天平的规范使用，掌握准确称取氯化钠0.5 g并称准至0.0001 g的操作，理解称量容器、加盖密闭和防气流干扰对结果的影响。"},{"t":"p","text":"练习容量瓶、移液管和滴定管的使用方法，包括定容、润洗、装液、排尽尖嘴气泡、检漏以及视线与凹液面最低点水平读数并估读至小数点后两位。"},{"t":"p","text":"通过配制100 mL氯化钠溶液、500 mL 0.1 mol·L⁻¹氢氧化钠溶液和500 mL 0.1 mol·L⁻¹盐酸溶液，掌握由质量或浓溶液体积计算目标浓度的方法。"},{"t":"p","text":"用盐酸和氢氧化钠溶液互相滴定，以甲基红为指示剂判断终点颜色变化，记录消耗体积并计算浓度，了解实验数据记录和有效数字保留方法。"}],"count":4},{"id":"procedure","title":"实验流程","hint":"怎么做、注意什么","blocks":[{"t":"p","text":"准确称取氯化钠0.5 g，称准至0.0001 g，转移至150 mL烧杯中，加入30 mL蒸馏水溶解后，定容于100 mL容量瓶中，摇匀，计算氯化钠溶液的浓度。"},{"t":"p","text":"计算配制500 mL 0.1 mol·L⁻¹氢氧化钠溶液所需固体氢氧化钠质量：m=0.1×0.500×40=2.0 g；在托盘天平上快速称取，放入100 mL烧杯中，加50 mL蒸馏水溶解。"},{"t":"p","text":"将氢氧化钠溶液转移至500 mL试剂瓶中，再用50 mL蒸馏水淋洗烧杯两次，洗液倒入试剂瓶中，用蒸馏水稀释至500 mL，摇匀。"},{"t":"p","text":"计算配制500 mL 0.1 mol·L⁻¹盐酸所需浓盐酸体积：V=0.1×0.500÷12≈0.00417 L≈4.17 mL；用量杯量取浓盐酸，倒入试剂瓶中，用蒸馏水稀释至500 mL，摇匀。"},{"t":"p","text":"用25 mL移液管吸取氢氧化钠溶液25.00 mL，放入250 mL锥形瓶中，加入甲基红指示剂3滴，用盐酸滴定至由黄色变为微红色，记录消耗盐酸的体积V(HCl)。"},{"t":"p","text":"用25 mL移液管吸取盐酸25.00 mL，放入250 mL锥形瓶中，加入甲基红指示剂3滴，用氢氧化钠溶液滴定至由红色变为黄色，记录消耗氢氧化钠溶液的体积V(NaOH)。"},{"t":"p","text":"滴定管和移液管均须用待装液润洗，装液后排尽尖嘴气泡；读数时视线与凹液面最低点水平，估读至小数点后两位；实验后废液倒入指定废液桶。"},{"t":"img","src":"assets/emwrj80rh/img1.png","caption":""},{"t":"img","src":"assets/emwrj80rh/img2.png","caption":""}],"count":9},{"id":"thinking","title":"实验思考","hint":"想清楚再动手","blocks":[{"t":"h","text":"Q 为什么严禁在容量瓶内溶解固体或加热容量瓶？"},{"t":"p","text":"容量瓶是精密定容用玻璃量器，受热或局部溶解易使玻璃膨胀不均而破裂，划伤手部并影响体积准确度；固体应在烧杯中溶解并冷却后再转移定容。"},{"t":"h","text":"Q 滴定管和移液管为什么必须用待装液润洗？"},{"t":"p","text":"若不用待装液润洗，残留蒸馏水会稀释待装溶液，使滴定剂或待测液浓度偏低，导致消耗体积和计算结果偏差；润洗可保证器皿内溶液浓度与试剂瓶一致。"},{"t":"h","text":"Q 如何计算配制500 mL 0.1 mol·L⁻¹氢氧化钠溶液和盐酸溶液所需原料量？"},{"t":"p","text":"氢氧化钠：m=0.1×0.500×40=2.0 g；盐酸：浓盐酸约12 mol·L⁻¹，V=0.1×0.500÷12≈0.00417 L≈4.17 mL，实际量取后稀释至500 mL并摇匀。"},{"t":"h","text":"Q 甲基红指示剂在酸碱互滴中终点颜色如何变化？"},{"t":"p","text":"用盐酸滴定氢氧化钠时，溶液由黄色变为微红色即为终点；用氢氧化钠滴定盐酸时，溶液由红色变为黄色即为终点，应控制半滴操作并记录消耗体积。"},{"t":"h","text":"Q 滴定读数为什么要求视线与凹液面最低点水平并估读至小数点后两位？"},{"t":"p","text":"视线不平会产生视差，使读数偏大或偏小；滴定管最小分度通常为0.1 mL，需估读至0.01 mL，以正确保留有效数字并减小体积误差。"}],"count":5}],"qa":[{"q":"称取氯化钠时为什么要称准至0.0001 g，而配制氢氧化钠时可在托盘天平上快速称取？","a":"氯化钠用于准确配制并计算浓度，需用电子天平称准至0.0001 g；氢氧化钠易吸潮且与空气中二氧化碳反应，只需快速称取约2.0 g并实际记录质量，后续以滴定结果为准。"},{"q":"浓盐酸量取时应注意什么？","a":"浓盐酸易挥发且有腐蚀性，应在通风条件下用量杯量取，避免吸入酸雾；量取后沿器壁倒入试剂瓶并稀释至500 mL，摇匀，废液不得随意倾倒。"},{"q":"移液管吸取25.00 mL溶液前要做哪些检查？","a":"检查管口和尖嘴有无破损或裂痕，避免划伤和玻璃碎屑进入溶液；用待装液润洗2至3次，吸取时排尽尖嘴气泡，放液后按规范等待液体流下。"},{"q":"滴定前如何检漏和排气泡？","a":"酸式管检查活塞是否灵活漏液，碱式管检查乳胶管和玻璃珠是否老化漏液；装液后用待装液润洗，打开活塞或挤压乳胶管使尖嘴气泡排尽，再调节液面至零刻度附近读数。"},{"q":"滴定过程中摇动锥形瓶和读数的规范是什么？","a":"摇动锥形瓶应沿同一方向平稳旋转，不可用力过猛以防液体溅出；读数时视线与凹液面最低点水平，估读至小数点后两位，滴定过程中左手不能离开活塞任其自流。"}],"full":"分析基础练习","ai":true,"no":5,"order":0,"hidden":false,"visibleAt":"","feedbackUrl":""},"analytical/e06":{"id":"e06","name":"EDTA配标+水的硬度","cards":[{"id":"safety","title":"安全教育","hint":"进入实验室前先读完","blocks":[{"t":"kv","k":"氨水防护","v":"1:1氨水及pH≈10氨性缓冲液挥发性强、有刺激性和腐蚀性，取用和滴加应在通风处进行，防止吸入氨气或溅入眼、皮肤。"},{"t":"kv","k":"盐酸与锌","v":"1:1盐酸强腐蚀，溶解锌时做好眼手防护，缓慢加酸防飞溅；如需加热须小火并防暴沸溅出。"},{"t":"kv","k":"玻璃仪器","v":"酸式滴定管、移液管、容量瓶、锥形瓶轻拿轻放，破损立即报告；移液管必须用洗耳球吸取，严禁用嘴吸。"},{"t":"kv","k":"滴定操作","v":"滴定速度不宜过快，临近终点更应缓慢滴定并充分摇动；摇锥形瓶作同一方向圆周运动，防止溶液溅出。"},{"t":"kv","k":"废液与防护","v":"含锌、含氨及含铬黑T废液倒入指定废液桶，不得直接入下水道；全程穿实验服，尽量佩戴护目镜，结束洗手。"},{"t":"p","text":"总结：本实验主要风险是氨水和盐酸的刺激腐蚀、玻璃仪器破损及滴定溅液，应在通风处操作、做好眼手防护、规范使用洗耳球并分类回收废液。"}],"count":6},{"id":"purpose","title":"实验目的","hint":"为什么做、依据是什么","blocks":[{"t":"p","text":"学习EDTA标准溶液的配制和标定方法，掌握配位滴定的基本原理。"},{"t":"p","text":"了解铬黑T指示剂的应用及终点由酒红色变为纯蓝色的颜色变化，并学会用Zn或ZnSO₄基准物标定EDTA。"},{"t":"p","text":"学习EDTA直接滴定法测定水的总硬度，掌握pH≈10氨性缓冲溶液和铬黑T指示剂的使用。"},{"t":"p","text":"了解水硬度的意义和表示法，掌握以CaO mg·L⁻¹表示总硬度的计算方法。"}],"count":4},{"id":"procedure","title":"实验流程","hint":"怎么做、注意什么","blocks":[{"t":"p","text":"配制0.02 mol·L⁻¹ EDTA溶液300 mL：称取乙二胺四乙酸二钠2.23 g，置于150 mL烧杯中，加50 mL蒸馏水溶解，移入500 mL试剂瓶，用蒸馏水稀释至总体积300 mL，摇匀。"},{"t":"p","text":"配制锌标准溶液：准称0.33~0.34 g纯金属锌或约0.9 g ZnSO₄，加5 mL 1:1 HCl溶解后定容250 mL，计算准确浓度；用纯锌时c(Zn)=m/(65.38×0.250)。"},{"t":"p","text":"标定：用移液管吸取25.00 mL锌标准溶液于250 mL锥形瓶，滴加1:1氨水至开始析出白色Zn(OH)₂沉淀，加pH≈10氨性缓冲溶液10 mL、水20 mL、铬黑T指示剂1~3滴。"},{"t":"p","text":"用EDTA溶液滴定，溶液由酒红色变为纯蓝色为终点，临近终点缓慢滴定并充分摇动，记录V(EDTA)；平行滴定后按c(EDTA)=c(Zn)×25.00/V(EDTA)计算。"},{"t":"p","text":"水样测定：用移液管准确量取澄清的水样100 mL于锥形瓶，加5 mL pH≈10氨性缓冲溶液摇匀，再加3~4滴0.5%铬黑T指示剂。"},{"t":"p","text":"用已标定EDTA标准溶液滴定至酒红色变为纯蓝色，记录V(EDTA)；各次滴定尽量控制在滴定管同一刻度部位，摇瓶作同一方向圆周运动。"},{"t":"p","text":"计算：总硬度(CaO mg·L⁻¹)=c(EDTA)×V(EDTA)×56.08×10³/V(水)，其中V(水)为所取水样体积mL。"},{"t":"table","rows":[["AI计算器"],["具体步骤","EDTA溶液标配和水的总硬度测定"]],"header":true},{"t":"img","src":"assets/emwrje8pd/img1.png","caption":""}],"count":9},{"id":"thinking","title":"实验思考","hint":"想清楚再动手","blocks":[{"t":"h","text":"Q 配制EDTA标准溶液时为什么常用乙二胺四乙酸二钠盐而不用乙二胺四乙酸？"},{"t":"p","text":"乙二胺四乙酸在水中溶解度小，而二钠盐溶解度较大，室温下约11.1 g·(100 mL)⁻¹，且含2个结晶水，相对分子质量为372.26，便于称量和配制成标准溶液。"},{"t":"h","text":"Q 用锌标准溶液标定EDTA时，滴加1:1氨水和加入pH≈10氨性缓冲溶液的目的分别是什么？"},{"t":"p","text":"滴加1:1氨水是中和过量酸并调节溶液至碱性，至开始析出白色Zn(OH)₂沉淀可指示接近所需pH；加入氨性缓冲溶液是维持滴定过程pH≈10，保证Zn²⁺与EDTA配位完全并使铬黑T终点灵敏。"},{"t":"h","text":"Q 若用二甲酚橙作指示剂标定EDTA，应控制什么酸度？如何控制？终点颜色如何变化？"},{"t":"p","text":"一般控制pH≈5~6，可用六亚甲基四胺或乙酸-乙酸钠缓冲溶液控制；终点时溶液由紫红色变为亮黄色。"},{"t":"h","text":"Q 铬黑T和二甲酚橙等金属指示剂指示终点的原理是什么？"},{"t":"p","text":"金属指示剂先与金属离子形成酒红色或紫红色配合物，EDTA夺取金属离子后指示剂被游离出来，呈现自身颜色；铬黑T终点由酒红色变为纯蓝色，二甲酚橙终点由紫红色变为亮黄色。"},{"t":"h","text":"Q 水的总硬度如何表示和计算？1°的含义是什么？"},{"t":"p","text":"总硬度常用CaO mg·L⁻¹表示，公式为总硬度=c(EDTA)×V(EDTA)×56.08×10³/V(水)；1°表示1 L水中含10 mg CaO。"}],"count":5}],"qa":[{"q":"移液管为什么必须用洗耳球吸取溶液？","a":"防止氨水、锌标准溶液或水样进入口中，保证人身安全，同时避免口吸造成体积不准和污染。"},{"q":"标定EDTA和测定水样时为什么都要加入pH≈10氨性缓冲溶液？","a":"维持滴定体系pH≈10，使Zn²⁺或Ca²⁺、Mg²⁺与EDTA配位完全，并保证铬黑T显色和终点颜色变化灵敏。"},{"q":"滴定临近终点时为什么不能太快？","a":"EDTA配位反应速度较慢，临近终点应缓慢滴定并充分摇动，避免局部过量造成终点判断提前或颜色不稳定。"},{"q":"水样中含少量Fe³⁺、Al³⁺时是否有干扰？如何消除？","a":"有干扰，它们会消耗EDTA或封闭铬黑T指示剂；少量时可加三乙醇胺等掩蔽剂掩蔽，必要时采用分离或其他掩蔽方法。"},{"q":"为什么各次滴定尽量控制在滴定管刻度的同一部位？","a":"可使滴定管刻度不准引起的误差相互抵消，提高平行测定结果的精密度。"},{"q":"铬黑T终点颜色如何判断？","a":"计量点前Ca²⁺、Mg²⁺或Zn²⁺与铬黑T形成酒红色配合物，滴定至终点时游离出指示剂，溶液呈纯蓝色，且摇匀后颜色稳定。"}],"full":"EDTA溶液配制与标定+水的硬度","ai":true,"no":6,"order":0,"hidden":false,"visibleAt":"","feedbackUrl":""},"analytical/e07":{"id":"e07","name":"NaOH标配与醋酸测定","cards":[{"id":"safety","title":"安全教育","hint":"进入实验室前先读完","blocks":[{"t":"h","text":"一．安全注意事项","level":2},{"t":"p","text":"1.严禁在容量瓶内溶解固体或加热容量瓶，以免玻璃膨胀破裂划伤手部。"},{"t":"p","text":"2.碱性溶液不可在容量瓶中久存，配好后必须及时转移到塑料瓶等合适容器中。强碱性溶液会腐蚀玻璃，导致磨口玻璃塞粘连，强行拧开极易导致瓶口碎裂、划伤手部。"},{"t":"p","text":"3.碱式滴定管绝对不能盛装酸性或强氧化性溶液（如高锰酸钾等），否则会迅速腐蚀橡胶管，导致溶液大量漏出，引发化学灼伤。"},{"t":"p","text":"4.滴定前必须严格检漏。滴定过程中，左手不能离开活塞任其自流，摇动锥形瓶时不可用力过猛，防止液体溅出腐蚀皮肤或衣物。"},{"t":"p","text":"5.滴定具有腐蚀性或毒性的试剂时，在有条件的情况下必须全程佩戴护目镜和防腐蚀手套。一旦发生酸碱溅洒，应立即用大量清水冲洗，并根据需要进行中和处理。"},{"t":"p","text":"6.使用移液管前必须仔细检查管口和尖嘴是否有破损或裂痕，以免在操作中划手部，或将玻璃碎屑引入溶液中造成危险。"},{"t":"h","text":"二．NaOH标准溶液的配置","level":2},{"t":"h","text":"3.注意事项","level":2},{"t":"p","text":"（1）氢氧化钠极易吸潮，因而称量速度要尽量快。"},{"t":"p","text":"(2)滴定前，应检查橡胶管内和滴定管尖处是否有气泡，如有气泡应排除，否则会影响读数，给测定带来误差。"},{"t":"h","text":"3.注意事项：","level":2},{"t":"p","text":"（1） 吸取、称量醋酸，以及稀释醋酸时要考虑到醋酸的强挥发性，醋酸的挥发会导致测出的醋酸含量偏小。"},{"t":"p","text":"（2）在控制滴定管滴定氢氧化钠溶液时，要控制好滴定的速度，使得溶液的液面为浅红色，如果液面为红色，甚至是深红色，则会影响测出的结果，导致测出的醋酸含量偏大。"}],"count":10},{"id":"purpose","title":"实验目的","hint":"为什么做、依据是什么","blocks":[{"t":"p","text":"分析实验四十：NaOH溶液标配和醋酸含量测定"},{"t":"h","text":"1.实验目的","level":2},{"t":"p","text":"（1）学会配制和标定 NaOH标准溶液的方法；"},{"t":"p","text":"（2） 练习碱式滴定管的滴定操作，学会观察和判断滴定终点。"},{"t":"h","text":"1.实验目的：","level":2},{"t":"p","text":"（1）掌握强碱滴定弱酸的原理；"},{"t":"p","text":"（2）进一步练习滴定操作，初步掌握容量瓶、移液管的使用方法。"},{"t":"p","text":"实验步骤：用清洁的25mL 移液管吸取少许醋酸试液，淋洗移液管内壁2~3次，然后吸取两份试液分别置于250 mL 锥形瓶中，加入酚酞指示剂2~3滴，用 NaOH 标准溶液滴定至浅红色，在0.5 min内不再褪去，即为终点。"}],"count":6},{"id":"procedure","title":"实验流程","hint":"怎么做、注意什么","blocks":[{"t":"h","text":"2.实验步骤","level":2},{"t":"p","text":"（1)配制 400 mL  NaOH 溶液。预先算出配制400mL 0.1 的NaOH 溶液所需固体NaOH的质量，然后在托盘天平上快速称取，放入100mL 烧杯中，加50mL 蒸馏水溶解后，转移至500mL 试剂瓶中，再用50mL蒸馏水淋洗烧杯两次，倒人试剂瓶中，最后用蒸馏水稀释至400 mL 左右，塞紧橡胶塞，摇匀，待用（贴上标签，写上姓名）。"},{"t":"p","text":"（2）在分行天平上准确称取邻苯二甲酸氢钾0.5 g（称准至0.0001g） 两份，分别加入250 mL 锥形瓶中，各加50mL 煮沸后刚冷却的蒸馏水溶解（若溶解不完，可微热、冷却），加入2 滴酚酞指示剂，用自己配制的 NaOH 溶液滴定至微红色在0.5 min 内不褪色即为终点，记下消耗的NaOH 体积（mL）。根据所消耗的 NaOH 溶液的体积和邻苯二甲酸氢钾的质量计算 NaOH 的准确浓度。"},{"t":"img","src":"assets/emwrjb7vk/img1.png","caption":""},{"t":"img","src":"assets/emwrjb7vk/img2.png","caption":""},{"t":"img","src":"assets/emwrjb7vk/img3.png","caption":""},{"t":"img","src":"assets/emwrjb7vk/img4.png","caption":""},{"t":"img","src":"assets/emwrjb7vk/img5.png","caption":""},{"t":"img","src":"assets/emwrjb7vk/img6.png","caption":""},{"t":"img","src":"assets/emwrjb7vk/img7.png","caption":""},{"t":"img","src":"assets/emwrjb7vk/img8.png","caption":""}],"count":10},{"id":"thinking","title":"实验思考","hint":"想清楚再动手","blocks":[{"t":"h","text":"4.实验思考","level":2},{"t":"p","text":"（1）能否在分析天平上准确称取固体 NaOH直接配制成标准溶液？为什么？"},{"t":"p","text":"（2）滴定管在装标准溶液前为什么要用此标准溶液淋洗2~3次？"},{"t":"p","text":"（3）配制 NaOH溶液用的蒸馏水体积，是否需要准确量取？为什么？"},{"t":"p","text":"（4）溶解基准物邻苯二甲酸氢钾所用的水的体积，是否需要准确量取？为什么？"},{"t":"p","text":"AI辅助计算NaOH溶液浓度及误差分析"},{"t":"h","text":"1、打开手机扫一扫；","level":2},{"t":"p","text":"2、浓度计算板块：输入所消耗的NaOH 溶液体积（单位：mL）即可得到其浓度。"},{"t":"p","text":"3、误差分析板块：输入所消耗的NaOH 溶液体积，可得到简单的误差分析结果。"},{"t":"p","text":"注意：邻苯二甲酸氢钾的质量 默认值为0.5000g，如果需要可修改。"},{"t":"p","text":"计算公式：CNaOH = (mKHP × 1000) / (MKHP × VNaOH)"},{"t":"h","text":"三．醋酸含量的测定","level":2},{"t":"h","text":"4.实验思考：","level":2},{"t":"p","text":"（1）测定醋酸为什么要用酚酞为指示剂？用甲基橙和中性红是否可以？为什么？"},{"t":"p","text":"（2）草酸、柠檬酸、酒石酸等多元有机酸能否用 NaOH 溶液分步滴定？"},{"t":"p","text":"（3）为什么 NaOH 溶液滴定醋酸结果以总酸度表示？"},{"t":"p","text":"（4）如何正确使用移液管？移液管中溶液放出后，管尖残留的溶液如何处理？"},{"t":"p","text":"AI辅助计算醋酸含量"},{"t":"h","text":"1.打开手机扫一扫；","level":2},{"t":"p","text":"2.输入实验一中已标定的NaOH溶液准确浓度以及本次标定醋酸试液的NaOH溶液体积"},{"t":"h","text":"3.点击 “计算醋酸含量”按钮，即可得出计算结果。","level":2},{"t":"p","text":"计算公式：醋酸含量(g/L) = (CNaOH×VNaOH×MHAc) / V酸样"},{"t":"p","text":"CNaOH: NaOH标准溶液浓度 (mol/L)"},{"t":"p","text":"VNaOH: 消耗NaOH溶液体积 (mL)"},{"t":"p","text":"MHAc: 醋酸的摩尔质量 (60.05 g/mol)"},{"t":"p","text":"V酸样: 醋酸试液取样体积 (mL)"}],"count":20}],"qa":[],"full":"NaOH标准溶液配制与标定及醋酸含量的测定","ai":false,"no":7,"order":0,"hidden":false,"visibleAt":"","feedbackUrl":""},"analytical/e08":{"id":"e08","no":10,"name":"过氧化氢含量的测定","order":6,"full":"实验四十九 过氧化氢含量的测定","hidden":false,"visibleAt":"","ai":true,"qa":[{"q":"用什么酸控制酸度？为什么？","a":"稀 H₂SO₄。HNO₃ 有氧化性，HCl 的 Cl⁻ 与 KMnO₄ 反应，均会干扰测定。"},{"q":"本实验为何不能用加热加速？","a":"H₂O₂ 受热分解，含量减少导致结果偏低。"},{"q":"滴定开始很慢是异常吗？","a":"正常。Mn²⁺ 是自催化剂，开始无 Mn²⁺ 反应慢，生成后逐渐加快。"},{"q":"终点为什么是微红色 1 min 不消失？","a":"KMnO₄ 稍过量即显粉红色；空气中还原性物质会使其慢慢褪色，1 min 不褪即到终点。"},{"q":"取样用什么仪器？","a":"25.00 mL 移液管，保证体积准确（数据带两位小数）。"}],"cards":[{"id":"safety","title":"安全教育","hint":"进实验室前先读完","blocks":[{"t":"h","text":"本实验安全要点","level":3},{"t":"kv","k":"过氧化氢","v":"30% 原液强腐蚀性，稀释取用时防溅；溅到皮肤立即大量流水冲洗。"},{"t":"kv","k":"禁止加热","v":"H₂O₂ 受热易分解，本实验全程不需加热，操作区远离热源。"},{"t":"kv","k":"稀硫酸","v":"3 mol/L H₂SO₄ 具腐蚀性，沿壁加入并轻摇。"},{"t":"kv","k":"KMnO₄","v":"强氧化剂且染色，溅到皮肤形成棕色斑，立即用水冲洗。"},{"t":"kv","k":"气泡","v":"反应放出 O₂，滴定不要过快，防溶液随气泡冲出锥形瓶。"},{"t":"kv","k":"废液","v":"含锰废液倒入指定回收桶，不得倒入水槽。"}],"count":6},{"id":"purpose","title":"实验目的","hint":"为什么做、依据是什么","blocks":[{"t":"p","text":"掌握高锰酸钾法测定过氧化氢含量的原理和方法。"},{"t":"p","text":"在稀 H₂SO₄ 中，H₂O₂ 室温下能定量还原 KMnO₄，反应式："},{"t":"p","text":"2MnO₄⁻ + 5H₂O₂ + 6H⁺ = 2Mn²⁺ + 5O₂↑ + 8H₂O"},{"t":"p","text":"KMnO₄ 自身指示终点，滴至微红色 1 min 不消失即可。"}],"count":4},{"id":"procedure","title":"实验流程","hint":"按顺序做什么","blocks":[{"t":"kv","k":"取样","v":"移液管吸取过氧化氢试液 25.00 mL 两份，分别放入 250 mL 锥形瓶。"},{"t":"kv","k":"酸化","v":"各加 25 mL 蒸馏水、15 mL 3 mol/L H₂SO₄ 溶液，摇匀。"},{"t":"kv","k":"滴定","v":"用 KMnO₄ 标准溶液滴定，开始反应慢，待 Mn²⁺ 生成后速率加快；滴至微红色 1 min 不消失为终点，记录体积。"},{"t":"kv","k":"平行","v":"同法滴定第二份，两次体积偏差合格后取平均值。"},{"t":"h","text":"计算","level":3},{"t":"kv","k":"计算式","v":"ρ(H₂O₂) = 2.5 × c(KMnO₄) × V(KMnO₄) × M(H₂O₂) ÷ V(试样)，M(H₂O₂)=34.02 g/mol。"},{"t":"kv","k":"AI 工具","v":"扫码输入消耗体积等数据，直接得含量、计算过程与误差分析（二维码见讲义 AI 衔接部分）。"},{"t":"fig","src":"assets/h06/img1.jpg","caption":"图 1　AI 计算工具二维码：扫码输入滴定数据，得含量、计算过程与误差分析"},{"t":"fig","src":"assets/h06/img2.png","caption":"图 2　计算工具示例：含量测定计算与结果"},{"t":"fig","src":"assets/h06/img3.png","caption":"图 3　计算工具数据输入界面"}],"count":9},{"id":"thinking","title":"实验思考","hint":"做完再想一遍","blocks":[{"t":"h","text":"能否用 HNO₃ 或 HCl 控制酸度？","level":3},{"t":"p","text":"不能。HNO₃ 有氧化性，会氧化 H₂O₂；Cl⁻ 会与 KMnO₄ 反应消耗滴定剂，两者都影响结果。"},{"t":"h","text":"为什么最初反应慢，之后越来越快？","level":3},{"t":"p","text":"生成的 Mn²⁺ 对该反应有催化作用，属于自催化反应，随 Mn²⁺ 积累速率加快。"},{"t":"h","text":"为什么不能加热加速反应？","level":3},{"t":"p","text":"H₂O₂ 受热易分解，加热会使测定结果偏低。"},{"t":"h","text":"终点如何判断？","level":3},{"t":"p","text":"微红色 1 min 内不消失即为终点，不需另加指示剂。"}],"count":4}],"feedbackUrl":""},"analytical/e09":{"id":"e09","no":8,"name":"铝盐中铝含量的测定","order":7,"full":"实验四十七 铝盐中铝含量的测定","hidden":false,"visibleAt":"","ai":true,"qa":[{"q":"为什么用置换滴定而不用直接滴定？","a":"Al³⁺ 与 EDTA 配位慢且封闭指示剂；置换法通过释放等量 EDTA 间接准确滴定。"},{"q":"第一次紫色不计数的原理？","a":"它是回滴过量 EDTA 的体积，与铝无关；第二次滴定对应 NH₄F 置换出的 EDTA。"},{"q":"如何控制酸度？","a":"先用甲基橙 + 1:1 氨水调至橙色（pH≈3.5）使配位完全，再用六亚甲基四胺缓冲至 pH 5~6 滴定。"},{"q":"终点为什么呈紫色？","a":"稍过量的 Cu²⁺ 与 PAN 形成深红色 Cu-PAN，与蓝色 Cu-EDTA 叠加呈紫色。"},{"q":"为什么趁热滴定？","a":"加热加速 Al-EDTA 配位完全和置换反应，冷时反应慢终点不敏锐。"}],"cards":[{"id":"safety","title":"安全教育","hint":"进实验室前先读完","blocks":[{"t":"h","text":"本实验多处加热，安全要点","level":3},{"t":"kv","k":"电炉加热","v":"两次煮沸 2 min，垫石棉网小火加热，防暴沸溅出；仪器外壁擦干。"},{"t":"kv","k":"防烫","v":"趁热滴定，锥形瓶口有蒸汽，取拿垫毛巾或戴隔热手套。"},{"t":"kv","k":"1:1 盐酸","v":"挥发有刺激性，通风橱内取用，用后盖紧。"},{"t":"kv","k":"NH₄F","v":"氟化物有毒，称取后立即盖好瓶盖，勿吸入粉尘，操作后洗手。"},{"t":"kv","k":"PAN 乙醇液","v":"含乙醇易燃，滴加时远离电炉明火。"},{"t":"kv","k":"滴定管","v":"用酸式滴定管装 CuSO₄ 标准溶液。"},{"t":"kv","k":"废液","v":"含氟废液倒入指定回收桶，不得倒入水槽。"}],"count":7},{"id":"purpose","title":"实验目的","hint":"为什么做、依据是什么","blocks":[{"t":"p","text":"Al³⁺ 与 EDTA 配位速率很慢，且易封闭指示剂，不能用直接滴定法测定。"},{"t":"p","text":"采用置换滴定法：先加过量 EDTA 并煮沸使配位完全，用 CuSO₄ 返滴过量部分；再加 NH₄F，F⁻ 与 Al³⁺ 生成更稳定的 AlF₆³⁻，置换释放出与铝等物质的量的 EDTA，再用 CuSO₄ 滴定。"},{"t":"p","text":"终点颜色变化复杂：黄色（PAN）随 Cu-EDTA 蓝色出现渐变绿，终点呈紫色，须注意观察。"}],"count":3},{"id":"procedure","title":"实验流程","hint":"按顺序做什么","blocks":[{"t":"h","text":"一、试样制备","level":3},{"t":"kv","k":"称样定容","v":"准确称取硫酸铝钾 1 g（±0.0002 g），加 2 mL 1:1 HCl、30 mL 水溶解，定容至 100 mL。"},{"t":"kv","k":"铜标准液","v":"称 CuSO₄·5H₂O 约 5 g 溶于 1 L 水，用 EDTA 标准溶液标定。"},{"t":"h","text":"二、滴定","level":3},{"t":"kv","k":"配位","v":"吸试液 10.00 mL 两份，加 20 mL 水、20 mL 0.02 mol/L EDTA，甲基橙 1~2 滴，滴 1:1 氨水至橙色（pH≈3.5）。"},{"t":"kv","k":"第一次滴定","v":"加六亚甲基四胺 10 mL、PAN 4~5 滴，煮沸 2 min，趁热用 CuSO₄ 滴至紫色；此次体积不记，调回 0 刻度。"},{"t":"kv","k":"置换","v":"加入 NH₄F 1 g，加热煮沸 2 min。"},{"t":"kv","k":"第二次滴定","v":"再用 CuSO₄ 滴至紫色（可补加 PAN 3~4 滴），记录消耗体积；同法做第二份。"},{"t":"h","text":"三、计算","level":3},{"t":"kv","k":"计算式","v":"w(Al) = c(CuSO₄) × V(CuSO₄) × M(Al) ÷ [m × (10/100)]，M(Al)=26.98 g/mol。"},{"t":"kv","k":"AI 工具","v":"扫码输入数据得含量与误差分析；原理疑问可扫码用 AI 问答（二维码见讲义 AI 衔接部分）。"},{"t":"fig","src":"assets/h07/img1.png","caption":"图 1　AI 计算工具二维码：扫码输入数据得铝含量与误差分析"},{"t":"fig","src":"assets/h07/img2.png","caption":"图 2　AI 原理问答二维码：原理疑问可扫码问答"},{"t":"fig","src":"assets/h07/img3.png","caption":"图 3　计算工具示例：铝含量计算与结果"},{"t":"fig","src":"assets/h07/img4.png","caption":"图 4　AI 使用场景对话示例"},{"t":"fig","src":"assets/h07/img5.png","caption":"图 5　AI 原理问答示例"},{"t":"fig","src":"assets/h07/img6.png","caption":"图 6　讲义滴定数据记录表"}],"count":14},{"id":"thinking","title":"实验思考","hint":"做完再想一遍","blocks":[{"t":"h","text":"为什么不能用直接滴定法测铝？","level":3},{"t":"p","text":"Al³⁺ 与 EDTA 配位速率慢，且 Al³⁺ 对指示剂有封闭作用，直接滴定终点难以判断。"},{"t":"h","text":"第一次到达紫色的 CuSO₄ 体积为什么不记数？","level":3},{"t":"p","text":"它消耗的是过量的 EDTA，与铝含量无关；只有 NH₄F 置换释放的 EDTA 才对应铝的量。"},{"t":"h","text":"NH₄F 的作用是什么？","level":3},{"t":"p","text":"F⁻ 与 Al³⁺ 生成更稳定的 AlF₆³⁻，把 Al-EDTA 中的 EDTA 定量置换出来。"},{"t":"h","text":"含铁样品中 NH₄F 过量会怎样？","level":3},{"t":"p","text":"Fe-EDTA 中的 EDTA 也会被置换出来，使结果偏高；铁含量高时须先分离 Fe 再测。"}],"count":4}],"feedbackUrl":""},"analytical/e10":{"id":"e10","no":9,"name":"高锰酸钾标准溶液的配制与标定","order":5,"full":"实验四十八 高锰酸钾标准溶液的配制与标定","hidden":false,"visibleAt":"","ai":true,"qa":[{"q":"为什么 KMnO₄ 不能用直接法配制？","a":"纯度不足且浓度不稳定：与水中还原性物质作用、见光自行分解，只能配成近似浓度后用基准物质标定。"},{"q":"标定为什么选 Na₂C₂O₄ 作基准物质？","a":"不含结晶水、不易吸湿、易纯制、性质稳定，称量准确。"},{"q":"滴定为什么要在 75~85 ℃ 进行？","a":"加热加速反应。温度过低反应慢，过高草酸分解使结果偏高，终点时不得低于 60 ℃。"},{"q":"为什么开始滴定要慢？","a":"生成的 Mn²⁺ 是反应的催化剂，开始没有 Mn²⁺ 反应慢，滴入几滴后即可适当加快。"},{"q":"为什么用棕色瓶避光保存？","a":"光照会加速 MnO₄⁻ 自行分解生成 MnO(OH)₂ 沉淀，浓度改变。"}],"cards":[{"id":"safety","title":"安全教育","hint":"进实验室前先读完","blocks":[{"t":"h","text":"本实验多处加热，安全要点","level":3},{"t":"kv","k":"加热煮沸","v":"配制时需煮沸 20~30 min，仪器外壁擦干后再加热，防炸裂、防干烧。"},{"t":"kv","k":"控制温度","v":"标定加热至 75~85 ℃ 即可，不得煮沸，防止溶液暴沸溅出烫伤。"},{"t":"kv","k":"防烫","v":"加热后的锥形瓶口有明显蒸汽，取拿须垫毛巾或戴隔热手套。"},{"t":"kv","k":"KMnO₄","v":"强氧化剂，溅到皮肤会形成棕色斑，立即用大量流水冲洗。"},{"t":"kv","k":"稀硫酸","v":"3 mol/L H₂SO₄ 具腐蚀性，沿壁缓慢加入并轻摇混匀。"},{"t":"kv","k":"滴定管","v":"KMnO₄ 腐蚀橡胶，只能装酸式滴定管，用后立即洗净。"},{"t":"kv","k":"避光保存","v":"KMnO₄ 溶液见光易分解，配好后装入棕色瓶于暗处放置。"},{"t":"kv","k":"废液","v":"含锰废液倒入指定回收桶，不得倒入水槽。"}],"count":8},{"id":"purpose","title":"实验目的","hint":"为什么做、依据是什么","blocks":[{"t":"p","text":"KMnO₄ 常含硫酸盐、氯化物等杂质，且氧化性强，能与水中还原性物质作用并自行分解，浓度不稳定，不能用直接法配制。"},{"t":"p","text":"因此采用间接法：先配成约 0.02 mol/L 的溶液，煮沸加速杂质氧化、暗处放置陈化，再用基准物质标定。"},{"t":"h","text":"标定反应","level":3},{"t":"p","text":"基准物质用草酸钠 Na₂C₂O₄：不含结晶水、不吸湿、易纯制、性质稳定。反应式："},{"t":"p","text":"2MnO₄⁻ + 5C₂O₄²⁻ + 16H⁺ = 2Mn²⁺ + 10CO₂↑ + 8H₂O"},{"t":"p","text":"KMnO₄ 自身呈紫色，滴定至粉红色 0.5 min 不褪即为终点，不需另加指示剂。"}],"count":5},{"id":"procedure","title":"实验流程","hint":"按顺序做什么","blocks":[{"t":"h","text":"一、配制（约 1 h，另需放置 7~10 天）","level":3},{"t":"kv","k":"称量","v":"按 c=0.02 mol/L、V=300 mL 计算约需 KMnO₄ 0.95 g，用托盘天平称取。"},{"t":"kv","k":"溶解煮沸","v":"加 50 mL 蒸馏水溶解，稀释至 300 mL，加热煮沸 20~30 min。"},{"t":"kv","k":"陈化过滤","v":"暗处放置 7~10 天，用装玻璃棉的漏斗过滤除去 MnO(OH)₂ 沉淀。"},{"t":"h","text":"二、标定","level":3},{"t":"kv","k":"称样","v":"准确称取烘干 Na₂C₂O₄ 0.15~0.20 g 两份，分别放 250 mL 锥形瓶。"},{"t":"kv","k":"酸化加热","v":"各加 30 mL 水溶解、15 mL 3 mol/L H₂SO₄，加热至 75~85 ℃（瓶口有明显蒸汽）。"},{"t":"kv","k":"滴定","v":"立即用 KMnO₄ 滴定，开始慢滴，褪色后再加下一滴；终点粉红色 0.5 min 不褪，记录体积。"},{"t":"h","text":"三、计算","level":3},{"t":"kv","k":"计算式","v":"c(KMnO₄) = 2m(Na₂C₂O₄) ÷ (5 × M × V)，M(Na₂C₂O₄)=134.00 g/mol。"},{"t":"kv","k":"AI 工具","v":"扫码输入消耗体积与称样质量，得浓度及误差分析（二维码见讲义 AI 衔接部分）。"},{"t":"fig","src":"assets/h05/img1.png","caption":"图 1　AI 计算工具二维码：扫码输入消耗体积与称样质量，得浓度及误差分析"},{"t":"fig","src":"assets/h05/img2.jpg","caption":"图 2　计算工具示例：滴定数据分析与结果"}],"count":10},{"id":"thinking","title":"实验思考","hint":"做完再想一遍","blocks":[{"t":"h","text":"用什么方法配制 KMnO₄ 标准溶液？为什么？","level":3},{"t":"p","text":"间接法。KMnO₄ 含杂质纯度不足，且氧化性强，会与水中还原性物质作用并自行分解，浓度不稳定，只能先配后标。"},{"t":"h","text":"标定时应控制哪些反应条件？","level":3},{"t":"p","text":"足够的酸度（H₂SO₄ 介质）、温度 75~85 ℃（终点时不低于 60 ℃）、滴定速度先慢后快、临近终点小心滴加。"},{"t":"h","text":"KMnO₄ 装在哪种滴定管？如何读数？","level":3},{"t":"p","text":"酸式滴定管，因 KMnO₄ 腐蚀橡胶管。溶液色深，应读液面最高沿线。"},{"t":"h","text":"为什么粉红色 0.5 min 不褪即算终点？","level":3},{"t":"p","text":"空气中的还原性气体和尘埃会使 MnO₄⁻ 缓慢分解，粉红色逐渐消失，0.5 min 不褪即认为反应完全。"}],"count":4}],"feedbackUrl":""},"analytical/e11":{"id":"e11","name":"邻二氮菲法测铁","cards":[{"id":"safety","title":"安全教育","hint":"进入实验室前先读完","blocks":[{"t":"kv","k":"化学品防护","v":"盐酸羟胺具刺激性和一定毒性，称量、移取时避免接触皮肤、吸入粉尘；邻二氮菲溶液和铁盐标准溶液避免入口及溅入眼内。"},{"t":"kv","k":"仪器安全","v":"使用分光光度计前先检查，勿使液体洒入样品室，洒出立即擦净；比色皿为易碎光学玻璃，轻拿轻放，只接触毛玻璃面。"},{"t":"kv","k":"移液操作","v":"移液管必须用洗耳球吸取溶液，严禁用嘴吸取；显色试剂按顺序加入，不可颠倒，防止溅出。"},{"t":"kv","k":"废液处理","v":"含铁及有机试剂废液倒入指定废液桶，不得直接倒入下水道。"},{"t":"kv","k":"个人防护","v":"全程穿实验服，有条件时全程佩戴护目镜，实验结束及时洗手。"},{"t":"p","text":"**总结**：本实验主要风险为盐酸羟胺刺激性、有机显色废液及比色皿破损和液体洒入仪器，须做好个人防护、规范移液、按序加试剂并分类回收废液。"}],"count":6},{"id":"purpose","title":"实验目的","hint":"为什么做、依据是什么","blocks":[{"t":"p","text":"掌握邻二氮菲分光光度法测定微量铁的原理：Fe²⁺与邻二氮菲生成稳定橙红色螯合物 Fe(phen)₃²⁺，在约510 nm处有最大吸收并遵守朗伯-比尔定律。"},{"t":"p","text":"了解V-5000型分光光度计的构造、调零和吸光度测定方法，能正确区分A模式与T模式并规范使用2 cm比色皿。"},{"t":"p","text":"学习吸收曲线和标准曲线的制作：通过460～530 nm每10 nm测吸光度确定λmax，再由铁标准系列绘制A-c标准曲线。"},{"t":"p","text":"完成未知水样中微量铁的测定：取5.00 mL未知液两份平行显色，测A后由标准曲线求铁含量，以μg·mL⁻¹表示。"}],"count":4},{"id":"procedure","title":"实验流程","hint":"怎么做、注意什么","blocks":[{"t":"p","text":"检查分光光度计和比色皿，确认样品室洁净；准备50 mL比色管、移液管、洗耳球及1％盐酸羟胺、HAc-NaAc缓冲溶液、0.1％邻二氮菲等试剂。"},{"t":"p","text":"吸收曲线显色液配制：准确移取铁盐标准溶液6.0 mL于50 mL比色管中，依次加入1％盐酸羟胺2.5 mL、HAc-NaAc缓冲溶液5.0 mL、0.1％邻二氮菲5.0 mL，用蒸馏水稀释至刻度，摇匀后放置10 min。"},{"t":"p","text":"波长扫描：用2 cm比色皿、蒸馏水作参比，在460～530 nm范围内每隔10 nm测定吸光度；每次改变波长重新调0％T和A模式零点，绘制吸收曲线并确定最大吸收波长λmax（约510 nm）。"},{"t":"p","text":"标准系列配制：分别准确移取铁盐标准溶液2.00、4.00、6.00、8.00、10.00 mL于5支编号50 mL比色管中，依次加入1％盐酸羟胺2.5 mL、HAc-NaAc缓冲溶液5.0 mL、0.1％邻二氮菲5.0 mL，稀释至刻度，摇匀后放置10 min。"},{"t":"p","text":"仪器调零与测定：将波长调至λmax，T模式推入黑体按“0％T”调零，A模式推入参比溶液按“OABS”调零；依次测定标准系列吸光度。"},{"t":"p","text":"绘制标准曲线：以铁浓度为横坐标、吸光度A为纵坐标作图，得到A-c关系；检查线性并用于未知样计算。"},{"t":"p","text":"未知液测定：准确移取未知液5.00 mL两份，分别转入两支50 mL比色管，按上述顺序加入相同显色试剂，稀释至刻度、摇匀放置10 min，在λmax下测吸光度。"},{"t":"p","text":"数据处理与清理：由未知液A从标准曲线查出5.00 mL未知液中铁含量并换算为μg·mL⁻¹；清洗比色皿和器皿，含铁及有机废液倒入指定废液桶。"},{"t":"table","rows":[["AI计算水样中铁的浓度和总量"],["步骤：",""]],"header":true},{"t":"img","src":"assets/emwrjddtl/img1.png","caption":""},{"t":"img","src":"assets/emwrjddtl/img2.png","caption":""},{"t":"img","src":"assets/emwrjddtl/img3.png","caption":""}],"count":12},{"id":"thinking","title":"实验思考","hint":"想清楚再动手","blocks":[{"t":"h","text":"Q 绘制吸收曲线和标准曲线的目的分别是什么？"},{"t":"p","text":"吸收曲线用于确定最大吸收波长λmax（本实验约510 nm），使测定灵敏度较高；标准曲线用于建立吸光度A与铁浓度c的定量关系，从而由未知液A求得铁含量。"},{"t":"h","text":"Q 为什么显色前要加入盐酸羟胺和HAc-NaAc缓冲溶液？"},{"t":"p","text":"盐酸羟胺将Fe³⁺还原为Fe²⁺，防止氧化剂干扰并保证与邻二氮菲生成Fe(phen)₃²⁺；HAc-NaAc缓冲溶液控制pH在3～9，避免pH<2时显色缓慢、pH过高时Fe²⁺水解影响显色。"},{"t":"h","text":"Q 酸度对邻二氮菲显色有何影响？"},{"t":"p","text":"pH<2时反应进行缓慢，显色不完全；pH过高时Fe²⁺易水解，影响橙红色螯合物形成。适宜用HAc-NaAc缓冲溶液控制酸度，使颜色稳定。"},{"t":"h","text":"Q 如何根据实验结果计算邻二氮菲铁配合物的摩尔吸收系数？"},{"t":"p","text":"由A=εbc，得ε=A/(bc)，其中b=2 cm，c为铁配合物浓度（mol·L⁻¹，由标准铁浓度换算），取λmax下测得的A计算；也可由标准曲线斜率k=εb，得ε=k/b。"}],"count":4}],"qa":[{"q":"为什么测定时使用2 cm比色皿和蒸馏水作参比？","a":"2 cm比色皿光程较长，可提高微量铁测定的吸光度；蒸馏水作参比用于扣除溶剂和比色皿背景，使测得的A主要反映显色配合物吸收。"},{"q":"为什么每次改变波长都要重新调0％T和调零？","a":"分光光度计在不同波长下暗电流和参比响应会变化，改变波长后需重新校0％T并以参比调A零点，否则吸光度读数会有偏差。"},{"q":"标准系列和未知液为什么要放置10 min后测定？","a":"Fe²⁺与邻二氮菲显色需要一定时间达到稳定，放置10 min可使橙红色螯合物充分形成、颜色稳定，保证标准曲线和未知液测定条件一致。"},{"q":"试剂加入顺序为什么不能颠倒？","a":"应先加盐酸羟胺还原Fe³⁺，再加缓冲溶液控制酸度，最后加邻二氮菲显色；顺序颠倒可能导致还原不完全、酸度不适或显色异常，影响结果。"},{"q":"未知液为何要取两份平行测定？","a":"两份平行样可检查操作重复性并减小偶然误差；若吸光度相差较大，应查找移液、显色或仪器调零等问题后重新测定。"}],"ai":true,"full":"邻二氮菲吸光光度法测定铁","no":11,"order":0,"hidden":false,"visibleAt":"","feedbackUrl":""},"analytical/h01":{"id":"h01","no":1,"name":"水的总硬度测定","order":1,"full":"实验四十五 水的总硬度的测定","hidden":true,"visibleAt":"","ai":true,"qa":[{"q":"什么是水的硬度？用什么单位表示？","a":"水的总硬度是水中钙、镁离子的总量。工程上常以 CaO 的 mg/L（ppm）表示，也有以 CaCO₃ 计或德国度表示。"},{"q":"EDTA 滴定水的总硬度，为什么要加氨性缓冲溶液？","a":"EDTA 与 Ca²⁺、Mg²⁺ 的配位能力随 pH 变化，pH≈10 时反应最完全且铬黑 T 变色敏锐；同时防止 Mg²⁺ 生成氢氧化物沉淀。"},{"q":"铬黑 T 的变色原理是什么？","a":"计量点前 Ca²⁺、Mg²⁺ 与铬黑 T 形成酒红色配合物；接近终点时 EDTA 夺取金属离子，游离出指示剂，溶液呈纯蓝色，即为终点。"},{"q":"Fe³⁺、Al³⁺ 干扰如何消除？","a":"加入三乙醇胺掩蔽 Fe³⁺、Al³⁺，或加 Na₂S 使重金属生成硫化物沉淀；干扰严重时可先分离。"},{"q":"为什么同一批滴定要在滴定管的同一部位读数？","a":"滴定管刻度存在系统误差，固定体积区间读数可使各次误差相互抵消，提高平行测定的精密度。"},{"q":"如何计算水的总硬度？","a":"ρ(CaO, mg/L) = c(EDTA)·V(EDTA)·56.08 / V(水样) × 1000，其中 V 单位为 mL，c 单位为 mol/L。"}],"cards":[{"id":"safety","title":"安全教育","hint":"进实验室前先读完","blocks":[{"t":"h","text":"本实验安全要点","level":3},{"t":"kv","k":"氨水","v":"1:1 氨水具挥发性与刺激性，必须在通风橱内取用，闻气味用扇闻。"},{"t":"kv","k":"缓冲液","v":"氨性缓冲溶液 pH≈10，具碱性腐蚀性，溅到皮肤立即用大量流水冲洗。"},{"t":"kv","k":"指示剂","v":"铬黑 T 易染色衣物与台面，滴加时避免溅出，用后立即盖好。"},{"t":"kv","k":"EDTA","v":"EDTA 溶液低毒，但不得入口；配好的标准溶液应贴标签、注明浓度与日期。"},{"t":"kv","k":"滴定管","v":"酸式滴定管使用前检漏、排气泡；读数时视线与凹液面最低处相平。"},{"t":"kv","k":"废液","v":"含 EDTA 与钙镁的废液集中回收，不得倒入水槽。"}],"count":6},{"id":"purpose","title":"实验目的","hint":"为什么做、依据是什么","blocks":[{"t":"h","text":"实验目的","level":3},{"t":"p","text":"1．学习 EDTA 直接滴定法的应用；"},{"t":"p","text":"2．掌握 EDTA 法测定水的硬度的原理和方法；"},{"t":"p","text":"3．了解测定水的硬度的意义和常用的硬度表示法。"},{"t":"h","text":"实验原理","level":3},{"t":"p","text":"水的总硬度由溶于水的钙、镁离子的总量来表示。一般每升水中含 50~80 mg 的钙和镁：含量低于此标准的水叫软水，高于此标准的水叫硬水。"},{"t":"p","text":"测定水的总硬度采用配位滴定法：用 EDTA 标准溶液直接滴定水中的 Ca²⁺、Mg²⁺ 总量，常在 pH≈10 的氨性缓冲溶液中进行，以铬黑 T 为指示剂。计量点前 Ca²⁺、Mg²⁺ 与铬黑 T 形成紫红色配合物，滴定至终点时游离出指示剂，溶液呈纯蓝色。"},{"t":"h","text":"计算式","level":3},{"t":"p","text":"总硬度 ρ(CaO) = c(EDTA)·V(EDTA)·M(CaO) / V(水) × 1000，单位 mg/L；M(CaO)=56.08 g/mol。"}],"count":6,"ai":true},{"id":"procedure","title":"实验流程","hint":"按顺序做什么","blocks":[{"t":"h","text":"实验步骤","level":3},{"t":"p","text":"1．用移液管量取澄清的水样 100 mL（为何用移液管而不是量筒？）置于锥形瓶中。"},{"t":"p","text":"2．加入 5 mL 氨性缓冲溶液（pH≈10），摇匀。"},{"t":"p","text":"3．加入 3~4 滴 0.5% 铬黑 T 指示剂，溶液呈酒红色。"},{"t":"p","text":"4．用 0.02 mol/L EDTA 标准溶液滴定至溶液由酒红色变为纯蓝色，即为终点，记录消耗体积 V(EDTA)。"},{"t":"p","text":"5．平行测定 2~3 次，按计算式求水的总硬度，以 CaO 计。"},{"t":"h","text":"注意事项","level":3},{"t":"p","text":"1．同一实验的各次滴定中，溶液的体积应控制在滴定管刻度的同一部位，使刻度不准引起的误差相互抵消。"},{"t":"p","text":"2．摇动锥形瓶时作同一方向的圆周运动，使瓶内溶液混合均匀、反应完全。"},{"t":"h","text":"实验工具","level":3},{"t":"kv","k":"EDTA 标定计算","v":"c(EDTA) = c(Zn²⁺)·V(Zn²⁺) / V(EDTA)，反应 Zn²⁺ + H₂Y²⁻ → ZnY²⁻ + 2H⁺。"},{"t":"kv","k":"硬度计算","v":"输入水样体积与消耗的 EDTA 体积，即可得总硬度（以 CaO 计，mg/L）。"}],"count":9,"ai":true},{"id":"thinking","title":"实验思考","hint":"做完再想一遍","blocks":[{"t":"h","text":"1．什么是水的硬度？水的硬度单位是什么？","level":3},{"t":"p","text":"水的硬度指水中 Ca²⁺、Mg²⁺ 的总量，常以每升水中 CaO 的毫克数（mg/L，即 ppm）或德国度（1 °d ≈ 10 mg CaO/L）表示。"},{"t":"h","text":"2．用 EDTA 怎样测定水的总硬度？指示剂与 pH 如何控制？终点如何变化？","level":3},{"t":"p","text":"用 EDTA 标准溶液直接滴定 Ca²⁺、Mg²⁺ 总量；以铬黑 T 为指示剂，用氨性缓冲溶液控制 pH≈10；终点由酒红色变为纯蓝色。"},{"t":"h","text":"3．水中含有少量杂质是否有干扰？如何消除？","level":3},{"t":"p","text":"Fe³⁺、Al³⁺ 等会与 EDTA 生成更稳定的配合物并封闭指示剂，造成终点拖后或不变色。可加三乙醇胺掩蔽 Fe³⁺、Al³⁺，或加 Na₂S 沉淀重金属；大量 Cu²⁺ 可用 KCN 掩蔽（须在通风橱内操作）。"},{"t":"h","text":"4．为什么必须在 pH≈10 的条件下滴定？","level":3},{"t":"p","text":"pH 过低时 EDTA 主要以 H₂Y²⁻ 等形式存在、配位能力弱，Ca²⁺ 反应不完全；pH 过高则 Mg²⁺ 生成 Mg(OH)₂ 沉淀，且指示剂变色不敏锐。pH≈10 是 CaY²⁻、MgY²⁻ 稳定且指示剂显色的最佳区间。"},{"t":"h","text":"5．为什么用移液管量取水样而不用量筒？","level":3},{"t":"p","text":"移液管为定量量器，精度（±0.1%）远高于量筒（±1%），而硬度计算对水样体积的准确度要求较高；量筒只适用于粗略量取。"}],"count":5,"ai":true}],"feedbackUrl":""},"inorganic/e01":{"id":"e01","no":1,"name":"基本操作练习及粗食盐的提纯","full":"基本操作练习及粗食盐的提纯","qa":[{"q":"除去 SO₄²⁻ 时，BaCl₂ 为什么要过量？过量的 Ba²⁺ 怎么除去？","a":"BaCl₂ 适当过量才能使 SO₄²⁻ 沉淀完全并降低其残留浓度。过量的 Ba²⁺ 在后续加入 Na₂CO₃ 时生成 BaCO₃ 沉淀，随第二次过滤一并除去，不会带入产品。"},{"q":"怎么判断 SO₄²⁻ 已经沉淀完全？","a":"沉淀沉降后取上层清液，补滴 1~2 滴 BaCl₂，若不再产生浑浊即表示已除尽；仍浑浊则继续滴加。这是“检验沉淀完全”的标准操作。"},{"q":"为什么 Na₂CO₃ 必须加在 BaCl₂ 之后？","a":"Na₂CO₃ 同时承担除去 Ca²⁺ 和过量 Ba²⁺ 的任务。若先加 Na₂CO₃ 再加 BaCl₂，后引入的 Ba²⁺ 没有试剂可以除去，会残留在溶液中并带入产品。加料顺序为 BaCl₂ → NaOH → Na₂CO₃ → HCl。"},{"q":"滤液为什么要用 HCl 调到 pH 2~3？","a":"前面为沉淀杂质加入了过量的 NaOH 和 Na₂CO₃，必须中和除去，否则成品中会混入碱和碳酸钠，蒸发时还会因碱液飞溅造成损失。终点以 pH 试纸检验，控制 pH = 2~3。"},{"q":"蒸发结晶为什么用小火，蒸干后为什么还要用滤纸吸干？","a":"大火蒸发时溶液暴沸、液滴溅出会造成损失，局部过热还可能使晶体崩裂。小火蒸干后，晶体表面仍附着母液，需倒在滤纸上吸干残余水分，否则称量质量偏高、产品不纯。"},{"q":"产率偏低可能有哪些原因？","a":"常见原因：溶解用水过多延长蒸发时间；过滤时晶体穿滤；蒸发时暴沸溅出；晶体转移不彻底；沉淀吸附少量 NaCl。两次过滤都必须保留滤液，这是最容易出错的地方。"}],"cards":[{"id":"safety","title":"安全教育","hint":"进实验室前先读完","blocks":[{"t":"h","text":"本实验安全要点","level":3},{"t":"kv","k":"要点1","v":"BaCl₂ 为可溶性钡盐，有毒：称量避免扬尘，接触后立即洗手，废液入含钡桶。"},{"t":"kv","k":"要点2","v":"酒精灯用灯帽盖灭；加热试管液体不超过 1/3，管口不对人。"},{"t":"kv","k":"要点3","v":"调 pH 时逐滴加入 2 mol/L HCl，防止酸液溅出。"},{"t":"kv","k":"要点4","v":"两次过滤的滤液均要保留，滤纸与残渣按固废处理。"},{"t":"h","text":"个人防护与准入","level":2},{"t":"p","text":"进入实验室前完成以下确认，未完成者不得开始实验。"},{"t":"kv","k":"实验服","v":"穿着实验服，衣扣与袖口扣紧；不得穿凉鞋、短裤或裙装。"},{"t":"kv","k":"护目镜","v":"全程佩戴，取用酸碱、加热及减压过滤时不得摘下。"},{"t":"kv","k":"手套","v":"接触酸碱溶液与钡盐时佩戴丁腈手套，破损后立即更换。"},{"t":"kv","k":"长发","v":"束起并收进实验服内，避免接触明火与试剂。"},{"t":"kv","k":"饮食","v":"实验室内禁止饮食、饮水、吸烟及化妆。"},{"t":"kv","k":"台面","v":"书包与手机放置指定位置，保持通道与台面整洁。"},{"t":"h","text":"本实验危险源","level":2},{"t":"p","text":"本实验涉及下列危险源，操作前确认其位置与防护措施。"},{"t":"kv","k":"BaCl₂","v":"可溶性钡盐有毒，称量与转移时避免扬尘和飞溅，接触后洗手。"},{"t":"kv","k":"酸液","v":"2 mol/L HCl 具腐蚀性，移取时防止溅到皮肤与眼睛。"},{"t":"kv","k":"碱液","v":"2 mol/L NaOH 可灼伤皮肤，溅入眼内可损伤角膜。"},{"t":"kv","k":"明火","v":"酒精外溢或灯芯松动可引燃台面，附近不得放置乙醇与滤纸。"},{"t":"kv","k":"高温","v":"加热后的烧杯、蒸发皿与石棉网温度高，冷却前不得徒手取放。"},{"t":"kv","k":"玻璃","v":"试管、量筒、蒸发皿受热不均或磕碰易破裂，可能造成割伤。"},{"t":"h","text":"关键操作禁忌","level":2},{"t":"p","text":"以下操作要求在本实验中须严格执行。"},{"t":"kv","k":"酒精灯","v":"用火柴点燃，不得用另一酒精灯引火；熄灭用灯帽盖灭，严禁吹灭。"},{"t":"kv","k":"试管加热","v":"液体不超过试管容积三分之一，管口不对人，先预热后集中加热。"},{"t":"kv","k":"试剂取用","v":"瓶塞倒放，标签朝向手心，滴管不触壁；取出的试剂不得倒回原瓶。"},{"t":"kv","k":"过滤","v":"用玻璃棒引流，漏斗下端管口紧靠烧杯内壁，滤纸边缘低于漏斗口。"},{"t":"kv","k":"减压过滤","v":"先检查装置气密性并接安全瓶；停止抽滤时先卸压，防止倒吸。"},{"t":"kv","k":"蒸发","v":"蒸发皿内液体不超过容积三分之二，小火加热，防止暴沸飞溅。"},{"t":"h","text":"事故处置与废液分类","level":2},{"t":"p","text":"按类别先行处置，随后报告指导教师并登记。"},{"t":"kv","k":"酸碱溅皮肤","v":"立即用大量流水冲洗 5 min 以上；酸伤用 3% NaHCO₃、碱伤用 2% 醋酸处理。"},{"t":"kv","k":"试剂入眼","v":"立即用洗眼器冲洗 15 min 以上，翻开上下眼睑冲洗，随后就医。"},{"t":"kv","k":"烫伤","v":"用冷水冲洗 15 min，不涂药膏、不刺破水泡。"},{"t":"kv","k":"割伤","v":"清除玻璃碎片，流水冲洗后压迫止血，伤口较深时送医。"},{"t":"kv","k":"含钡废液","v":"含 Ba²⁺ 废液与 BaSO₄ 沉淀倒入含钡废液桶，不得倒入水槽。"},{"t":"kv","k":"固废","v":"含钡沉淀的滤纸与残渣投入专用废物桶，不与生活垃圾混放。"}],"count":32},{"id":"purpose","title":"实验目的","hint":"为什么做、依据是什么","blocks":[{"t":"h","text":"实验目的","level":2},{"t":"p","text":"本次实验分为**基本操作训练**与**粗食盐提纯**两部分。"},{"t":"p","text":"1.　认识化学实验中常用仪器，学习使用量筒和对液体的估量，练习固体、液体试剂的取用和在试管中加热的方法。"},{"t":"p","text":"2.　通过对粗食盐的提纯，练习溶解、过滤、蒸发、结晶等基本操作，并掌握提纯食盐的方法。"},{"t":"p","text":"**说 明**\n第一项对应本实验前半段的仪器与基本操作训练；第二项在提纯流程中逐项落实。"},{"t":"h","text":"粗食盐中的杂质","level":2},{"t":"p","text":"粗食盐中，含有不溶性杂质（如泥沙等）和可溶性杂质（主要是 Ca^{2+}、Mg^{2+}、K^{+}、Fe^{3+}、SO_{4}^{2−}）。不溶性杂质可用溶解和过滤方法除去，可溶性杂质用下列方法除去。"},{"t":"p","text":"**不溶性杂质**\n泥沙等，用溶解、过滤的方法除去。\n**可溶性杂质**\nCa^{2+}、Mg^{2+}、K^{+}、Fe^{3+}、SO_{4}^{2−}，用沉淀法除去后过滤。"},{"t":"p","text":"K+ 含量很少，在蒸发结晶时不会与 NaCl 同时析出，故不作专门处理。","html":"K<sup>+</sup> 含量很少，在蒸发结晶时不会与 NaCl 同时析出，故不作专门处理。"},{"t":"h","text":"除去 SO4^{2−}","level":2},{"t":"p","text":"向粗食盐溶液中加入 BaCl2 溶液，使 SO42− 生成难溶的 BaSO4 沉淀，再经过滤除去。","html":"向粗食盐溶液中加入 BaCl<sub>2</sub> 溶液，使 SO<sub>4</sub><sup>2−</sup> 生成难溶的 BaSO<sub>4</sub> 沉淀，再经过滤除去。"},{"t":"p","text":"Ba2+ + SO42− = BaSO4↓","html":"Ba<sup>2+</sup> + SO<sub>4</sub><sup>2−</sup> = BaSO<sub>4</sub>↓"},{"t":"p","text":"**说 明**\nBaCl_{2} 需适当过量，以保证 SO_{4}^{2−} 沉淀完全；过量的 Ba^{2+} 在后续步骤中加入 Na_{2}CO_{3} 时一并除去。"},{"t":"h","text":"除去 Mg^{2+}、Fe^{3+}","level":2},{"t":"p","text":"在滤液中加入 NaOH 和 Na_{2}CO_{3} 溶液，过滤可除去 Mg^{2+}、Ca^{2+}、Fe^{3+}、Ba^{2+}（除去 SO_{4}^{2−} 时加入之过量离子）。"},{"t":"p","text":"其中 Mg2+、Fe3+ 由 NaOH 沉淀除去：","html":"其中 Mg<sup>2+</sup>、Fe<sup>3+</sup> 由 NaOH 沉淀除去："},{"t":"p","text":"Fe3+ + 3OH− = Fe(OH)3↓","html":"Fe<sup>3+</sup> + 3OH<sup>−</sup> = Fe(OH)<sub>3</sub>↓"},{"t":"p","text":"Mg2+ + 2OH− = Mg(OH)2↓","html":"Mg<sup>2+</sup> + 2OH<sup>−</sup> = Mg(OH)<sub>2</sub>↓"},{"t":"p","text":"Fe(OH)_{3} 为红褐色沉淀，Mg(OH)_{2} 为白色沉淀，可据此判断沉淀是否生成。"},{"t":"h","text":"除去 Ca^{2+ }与过量的 Ba^{2+}","level":2},{"t":"p","text":"Ca2+ 与除去 SO42− 时加入的过量 Ba2+，由 Na2CO3 生成碳酸盐沉淀后过滤除去。","html":"Ca<sup>2+</sup> 与除去 SO<sub>4</sub><sup>2−</sup> 时加入的过量 Ba<sup>2+</sup>，由 Na<sub>2</sub>CO<sub>3</sub> 生成碳酸盐沉淀后过滤除去。"},{"t":"p","text":"Ca2+ + CO32− = CaCO3↓","html":"Ca<sup>2+</sup> + CO<sub>3</sub><sup>2−</sup> = CaCO<sub>3</sub>↓"},{"t":"p","text":"Ba2+ + CO32− = BaCO3↓","html":"Ba<sup>2+</sup> + CO<sub>3</sub><sup>2−</sup> = BaCO<sub>3</sub>↓"},{"t":"p","text":"**注 意**\nNa_{2}CO_{3} 必须加入在 BaCl_{2} 之后。若顺序颠倒，后引入的 Ba^{2+} 无试剂可除去，将带入产品。"},{"t":"h","text":"中和过量的碱","level":2},{"t":"p","text":"过量的 NaOH 和 Na_{2}CO_{3} 用 HCl 中和除去。少量可溶性杂质（如 KCl）由于含量很少，在蒸发、结晶过程中，不会和 NaCl 同时结晶出来。"},{"t":"p","text":"OH− + H+ = H2O","html":"OH<sup>−</sup> + H<sup>+</sup> = H<sub>2</sub>O"},{"t":"p","text":"CO32− + 2H+ = H2O + CO2↑","html":"CO<sub>3</sub><sup>2−</sup> + 2H<sup>+</sup> = H<sub>2</sub>O + CO<sub>2</sub>↑"},{"t":"p","text":"中和终点以 pH 试纸检验，控制溶液 pH 在 2~3。"},{"t":"h","text":"仪器和药品","level":2},{"t":"p","text":"**量取与称量**"},{"t":"p","text":"10 mL 量筒　小滴管　台秤　点滴板"},{"t":"p","text":"**溶解与加热**"},{"t":"p","text":"100 mL 烧杯、钥匙、洗瓶、试管、试管夹、酒精灯、石棉网、铁架、蒸发皿"},{"t":"p","text":"**过滤与其他**"},{"t":"p","text":"玻璃漏斗、漏斗架、滤纸、玻璃棒、减压过滤系统、广泛 pH 试纸"},{"t":"p","text":"**药品**"},{"t":"p","text":"固体 NaCl、粗食盐、BaCl_{2}（1 mol/L）、HCl（2 mol/L）、NaOH（2 mol/L）、Na_{2}CO_{3}（2 mol/L）"}],"count":31},{"id":"procedure","title":"实验流程","hint":"按顺序做什么","blocks":[{"t":"h","text":"量筒的使用和液体估量","level":2},{"t":"p","text":"往干燥的 10 mL 量筒中用滴管滴加水至 1 mL，记录滴数，继续加水至 2 mL、3 mL，记录滴数，得出平均 1 mL 水（或稀溶液）的滴数。"},{"t":"p","text":"**1.**　取干燥的 10 mL 量筒，用滴管滴加水至 1 mL，记录滴数。"},{"t":"p","text":"**2.**　继续滴加至 2 mL、3 mL，分别记录滴数。"},{"t":"p","text":"**3.**　计算平均每毫升水（或稀溶液）的滴数，作为后续估量的依据。"},{"t":"p","text":"**说 明**\n读取量筒示数时视线与凹液面最低处相平，量筒应放在水平台面上。"},{"t":"h","text":"试剂的取用与试管加热","level":2},{"t":"p","text":"用小匙取少量固体 NaCl，放入试管中，加入蒸馏水 2 mL，用拇指、食指和中指持住试管的中上部，试管略倾斜，手腕用力振荡试管，观察固体 NaCl 的溶解，并用酒精灯加热至沸腾。"},{"t":"fig","src":"assets/exps/e01/x01.png","caption":"振荡试管：持中上部，手腕用力","w":660,"h":432},{"t":"fig","src":"assets/exps/e01/x02.png","caption":"试管加热：管口不对人，先用试管夹夹住预热","w":219,"h":216},{"t":"p","text":"**说 明**\n加热时试管内液体不超过容积的 1/3，管口不得对着自己或他人；加热后试管需置于石棉网上冷却。"},{"t":"h","text":"溶解粗食盐","level":2},{"t":"p","text":"在台秤上称取 4 g 粗食盐放在小烧杯中，加入约 20 mL 蒸馏水，加热、搅拌，使其大部分固体溶解，剩下少量不溶性杂质。"},{"t":"p","text":"**说 明**\n加热时垫石棉网，用玻璃棒搅拌加速溶解。不溶性杂质不参与溶解，留在溶液中留待过滤除去。"},{"t":"h","text":"除去 SO4^{2−}","level":2},{"t":"p","text":"向热溶液中滴加 1 mol/L BaCl_{2} 溶液（约 2 mL），停止加热，在石棉网上保温约 5 分钟，待沉淀沉降后，在上层清液中滴加 1~2 滴 BaCl_{2} 溶液；如果仍有混浊现象，需继续滴加，直至滴加 1 滴后上层清液不再产生混浊现象为止，此时 SO_{4}^{2−} 已沉淀完全。继续加热 5 分钟，使沉淀颗粒长大而易于沉降。用普通漏斗过滤，将滤纸及残留物投入废液桶，保留滤液。"},{"t":"p","text":"**1.**　趁热滴加 1 mol/L BaCl_{2} 约 2 mL，停止加热，石棉网上保温 5 分钟。"},{"t":"p","text":"**2.**　取上层清液，滴加 1~2 滴 BaCl_{2} 检验；仍浑浊则继续滴加，直至不再浑浊。"},{"t":"p","text":"**3.**　确认沉淀完全后，继续加热 5 分钟，使沉淀颗粒长大。"},{"t":"p","text":"**4.**　用普通漏斗过滤，滤纸及残留物投入废液桶，保留滤液。"},{"t":"h","text":"除去 Mg^{2+}、Ca^{2+}、Ba^{2+}、Fe^{3+}","level":2},{"t":"p","text":"在滤液中加入 1 mL 2 mol·L^{-1} NaOH 和 3 mL 2 mol·L^{-1} Na_{2}CO_{3} 溶液，加热至沸，待沉淀沉降后，于上层清液中滴加 1 滴 Na_{2}CO_{3} 溶液，直至不再产生混浊现象为止，保温 5 分钟，沉淀沉降后用普通漏斗过滤。弃去滤纸及残留物，保留滤液。"},{"t":"p","text":"**注 意**\n本次过滤同样保留滤液；检验沉淀是否完全的方法与上一步相同，补滴 Na_{2}CO_{3} 后不再浑浊即可。"},{"t":"h","text":"调节 pH 值","level":2},{"t":"p","text":"在滤液中逐滴加入 2 mol·L^{-1} HCl，用玻棒沾取滤液于 pH 试纸上检验，直至溶液 pH = 2~3 时为止。"},{"t":"p","text":"**1.**　用滴管逐滴加入 2 mol/L HCl，边加边搅拌。"},{"t":"p","text":"**2.**　用玻璃棒沾取少量滤液，点在广泛 pH 试纸上，与标准比色卡对照。"},{"t":"p","text":"**3**.　重复上述操作，直至 pH 稳定在 2~3。"},{"t":"p","text":"**说 明**\n沾取试液后的玻璃棒不得再次伸入滤液；每次沾取前应将玻璃棒洗净并擦干，避免污染滤液。"},{"t":"h","text":"蒸发结晶","level":2},{"t":"p","text":"将滤液倒入蒸发皿中，用小火加热蒸发，浓缩至粘稠后继续小火加热直至完全把水分蒸干，将得到的晶体倒在滤纸上把残余水分吸干，称其质量，计算产率。"},{"t":"p","text":"**1.**　滤液转入蒸发皿，小火加热蒸发，浓缩至粘稠。"},{"t":"p","text":"**2.**　继续小火加热至水分完全蒸干，避免局部过热导致晶体飞溅。"},{"t":"p","text":"**3.**　将晶体转移至滤纸上吸干残余水分，**冷却后称量**。"},{"t":"p","text":"**4.**　按产率 = 实际所得质量 ÷ 粗食盐质量 × 100% 计算。"},{"t":"p","text":"**说 明**\n蒸发皿温度较高，须待冷却后再取放与称量。"}],"count":29},{"id":"thinking","title":"实验思考","hint":"做完再想一遍","blocks":[{"t":"h","text":"除去 SO₄²⁻ 时，BaCl₂ 为什么要过量？过量的 Ba²⁺ 怎么除去？","level":3},{"t":"p","text":"BaCl₂ 适当过量才能使 SO₄²⁻ 沉淀完全并降低其残留浓度。过量的 Ba²⁺ 在后续加入 Na₂CO₃ 时生成 BaCO₃ 沉淀，随第二次过滤一并除去，不会带入产品。"},{"t":"h","text":"怎么判断 SO₄²⁻ 已经沉淀完全？","level":3},{"t":"p","text":"沉淀沉降后取上层清液，补滴 1~2 滴 BaCl₂，若不再产生浑浊即表示已除尽；仍浑浊则继续滴加。这是“检验沉淀完全”的标准操作。"},{"t":"h","text":"为什么 Na₂CO₃ 必须加在 BaCl₂ 之后？","level":3},{"t":"p","text":"Na₂CO₃ 同时承担除去 Ca²⁺ 和过量 Ba²⁺ 的任务。若先加 Na₂CO₃ 再加 BaCl₂，后引入的 Ba²⁺ 没有试剂可以除去，会残留在溶液中并带入产品。加料顺序为 BaCl₂ → NaOH → Na₂CO₃ → HCl。"},{"t":"h","text":"滤液为什么要用 HCl 调到 pH 2~3？","level":3},{"t":"p","text":"前面为沉淀杂质加入了过量的 NaOH 和 Na₂CO₃，必须中和除去，否则成品中会混入碱和碳酸钠，蒸发时还会因碱液飞溅造成损失。终点以 pH 试纸检验，控制 pH = 2~3。"},{"t":"h","text":"蒸发结晶为什么用小火，蒸干后为什么还要用滤纸吸干？","level":3},{"t":"p","text":"大火蒸发时溶液暴沸、液滴溅出会造成损失，局部过热还可能使晶体崩裂。小火蒸干后，晶体表面仍附着母液，需倒在滤纸上吸干残余水分，否则称量质量偏高、产品不纯。"},{"t":"h","text":"产率偏低可能有哪些原因？","level":3},{"t":"p","text":"常见原因：溶解用水过多延长蒸发时间；过滤时晶体穿滤；蒸发时暴沸溅出；晶体转移不彻底；沉淀吸附少量 NaCl。两次过滤都必须保留滤液，这是最容易出错的地方。"}],"count":6,"qa":[{"q":"除去 SO₄²⁻ 时，BaCl₂ 为什么要过量？过量的 Ba²⁺ 怎么除去？","a":"BaCl₂ 适当过量才能使 SO₄²⁻ 沉淀完全并降低其残留浓度。过量的 Ba²⁺ 在后续加入 Na₂CO₃ 时生成 BaCO₃ 沉淀，随第二次过滤一并除去，不会带入产品。"},{"q":"怎么判断 SO₄²⁻ 已经沉淀完全？","a":"沉淀沉降后取上层清液，补滴 1~2 滴 BaCl₂，若不再产生浑浊即表示已除尽；仍浑浊则继续滴加。这是“检验沉淀完全”的标准操作。"},{"q":"为什么 Na₂CO₃ 必须加在 BaCl₂ 之后？","a":"Na₂CO₃ 同时承担除去 Ca²⁺ 和过量 Ba²⁺ 的任务。若先加 Na₂CO₃ 再加 BaCl₂，后引入的 Ba²⁺ 没有试剂可以除去，会残留在溶液中并带入产品。加料顺序为 BaCl₂ → NaOH → Na₂CO₃ → HCl。"},{"q":"滤液为什么要用 HCl 调到 pH 2~3？","a":"前面为沉淀杂质加入了过量的 NaOH 和 Na₂CO₃，必须中和除去，否则成品中会混入碱和碳酸钠，蒸发时还会因碱液飞溅造成损失。终点以 pH 试纸检验，控制 pH = 2~3。"},{"q":"蒸发结晶为什么用小火，蒸干后为什么还要用滤纸吸干？","a":"大火蒸发时溶液暴沸、液滴溅出会造成损失，局部过热还可能使晶体崩裂。小火蒸干后，晶体表面仍附着母液，需倒在滤纸上吸干残余水分，否则称量质量偏高、产品不纯。"},{"q":"产率偏低可能有哪些原因？","a":"常见原因：溶解用水过多延长蒸发时间；过滤时晶体穿滤；蒸发时暴沸溅出；晶体转移不彻底；沉淀吸附少量 NaCl。两次过滤都必须保留滤液，这是最容易出错的地方。"}]}],"order":1,"hidden":false,"visibleAt":"","feedbackUrl":""},"inorganic/e02":{"id":"e02","no":2,"name":"配位解离平衡常数测定","full":"配位解离平衡常数的测定","cards":[{"id":"safety","title":"安全教育","hint":"进实验室前先读完","blocks":[{"t":"h","text":"本实验安全要点","level":3},{"t":"kv","k":"要点1","v":"银氨溶液现配现用，严禁蒸干、久置，受震动可能爆炸；用后加稀盐酸酸化破坏。"},{"t":"kv","k":"要点2","v":"浓盐酸、氨水、Na₂S 在通风橱内取用，闻气味用扇闻。"},{"t":"kv","k":"要点3","v":"Na₂S、NaF、硫代硫酸钠严禁与酸混合，遇酸放出剧毒气体。"},{"t":"kv","k":"要点4","v":"重金属废液（含 Ag⁺、Ba²⁺、Cu²⁺、Zn²⁺）分类回收，不倒水槽。"},{"t":"p","text":"本实验为小剂量试管反应，反应本身不剧烈，风险主要来自试剂性质与操作习惯。八个风险点位逐一过关：个人防护、通风橱、腐蚀性酸碱、有毒试剂、银氨溶液、加热明火、废液回收、应急处置，收束于安全\"八不准\"。"},{"t":"h","text":"安全先行：本实验的风险画像","level":2},{"t":"p","text":"**风险来自哪里**"},{"t":"p","text":"反应本身：小剂量试管反应，现象温和、不剧烈——这正是容易放松警惕的原因。\n试剂性质：浓 HCl、氨水、Na₂S 等试剂具腐蚀性、毒性或挥发性，是最主要的风险来源。\n操作习惯：逐滴加入、边加边摇、专管专用做不到位，既让现象失真，也会酿成意外。"},{"t":"p","text":"**最高危的三件事**"},{"t":"p","text":"① 银氨溶液——严禁蒸干、久置，受摩擦震动可能爆炸（雷爆银）。\n② Na₂S / NaF / 硫代硫酸钠——严禁与酸混合，遇酸放出剧毒气体。\n③ 浓硫酸稀释——必须\"酸入水、边加边搅拌\"，严禁把水倒入浓硫酸。"},{"t":"h","text":"个人防护与现场要求","level":2},{"t":"p","text":"**进入实验室的基本要求**"},{"t":"p","text":"着装：穿实验服与手套，长发束起，不穿拖鞋短裤。\n现场纪律：实验室内禁止饮食。\n离场：离开实验室前洗手。"},{"t":"p","text":"**最后一道防线**"},{"t":"p","text":"滴加酸、加热试管、处理银氨溶液时，护目镜与手套是最后一道防线——它们挡在试剂与你的眼睛、皮肤之间。"},{"t":"fig","src":"assets/exps/e02/i01.png","caption":"图 1　个人防护三件套：护目镜 · 手套 · 实验服","w":540,"h":378},{"t":"h","text":"通风橱与挥发性试剂","level":2},{"t":"p","text":"**哪些试剂必须在通风橱内取用**"},{"t":"p","text":"浓盐酸、氨水、Na₂S 均有挥发或刺激性气味。"},{"t":"p","text":"**规范动作**"},{"t":"p","text":"取用与滴加应在通风橱内进行，管口不得对人。\n开瓶时瓶口朝通风橱内侧。\n闻气味用\"扇闻\"，不得俯身直吸。"},{"t":"p","text":"自查：在通风橱外开瓶取用浓盐酸、氨水，是\"八不准\"明令禁止的行为。"},{"t":"h","text":"银氨溶液的特殊危险","level":2},{"t":"p","text":"银氨溶液久置或蒸干会生成雷爆银，受摩擦、震动就可能爆炸。它看起来只是一瓶无色溶液，却是本实验唯一可能发生爆炸的试剂。"},{"t":"p","text":"**三个注意事项**"},{"t":"p","text":"现配现用——不提前配、不过夜。\n用后立即处理——加稀盐酸酸化破坏，倒入含银废液瓶。\n用过即洗——用过的试管及时清洗。"},{"t":"fig","src":"assets/exps/e02/i02.png","caption":"图 2　银氨溶液：现配现用、酸化破坏、严禁久置蒸干","w":400,"h":280},{"t":"p","text":"**三个“严禁”**\n严禁蒸干、严禁久存、严禁直接倒入水槽。"},{"t":"h","text":"加热与明火","level":2},{"t":"p","text":"**酒精灯使用规范**"},{"t":"p","text":"灯内酒精不超过容积的 2/3、不少于 1/4；\n火柴点燃、灯帽盖灭，不可吹灭；\n不可燃着时添加酒精。"},{"t":"p","text":"**试管加热规范**"},{"t":"p","text":"加热液体液面不超过试管的 1/3；\n管口斜向上且不对人；\n先预热，再集中加热；\n热试管不可立即用冷水冲。"},{"t":"fig","src":"assets/exps/e02/i03.png","caption":"图 3　试管加热：液面不超过 1/3，管口不对人","w":400,"h":280},{"t":"h","text":"废液分类回收","level":2},{"t":"p","text":"重金属废液：含 Ag⁺、Ba²⁺、Cu²⁺、Zn²⁺ 的废液分别回收。\n特殊废液：含硫、含氟、含硫氰酸根的废液另设回收瓶。\n注意：不得与酸性废液混倒，因为硫代硫酸钠遇酸会放出 SO₂ 并析出硫，在“八不准”中则是对应了**不准将废液倒入水槽；不准将 Na₂S、NaF、硫代硫酸钠与酸混合**的两条。"},{"t":"fig","src":"assets/exps/e02/i04.png","caption":"图 4　废液分类回收：含 Ag⁺、Ba²⁺、Cu²⁺/Zn²⁺ 分别入瓶，严禁倒入水槽","alt":"","w":540,"h":378},{"t":"h","text":"应急处置速查","level":2},{"t":"p","text":"任何意外第一时间报告指导老师，不要自行隐瞒处理。"},{"t":"h","text":"安全\"八不准\"","level":2},{"t":"p","text":"一　不准不穿戴防护进入实验室。\n二　不准在实验室饮食。\n三　不准在通风橱外开瓶取用浓盐酸、氨水。\n四　不准滴管混用或伸入试管。\n五　不准把水倒入浓硫酸。\n六　不准将 Na₂S、NaF、硫代硫酸钠与酸混合。\n七　不准蒸干或久置银氨溶液。\n八　不准将废液倒入水槽。"}],"count":33},{"id":"purpose","title":"实验目的","hint":"为什么做、依据是什么","blocks":[{"t":"h","text":"实验目的","level":2},{"t":"p","text":"**1.** 以颜色与沉淀为判据，定性认识配合物的生成、组成、解离与稳定性。\n**2. **能写出配离子解离方程式并理解 K_{稳} 的含义。\n**3. **能依据现象判断内界与外界、平衡移动方向与稳定性相对大小。\n**4. **掌握逐滴加入、边加边摇、恰好溶解等基本操作，并遵守相应安全规范。"},{"t":"h","text":"反应原理","level":2},{"t":"p","text":"**配合物的解离与 K_{稳}**"},{"t":"p","text":"配合物由配离子与外界组成，属强电解质，完全解离；配离子是弱电解质，部分解离并存在平衡，其平衡常数 K_{稳} 越大，配离子越稳定。\n[Cu(NH₃)₄]SO₄ → [Cu(NH₃)₄]²⁺ + SO₄²⁻        ***==完全解离==***\n[Cu(NH₃)₄]²⁺ ⇌ Cu²⁺ + 4NH₃          ***==部分解离==***"},{"t":"p","text":"**使解离平衡移动的三条途径**"},{"t":"p","text":"**生成更难溶沉淀**：如 CuS、AgI。\n**消耗配体**：H⁺ 结合 NH₃。\n**生成更稳定配合物**：EDTA 螯合。\n多齿配体成环后稳定性显著提高，称为**螯合效应**，可用于 Mg²⁺ 等离子的鉴定。"},{"t":"h","text":"试剂与仪器","level":2},{"t":"p","text":"试剂（18 种）"},{"t":"p","text":"CuSO₄、CuCl₂、AgNO₃、FeCl₃、浓 HCl、氨水、NaOH、H₂SO₄、BaCl₂、Na₂S、NaF、KSCN、Na₂S₂O₃、KBr、KI、(NH₄)₂C₂O₄、EDTA、镁试剂Ⅰ。\n**提示**：其中 BaCl₂、(NH₄)₂C₂O₄、Na₂S、NaF、KSCN、AgNO₃ 为有毒或腐蚀性试剂，该类物质的取用规范见第一部分。"},{"t":"p","text":"**仪器**"},{"t":"p","text":"试管、试管夹、滴管、烧杯、玻璃棒、酒精灯、洗瓶。"}],"count":9},{"id":"procedure","title":"实验流程","hint":"按顺序做什么","blocks":[{"t":"h","text":"腐蚀性酸碱","level":2},{"t":"p","text":"**强腐蚀性试剂与取用规范**"},{"t":"p","text":"浓 HCl、NaOH、H₂SO₄ 具强腐蚀性。取用时**需戴手套与护目镜，标签朝手心、瓶塞倒放在桌面上**。"},{"t":"p","text":"**稀释浓硫酸的正确方法**"},{"t":"p","text":"必须\"酸入水、边加边搅拌\"。把水倒入浓硫酸会剧烈放热、液滴飞溅。"},{"t":"p","text":"**皮肤沾到酸碱怎么办**"},{"t":"p","text":"立即用大量流水冲洗至少 15 分钟；沾到酸时应使用饱和 NaHCO₃冲洗，沾到碱则是使用 1% 醋酸，严重者需要及时就医。"},{"t":"h","text":"==不准把水倒入浓硫酸。==","level":3},{"t":"h","text":"实验内容与操作重难点","level":2},{"t":"p","text":"本实验以颜色与沉淀为语言，把配位平衡的生成、组成、移动与稳定性串成一条主线。"},{"t":"p","text":"实验目的 → 反应原理 → K稳 数据 → 试剂与仪器 → 五步操作流程 → 重难点①~⑤（逐滴加氨水 / 内外界检验 / 平衡移动 / 配体竞争 / 螯合鉴定）。","html":"实验目的 → 反应原理 → K<sub>稳</sub> 数据 → 试剂与仪器 → 五步操作流程 → 重难点①~⑤（逐滴加氨水 / 内外界检验 / 平衡移动 / 配体竞争 / 螯合鉴定）。"},{"t":"p","text":"实验的首要标准：用 K_{稳} 判断稳定性，用因果链解释现象，用规范操作保证现象可信。"},{"t":"h","text":"本实验涉及的配离子 K_{稳}（298 K）","level":2},{"t":"table","rows":[["配离子","中心离子","配体","lg K稳","K稳","K不稳"],["[Cu(NH₃)₄]²⁺","Cu²⁺","NH₃","13.32","≈2.1×10¹³","≈4.8×10⁻¹⁴"],["[Ag(NH₃)₂]⁺","Ag⁺","NH₃","7.05","≈1.1×10⁷","≈9.1×10⁻⁸"],["[Fe(SCN)]²⁺","Fe³⁺","SCN⁻","2.09","≈1.2×10²","≈8.3×10⁻³"],["[Ag(CN)₂]⁻","Ag⁺","CN⁻","21.10","≈1.3×10²¹","≈7.7×10⁻²²"],["[CuY]²⁻","Cu²⁺","Y⁴⁻","18.80","≈6.3×10¹⁸","≈1.6×10⁻¹⁹"],["[FeY]⁻","Fe³⁺","Y⁴⁻","25.10","≈1.3×10²⁵","≈7.7×10⁻²⁶"],["[MgY]²⁻","Mg²⁺","Y⁴⁻","8.70","≈5.0×10⁸","≈2.0×10⁻⁹"]]},{"t":"p","text":"表 1　比较稳定性的标准"},{"t":"p","text":"用表的方法：两体系比较稳定性，直接比 lg K稳；现象与 K稳 对不上号时，先查表再下结论。","html":"用表的方法：两体系比较稳定性，直接比 lg K<sub>稳</sub>；现象与 K<sub>稳</sub> 对不上号时，先查表再下结论。"},{"t":"h","text":"操作流程：五步走","level":2},{"t":"p","text":"**① 制备**"},{"t":"p","text":"向CuSO₄ 中逐滴加氨水至沉淀恰好溶解，得深蓝色溶液。"},{"t":"p","text":"**② 检验**"},{"t":"p","text":"加 NaOH ，无沉淀；加 BaCl₂ ，产生白色沉淀。"},{"t":"p","text":"**③ 移动**"},{"t":"p","text":"加 Na₂S 生成黑色 CuS、加 HCl 蓝色褪去——平衡右移。"},{"t":"p","text":"**④ 比较**"},{"t":"p","text":"Fe³⁺—KSCN—EDTA—NaF 体系；Ag⁺ 的沉淀—配位—再沉淀。"},{"t":"p","text":"**⑤ 螯合**"},{"t":"p","text":"铜氨溶液加 EDTA 褪色；Mg²⁺ 加氨水与镁试剂Ⅰ生成蓝色螯合物。"},{"t":"h","text":"逐滴加氨水制备铜氨配离子","level":2},{"t":"p","text":"**重难点拆解**"},{"t":"p","text":"**操作要点**：氨水逐滴加入，每加一滴充分振荡，以\"沉淀恰好完全溶解\"为度。\n**为什么难**：体系中两步反应共存：氨水少量时生成 Cu(OH)₂ 沉淀，氨水过量时 NH₃ 的配位作用占优、沉淀转化为 [Cu(NH₃)₄]²⁺。判断配位何时占优，只能依靠观察是否刚好到**“沉淀恰好消失、溶液转深蓝”**这一临界点。\n**常见误差点**：氨水不足则沉淀未溶，后续颜色偏浅；过量太多则残留游离 NH₃ 干扰加酸、加碱现象；加得太快、未振荡会冲过临界点。\n**可行的改进措施**：慢加、勤摇，临近终点改为半滴加入。"},{"t":"fig","src":"assets/exps/e02/i05.png","caption":"图 5　逐滴加入并振荡：一次一滴、边加边摇、至恰好溶解","w":300,"h":210},{"t":"h","text":"内界与外界的检验","level":2},{"t":"p","text":"**重难点拆解**"},{"t":"p","text":"**操作要点**：两支试管分别加 NaOH 与 BaCl₂，现象对照着看：一个无沉淀、一个有沉淀。\n**为什么难**：现象用于反推结构。K_{稳}([Cu(NH₃)₄]²⁺)=2.1×10¹³，自由 Cu²⁺ 被压得极低，加入碱后 c(Cu²⁺)·c²(OH⁻) 仍达不到 Cu(OH)₂ 的溶度积，故无沉淀；而 SO₄²⁻ 在外界，可被 Ba²⁺ 自由检出。\n**常见误差点**：试管未洗净残留 Cu²⁺ 会出现假沉淀；滴管混用会引入干扰离子。\n**可行的改进措施**：必须洁净试管、试剂专用滴管。"},{"t":"h","text":"解离平衡的移动","level":2},{"t":"p","text":"**重难点拆解**"},{"t":"p","text":"**操作要点**：取铜氨溶液，一份滴加 Na₂S 溶液，一份逐滴加入 HCl，分别观察沉淀与颜色变化。\n**为什么难**：现象要用来判断平衡移动方向。加 Na₂S 时，S²⁻ 与溶液中极少量自由 Cu²⁺ 生成极难溶的 CuS，使配位平衡向解离方向移动，蓝色褪去并出现黑色沉淀；加酸时 H⁺ 与 NH₃ 结合，同样使平衡向解离方向移动。\n常见误差点：把加 Na₂S 的变色误当作氧化还原；加酸过快使局部过量、沉淀与褪色现象重叠，难以观察。\n\n可行的改进措施：逐滴加入、边加边摇，并与未加试剂的试管对照。"},{"t":"fig","src":"assets/exps/e02/i06.png","caption":"图 6　铜氨溶液的平衡移动：加 Na₂S 生成黑色 CuS、加 HCl 蓝色褪去","w":300,"h":225},{"t":"h","text":"配体竞争与稳定性比较","level":2},{"t":"p","text":"**重难点拆解**"},{"t":"p","text":"常见误差点：铁体系按\"先 KSCN 显色、再 EDTA 褪色、另取一份加 NaF\"进行；银体系按\"沉淀—溶解—再沉淀\"逐步推进。\n**为什么难**：需把现象与 K_{稳} 进行匹配。 K_{稳}([Fe(SCN)]²⁺) = 1.2×10²，K_{稳 }([FeY]⁻) = 1.3×10²⁵，相差约 23 个数量级，故加入 EDTA 的瞬间红色会立即消失；银体系则要同时看 K_{sp} 与 K_{稳}，沉淀能否生成取决于自由 Ag⁺ 是否足以超过该沉淀的溶度积。\n常见误差点：把\"沉淀溶解\"误当反应结束（实际生成配离子，仍可继续加沉淀剂）；一次加大量试剂越过中间现象；忘记保留上一支试管作对照。"},{"t":"h","text":"螯合物与 Mg²⁺ 鉴定","level":2},{"t":"p","text":"**重难点拆解**"},{"t":"p","text":"**操作要点**：铜氨溶液加 EDTA逐滴加入并振荡；Mg²⁺ 鉴定先加氨水调碱性，再滴镁试剂Ⅰ。\n**为什么难**：螯合效应源于多齿成环——一个 EDTA 分子占据多个配位点、形成多个五元环，熵变有利，稳定性大幅提高。Mg²⁺ 鉴定受 pH 控制，酸性条件下不显色。\n**常见误差点**：镁试剂过量会掩盖蓝色；氨水不足或试管不洁造成假阴性。\n**可行的改进措施**：建议同时做\"蒸馏水 + 氨水 + 镁试剂\"空白对照。"},{"t":"fig","src":"assets/exps/e02/i07.jpg","caption":"图 7　碱性条件下镁试剂Ⅰ与 Mg²⁺ 生成蓝色螯合物（示意图，AI 生成）","w":790,"h":864},{"t":"h","text":"六条规范与小结","level":2},{"t":"p","text":"**六条规范**"},{"t":"p","text":"逐滴加入、边加边摇、少量为宜、专管专用、及时记录、废液分类。"},{"t":"p","text":"**小结**\n本次实验的重点是抓住这三件事："},{"t":"p","text":"用 K稳 判断稳定性；\n用因果链解释现象；\n用规范操作保证现象可信。","html":"用 K<sub>稳</sub> 判断稳定性；\n用因果链解释现象；\n用规范操作保证现象可信。"},{"t":"p","text":"结束实验后需要整理实验仪器，请注意确认：银氨溶液酸化了吗？废液分类了吗？试管洗了吗？"}],"count":40},{"id":"thinking","title":"实验思考","hint":"做完再想一遍","blocks":[{"t":"h","text":"滴加氨水时为什么要逐滴加入并边加边摇？","level":3},{"t":"p","text":"逐滴加入、边加边摇可以及时观察到沉淀的生成与恰好溶解，避免氨水局部过量导致配合物直接生成而错过中间现象，也能防止反应过于剧烈、溶液溅出。"},{"t":"h","text":"如何检验配离子的内界与外界？","level":3},{"t":"p","text":"内界配体在配离子内部，不与溶液中其他离子直接反应；外界离子可被沉淀剂检出。例如向 [Cu(NH₃)₄]SO₄ 溶液中加 BaCl₂ 会产生 BaSO₄ 沉淀，而加 NaOH 不产生 Cu(OH)₂ 沉淀，说明 Cu²⁺ 在内界、SO₄²⁻ 在外界。"},{"t":"h","text":"银氨溶液为什么必须现配现用？","level":3},{"t":"p","text":"银氨溶液久置或蒸干会生成雷爆银（Ag₃N 等），受摩擦、震动可能爆炸。使用后应立即加稀盐酸酸化破坏，倒入含银废液瓶，用过即洗，严禁久存、严禁蒸干、严禁倒入水槽。"},{"t":"h","text":"加入 Na₂S 后沉淀溶解平衡向哪个方向移动？","level":3},{"t":"p","text":"S²⁻ 与 Ag⁺ 生成更难溶的 Ag₂S，使溶液中 Ag⁺ 浓度大幅降低，AgCl（或 AgI）的溶解平衡向溶解方向移动并转化为 Ag₂S 沉淀。沉淀转化的方向由两种难溶物溶度积的相对大小决定，Ksp 更小的更稳定。","html":"S²⁻ 与 Ag⁺ 生成更难溶的 Ag₂S，使溶液中 Ag⁺ 浓度大幅降低，AgCl（或 AgI）的溶解平衡向溶解方向移动并转化为 Ag₂S 沉淀。沉淀转化的方向由两种难溶物溶度积的相对大小决定，K<sub>sp</sub> 更小的更稳定。"},{"t":"h","text":"配合物的稳定性用什么衡量？","level":3},{"t":"p","text":"用稳定常数 K稳（或 β）衡量：K稳 越大，配离子越稳定，解离程度越小。比较不同配体对同一中心离子的配位能力时，可比较对应配离子的 K稳。","html":"用稳定常数 K<sub>稳</sub>（或 β）衡量：K<sub>稳</sub> 越大，配离子越稳定，解离程度越小。比较不同配体对同一中心离子的配位能力时，可比较对应配离子的 K<sub>稳</sub>。"},{"t":"h","text":"为什么配位平衡会受酸度影响？","level":3},{"t":"p","text":"许多配体（如 NH₃、S₂O₃²⁻、F⁻）是弱碱或弱酸根，加酸会使其质子化、有效浓度下降，配离子随之解离；反之加碱可能生成氢氧化物沉淀。因此配位平衡与酸碱平衡、沉淀平衡相互影响。"}],"count":6,"qa":[{"q":"滴加氨水时为什么要逐滴加入并边加边摇？","a":"逐滴加入、边加边摇可以及时观察到沉淀的生成与恰好溶解，避免氨水局部过量导致配合物直接生成而错过中间现象，也能防止反应过于剧烈、溶液溅出。"},{"q":"如何检验配离子的内界与外界？","a":"内界配体在配离子内部，不与溶液中其他离子直接反应；外界离子可被沉淀剂检出。例如向 [Cu(NH₃)₄]SO₄ 溶液中加 BaCl₂ 会产生 BaSO₄ 沉淀，而加 NaOH 不产生 Cu(OH)₂ 沉淀，说明 Cu²⁺ 在内界、SO₄²⁻ 在外界。"},{"q":"银氨溶液为什么必须现配现用？","a":"银氨溶液久置或蒸干会生成雷爆银（Ag₃N 等），受摩擦、震动可能爆炸。使用后应立即加稀盐酸酸化破坏，倒入含银废液瓶，用过即洗，严禁久存、严禁蒸干、严禁倒入水槽。"},{"q":"加入 Na₂S 后沉淀溶解平衡向哪个方向移动？","a":"S²⁻ 与 Ag⁺ 生成更难溶的 Ag₂S，使溶液中 Ag⁺ 浓度大幅降低，AgCl（或 AgI）的溶解平衡向溶解方向移动并转化为 Ag₂S 沉淀。沉淀转化的方向由两种难溶物溶度积的相对大小决定，Ksp 更小的更稳定。"},{"q":"配合物的稳定性用什么衡量？","a":"用稳定常数 K稳（或 β）衡量：K稳 越大，配离子越稳定，解离程度越小。比较不同配体对同一中心离子的配位能力时，可比较对应配离子的 K稳。"},{"q":"为什么配位平衡会受酸度影响？","a":"许多配体（如 NH₃、S₂O₃²⁻、F⁻）是弱碱或弱酸根，加酸会使其质子化、有效浓度下降，配离子随之解离；反之加碱可能生成氢氧化物沉淀。因此配位平衡与酸碱平衡、沉淀平衡相互影响。"}]}],"qa":[{"q":"滴加氨水时为什么要逐滴加入并边加边摇？","a":"逐滴加入、边加边摇可以及时观察到沉淀的生成与恰好溶解，避免氨水局部过量导致配合物直接生成而错过中间现象，也能防止反应过于剧烈、溶液溅出。"},{"q":"如何检验配离子的内界与外界？","a":"内界配体在配离子内部，不与溶液中其他离子直接反应；外界离子可被沉淀剂检出。例如向 [Cu(NH₃)₄]SO₄ 溶液中加 BaCl₂ 会产生 BaSO₄ 沉淀，而加 NaOH 不产生 Cu(OH)₂ 沉淀，说明 Cu²⁺ 在内界、SO₄²⁻ 在外界。"},{"q":"银氨溶液为什么必须现配现用？","a":"银氨溶液久置或蒸干会生成雷爆银（Ag₃N 等），受摩擦、震动可能爆炸。使用后应立即加稀盐酸酸化破坏，倒入含银废液瓶，用过即洗，严禁久存、严禁蒸干、严禁倒入水槽。"},{"q":"加入 Na₂S 后沉淀溶解平衡向哪个方向移动？","a":"S²⁻ 与 Ag⁺ 生成更难溶的 Ag₂S，使溶液中 Ag⁺ 浓度大幅降低，AgCl（或 AgI）的溶解平衡向溶解方向移动并转化为 Ag₂S 沉淀。沉淀转化的方向由两种难溶物溶度积的相对大小决定，Ksp 更小的更稳定。"},{"q":"配合物的稳定性用什么衡量？","a":"用稳定常数 K稳（或 β）衡量：K稳 越大，配离子越稳定，解离程度越小。比较不同配体对同一中心离子的配位能力时，可比较对应配离子的 K稳。"},{"q":"为什么配位平衡会受酸度影响？","a":"许多配体（如 NH₃、S₂O₃²⁻、F⁻）是弱碱或弱酸根，加酸会使其质子化、有效浓度下降，配离子随之解离；反之加碱可能生成氢氧化物沉淀。因此配位平衡与酸碱平衡、沉淀平衡相互影响。"}],"order":2,"hidden":false,"visibleAt":""},"inorganic/e03":{"id":"e03","no":3,"name":"硫酸铜晶体制备","full":"用废硫酸铜溶液制备五水合硫酸铜晶体","cards":[{"id":"safety","title":"安全教育","hint":"进实验室前先读完","blocks":[{"t":"h","text":"本实验安全要点","level":3},{"t":"kv","k":"要点1","v":"3 mol/L 硫酸具腐蚀性：戴护目镜与手套，补加水沿壁缓慢加入。"},{"t":"kv","k":"要点2","v":"马弗炉 700~800 ℃：坩埚必须用坩埚钳取放，开炉门避开面部热浪。"},{"t":"kv","k":"要点3","v":"减压过滤：先开水泵后倒液，结束先放气再关泵，防止倒吸。"},{"t":"kv","k":"要点4","v":"含铜废液、母液全部倒入含铜回收桶；碎玻璃用扫帚收集。"},{"t":"h","text":"先看后动：三条底线","level":2},{"t":"p","text":"**总体要求**"},{"t":"p","text":"本实验涉及腐蚀性酸、明火加热、700 ℃ 以上高温灼烧和减压过滤。进入实验室前请记住三条底线：\n**先看后动**：没弄清楚操作规范前，不动仪器、不取药品。\n**废液分类回收**：含铜废液、母液一律倒入指定回收桶，不得倒入水槽。\n**不单独行动**：马弗炉、酒精灯使用时同组同学互相提醒，离岗先断火断电。"},{"t":"p","text":"任何意外第一时间报告指导老师，不要自行隐瞒处理。"}],"count":7},{"id":"purpose","title":"实验目的","hint":"为什么做、依据是什么","blocks":[{"t":"h","text":"减压过滤与玻璃仪器","level":2},{"t":"p","text":"减压过滤与玻璃仪器安全"},{"t":"p","text":"**布氏漏斗与吸滤瓶**：在使用前需要确保橡皮塞塞紧不漏气，且滤纸略小于漏斗内径并用水润湿贴紧。\n**开停顺序**：先开水泵后倒液；过滤结束先拔开瓶塞（或放气）再关水泵，防止倒吸。\n**倾析法转移**：铜粉等粗颗粒先用倾析法倒出上层清液，减少滤纸堵塞。\n**玻璃仪器轻拿轻放**：碎玻璃不得徒手捡拾，用扫帚簸箕收集并投入锐器盒。"},{"t":"p","text":"减压过滤时需要注意顺序：开水泵 → 倒液 → 拔塞放气 → 关水泵。颠倒实验顺序可能会发生倒吸现象。"},{"t":"h","text":"实验目的","level":2},{"t":"p","text":"本节要掌握什么"},{"t":"p","text":"**1. **掌握基本操作：蒸发浓缩、减压过滤、重结晶等基本操作。\n**2. **理解提纯原理：了解重结晶提纯物质的基本原理。"},{"t":"p","text":"本实验最终要拿到的是蓝色五水合硫酸铜晶体，并算出产率与收率。"},{"t":"h","text":"反应原理与结晶提纯","level":2},{"t":"h","text":"三步反应，一条路线","level":3},{"t":"p","text":"实验路线：铁置换得铜 → 灼烧成氧化铜 → 酸溶得硫酸铜 → 冷却结晶提纯。\n用铁片置换废液中的铜（II）得单质铜。由于纯铜属不活泼金属，不能溶于非氧化性的酸，因此先把铜灼烧成氧化铜，然后与适当浓度的硫酸反应生成硫酸铜。反应方程式为：\nCuSO_{4} + Fe = Cu + FeSO_{4}\n*==**（置换反应）**==*\n2Cu + O_{2} = 2CuO\n*==**（灼烧）**==*\nCuO + H_{2}SO_{4} = CuSO_{4} + H_{2}O\n*==**（酸溶）**==*\n当溶液蒸发浓缩后冷却到一定温度时处于过饱和状态，随着温度继续下降，硫酸铜晶体不断从溶液中析出；其他可溶性杂质通过重结晶的方法除去，最终制得纯净的五水合硫酸铜晶体（CuSO_{4}·5H_{2}O，蓝色）。"},{"t":"h","text":"仪器与药品","level":2},{"t":"p","text":"**仪器**\n蒸发皿、烧杯（150 mL）、布氏漏斗、吸滤瓶、研钵、坩埚、量筒（100 mL、10 mL）、三脚架、石棉网、马弗炉\n**药品**\nH_{2}SO_{4} 溶液（3 mol/L）、铁片 2~3 片、废硫酸铜溶液、蒸馏水、滤纸"},{"t":"p","text":"开工前请核对：坩埚钳、护目镜、洗眼器的位置确认到位后再开始实验。"}],"count":9},{"id":"procedure","title":"实验流程","hint":"按顺序做什么","blocks":[{"t":"h","text":"1　置换铜","level":3},{"t":"p","text":"取 2~3 片铁片用砂纸打磨光亮，置于 150 mL 烧杯中，加入 100 mL 废硫酸铜溶液；为加快反应速率可用酒精灯微热进行置换反应。待铁片上出现棕红色铜粉后，将铜粉刮入清水中（清水中可滴入几滴硫酸，防止铁混入）。反复置换，直到废液由蓝色变为浅绿色为止。"},{"t":"h","text":"2　过滤与烘干","level":3},{"t":"p","text":"以倾析法倒入布氏漏斗中减压过滤，清洗几次后置于蒸发皿中小火烘干，注意防止铜粉氧化变黑。"},{"t":"p","text":"判断终点：废液由蓝色变为浅绿色，说明铜已基本置换完全。"},{"t":"h","text":"3　灼烧 → 酸溶 → 浓缩结晶","level":3},{"t":"p","text":"将烘干的铜粉研碎，称取 3 g 置于坩埚，放入马弗炉于 700~800 ℃ 灼烧 5 min；取出研细后再灼烧 15 min，反复“研碎—灼烧”三次。之后置于蒸发皿中加入 20 mL 3 mol/L 硫酸溶液，加热溶解，溶解过程中根据反应情况适当补充水，直至固体全部溶解；若仍有不溶性残渣，趁热减压过滤。\n滤液转入洗净的蒸发皿中，水浴加热浓缩至表面出现晶膜为止；取下蒸发皿置于冷水上冷却，即有蓝色五水合硫酸铜晶体析出，冷却至室温后抽滤、称量、计算产率。"},{"t":"p","text":"两次停留点：“研碎—灼烧”共三次；“晶膜出现”即停火，不要烧干。"},{"t":"h","text":"4　重结晶","level":3},{"t":"p","text":"粗产品按每克加 1.2 mL 水的比例溶于蒸馏水，加热完全溶解后趁热过滤；滤液收集于小烧杯中缓慢冷却析晶（如无晶体析出，可再加热蒸发稍微浓缩）。冷却后用抽滤法除去母液，晶体干燥后再放在两层滤纸间挤压吸干，置于表面皿上称量、计算收率，母液回收。"},{"t":"p","text":"产率参考公式：产率 = 实际产量 ÷ 理论产量 × 100%。理论产量可按 3 g 铜全部转化估算（约 11.8 g CuSO4·5H2O）。","html":"产率参考公式：产率 = 实际产量 ÷ 理论产量 × 100%。理论产量可按 3 g 铜全部转化估算（约 11.8 g CuSO<sub>4</sub>·5H<sub>2</sub>O）。"},{"t":"h","text":"补充材料一：AI 帮你计算产率","level":2},{"t":"p","text":"AI 可以帮助我们更快速地得出计算结果，同时还能详细分析产率偏高或偏低的原因，帮助快速检误。\n**二维码涉及的工具是一款在线产率计算器。**\n步骤：扫描下方二维码，输入单质铜质量与硫酸铜晶体质量即可得出理论产量、实际产量与产率。"},{"t":"fig","src":"assets/exps/e03/i01.png","caption":"图 1　产率计算工具二维码（第三方在线工具）","w":369,"h":369},{"t":"h","text":"算例：3 g 铜得 81.4% 产率","level":2},{"t":"fig","src":"assets/exps/e03/i02.png","caption":"图 2　产率计算示例：3 g 铜粉，理论产量 11.788 g，实际 9.600 g，产率 81.4%","alt":"","w":380,"h":525},{"t":"p","text":"注意点：AI 正确率很高，但不排除偶然失误，且没有详细过程，需要时可继续询问 AI 得到详细步骤。"},{"t":"h","text":"补充材料二：AI 锐评晶体质量","level":2},{"t":"p","text":"优点：在不太清楚辨别方式的情况下给出一定判别依据，提高认知；此外还能针对各组给出改进建议。\n步骤：扫描下方二维码，选择你的晶体图片即可。评价系统会从透明度、对称性、尺寸、棱角清晰度四项给出评分。"},{"t":"fig","src":"assets/exps/e03/i03.png","caption":"图 3　晶体质量评价系统二维码（第三方在线工具）","w":370,"h":370},{"t":"h","text":"评分示例：四项打分","level":2},{"t":"fig","src":"assets/exps/e03/i04.png","caption":"图 4　晶体评价示例：从透明度、对称性、尺寸、棱角清晰度四项打分（工具界面截图）","w":380,"h":273},{"t":"p","text":"如何用分：评价从透明度、对称性、尺寸、棱角清晰度四项给出，可作为各组改进晶体质量的参考。"},{"t":"h","text":"识别注意点与使用边界","level":2},{"t":"p","text":"**注意点**"},{"t":"p","text":"该工具并非专业识别工具，识别结果只能说有较高可信度、但非尽然；**==有条件的同学可看能否获得厦门大学的晶体识别 APP。==**"},{"t":"p","text":"AI 使用提醒：AI 随好，不能贪杯。它可以帮助我们快速解决一些问题，但也会让人养成一遇到问题就“提问 AI”的习惯，可能不利于独立思考。当把握好度——有它也要有自己的思考。"},{"t":"kv","k":"工具一","v":"产率计算器：输入单质铜质量与硫酸铜晶体质量，得出理论产量、实际产量与产率。"},{"t":"kv","k":"工具二","v":"晶体质量评分系统：对照透明度、对称性、尺寸、棱角清晰度四项给晶体评分。提供理论识别要点，供对照判断晶体外观是否合格。"},{"t":"h","text":"实验结束操作","level":3},{"t":"p","text":"**母液回收**：重结晶后的母液倒入指定回收瓶。\n**数据记录**：铜粉质量、晶体质量当场记好，产率当堂计算。\n**整理台面**：玻璃仪器洗净归位，断火断电后再离开实验室。"},{"t":"p","text":"预祝实验顺利。如在预习或操作中有疑问，请及时与指导老师沟通。"}],"count":22},{"id":"thinking","title":"实验思考","hint":"做完再想一遍","blocks":[{"t":"h","text":"什么情况下用倾析法、常压过滤、减压过滤？","level":3},{"t":"p","text":"倾析法适合颗粒大、易沉降的固液分离，先倒出上层清液；常压过滤适合一般沉淀分离；减压过滤适合晶体颗粒较大、需要快速抽干的分离，细胶体沉淀容易堵塞滤纸，不宜减压过滤。"},{"t":"h","text":"蒸发浓缩硫酸铜溶液时为什么要水浴加热？","level":3},{"t":"p","text":"水浴受热均匀、温度易控，可避免直接加热造成局部过热、液滴飞溅和晶体溅失，也能防止蒸发皿骤热开裂。溶液表面出现晶膜即应停止加热。"},{"t":"h","text":"铜粉灼烧为什么要反复“研碎—灼烧”三次？","level":3},{"t":"p","text":"铜粉颗粒内部在首次灼烧时可能未完全氧化，研碎后暴露新鲜表面再灼烧，可使氧化更彻底。氧化不完全会导致后续酸溶残留、产率偏低。"},{"t":"h","text":"重结晶提纯的原理是什么？为什么要按每克粗产品加 1.2 mL 水？","level":3},{"t":"p","text":"利用目标物与杂质在溶剂中溶解度随温度变化差异：高温溶解、低温析晶，杂质留在母液中。加水量太少溶解不完全，太多则收率降低，1.2 mL/g 是兼顾溶解与收率的经验值。"},{"t":"h","text":"产率与收率有什么区别？","level":3},{"t":"p","text":"产率 = 实际产量 ÷ 理论产量 × 100%，理论产量按 3 g 铜全部转化估算；收率侧重实际得到的合格产品比例。两者都反映操作损失，偏差大时应回查过滤、转移、结晶各步。"},{"t":"h","text":"含铜废液应该怎么处理？","level":3},{"t":"p","text":"废硫酸铜溶液、母液、洗涤液均属重金属废液，必须倒入指定含铜废液回收桶，不得倒入水槽；含铜固体残渣单独收集，交由实验室统一处理。"}],"count":6,"qa":[{"q":"什么情况下用倾析法、常压过滤、减压过滤？","a":"倾析法适合颗粒大、易沉降的固液分离，先倒出上层清液；常压过滤适合一般沉淀分离；减压过滤适合晶体颗粒较大、需要快速抽干的分离，细胶体沉淀容易堵塞滤纸，不宜减压过滤。"},{"q":"蒸发浓缩硫酸铜溶液时为什么要水浴加热？","a":"水浴受热均匀、温度易控，可避免直接加热造成局部过热、液滴飞溅和晶体溅失，也能防止蒸发皿骤热开裂。溶液表面出现晶膜即应停止加热。"},{"q":"铜粉灼烧为什么要反复“研碎—灼烧”三次？","a":"铜粉颗粒内部在首次灼烧时可能未完全氧化，研碎后暴露新鲜表面再灼烧，可使氧化更彻底。氧化不完全会导致后续酸溶残留、产率偏低。"},{"q":"重结晶提纯的原理是什么？为什么要按每克粗产品加 1.2 mL 水？","a":"利用目标物与杂质在溶剂中溶解度随温度变化差异：高温溶解、低温析晶，杂质留在母液中。加水量太少溶解不完全，太多则收率降低，1.2 mL/g 是兼顾溶解与收率的经验值。"},{"q":"产率与收率有什么区别？","a":"产率 = 实际产量 ÷ 理论产量 × 100%，理论产量按 3 g 铜全部转化估算；收率侧重实际得到的合格产品比例。两者都反映操作损失，偏差大时应回查过滤、转移、结晶各步。"},{"q":"含铜废液应该怎么处理？","a":"废硫酸铜溶液、母液、洗涤液均属重金属废液，必须倒入指定含铜废液回收桶，不得倒入水槽；含铜固体残渣单独收集，交由实验室统一处理。"}]}],"qa":[{"q":"什么情况下用倾析法、常压过滤、减压过滤？","a":"倾析法适合颗粒大、易沉降的固液分离，先倒出上层清液；常压过滤适合一般沉淀分离；减压过滤适合晶体颗粒较大、需要快速抽干的分离，细胶体沉淀容易堵塞滤纸，不宜减压过滤。"},{"q":"蒸发浓缩硫酸铜溶液时为什么要水浴加热？","a":"水浴受热均匀、温度易控，可避免直接加热造成局部过热、液滴飞溅和晶体溅失，也能防止蒸发皿骤热开裂。溶液表面出现晶膜即应停止加热。"},{"q":"铜粉灼烧为什么要反复“研碎—灼烧”三次？","a":"铜粉颗粒内部在首次灼烧时可能未完全氧化，研碎后暴露新鲜表面再灼烧，可使氧化更彻底。氧化不完全会导致后续酸溶残留、产率偏低。"},{"q":"重结晶提纯的原理是什么？为什么要按每克粗产品加 1.2 mL 水？","a":"利用目标物与杂质在溶剂中溶解度随温度变化差异：高温溶解、低温析晶，杂质留在母液中。加水量太少溶解不完全，太多则收率降低，1.2 mL/g 是兼顾溶解与收率的经验值。"},{"q":"产率与收率有什么区别？","a":"产率 = 实际产量 ÷ 理论产量 × 100%，理论产量按 3 g 铜全部转化估算；收率侧重实际得到的合格产品比例。两者都反映操作损失，偏差大时应回查过滤、转移、结晶各步。"},{"q":"含铜废液应该怎么处理？","a":"废硫酸铜溶液、母液、洗涤液均属重金属废液，必须倒入指定含铜废液回收桶，不得倒入水槽；含铜固体残渣单独收集，交由实验室统一处理。"}],"order":3,"hidden":false,"visibleAt":""},"inorganic/e04":{"id":"e04","no":4,"name":"溶解平衡","full":"溶解平衡（性质类实验）","cards":[{"id":"safety","title":"安全教育","hint":"进实验室前先读完","blocks":[{"t":"h","text":"本实验安全要点","level":3},{"t":"kv","k":"要点1","v":"AgNO₃ 具腐蚀性与光敏性，接触皮肤留黑斑，须戴手套、避光保存。"},{"t":"kv","k":"要点2","v":"Pb(NO₃)₂、BaCl₂ 等重金属盐严禁皮肤接触，废液分类回收。"},{"t":"kv","k":"要点3","v":"浓氨水、强碱在通风处取用，溅到立即冲洗 ≥15 min。"},{"t":"kv","k":"要点4","v":"恒温槽与水浴防烫伤，玻璃移液管防割伤，取上层清液避免吸入固体。"},{"t":"h","text":"溶解平衡实验安全注意事项","level":2},{"t":"p","text":"1. 个人防护：实验全程佩戴护目镜、穿实验服并戴丁腈手套；AgNO₃、Pb(NO₃)₂、BaCl₂ 等重金属盐严禁皮肤直接接触。"},{"t":"p","text":"2. 通风防刺激：浓盐酸、浓氨水、强碱等具有挥发性或刺激性的试剂须在通风处或通风橱内取用，防止酸雾、氨气刺激呼吸道。"},{"t":"p","text":"3. 腐蚀防护：稀释浓酸务必“酸入水”并缓慢搅拌；若溅到皮肤立即用大量流动清水冲洗至少 15 分钟，溅入眼睛用洗眼器冲洗并及时就医。"},{"t":"p","text":"4. 废液分类：银盐、铅盐、钡盐等重金属废液严禁倒入水槽，必须分类收集至专用废液桶统一回收处理。"},{"t":"p","text":"5. 仪器规范：胶头滴管专管专用，不可平放或倒置；加热液体需垫石棉网或用水浴，破损玻璃器皿放入锐器盒，不混入普通垃圾。"},{"t":"p","text":"6. 试剂储存：AgNO₃ 见光易分解释放有毒氮氧化物，须存于棕色瓶并远离酸碱及易燃物；Ca(OH)₂ 称量时佩戴口罩防粉尘刺激。"},{"t":"h","text":"重点难点及重大安全隐患须知","level":2},{"t":"p","text":"本次实验的目的是掌握平衡移动规律：理解离子积 Q 与 Ksp 的关系（Q > Ksp 生成沉淀、Q < Ksp 沉淀溶解、Q = Ksp 饱和）及沉淀转化规律。\n**AgNO₃ 具有腐蚀性与光敏性，接触皮肤留下难洗黑斑，操作须戴手套、有条件的情况下全程佩戴护目镜，废液入专用桶。**\n图1为 AgNO₃ 接触皮肤产生的黑斑，图2为废液专用桶。"},{"t":"fig","src":"assets/exps/e04/i02.jpg","caption":"图 1　AgNO₃ 沾到皮肤会留下难洗的黑斑","alt":"","w":250,"h":188},{"t":"fig","src":"assets/exps/e04/i03.jpg","caption":"图 2　实验室废液专用回收桶（分类收集，严禁倒入水槽）","alt":"","w":371,"h":366},{"t":"p","text":"难点——饱和溶液的恒温配制与取样：须恒温静置后准确取上层清液，严禁吸入底部固体；不同电解质（AB 型、A₂B 型）Ksp 与 S 换算关系不同，不可跨类型比较。重大安全隐患：恒温槽/水浴加热防烫伤，玻璃移液管防割伤。需佩戴手套。","html":"难点——饱和溶液的恒温配制与取样：须恒温静置后准确取上层清液，严禁吸入底部固体；不同电解质（AB 型、A₂B 型）K<sub>sp</sub> 与 S 换算关系不同，不可跨类型比较。重大安全隐患：恒温槽/水浴加热防烫伤，玻璃移液管防割伤。需佩戴手套。"},{"t":"fig","src":"assets/exps/e04/i04.jpg","caption":"图 3　AgCl → AgI → Ag₂S 沉淀转化（示意图，AI 生成）","alt":"","w":1152,"h":864},{"t":"p","text":"难点——分步沉淀 pH 控制与配位溶解：分步沉淀需精确控制 pH 范围，配位溶解使用浓氨水。重大安全隐患：浓氨水、强碱具强腐蚀与刺激性，必须通风橱操作，溅伤立即冲洗就医；重金属废液严禁倒入下水。"}],"count":16},{"id":"purpose","title":"实验目的","hint":"为什么做、依据是什么","blocks":[{"t":"h","text":"本实验要掌握什么","level":3},{"t":"p","text":"认识难溶电解质的沉淀溶解平衡，理解溶度积 Ksp 的物理意义。","html":"认识难溶电解质的沉淀溶解平衡，理解溶度积 K<sub>sp</sub> 的物理意义。"},{"t":"p","text":"掌握用离子积 Q 与 Ksp 的关系判断沉淀生成与溶解的方法。","html":"掌握用离子积 Q 与 K<sub>sp</sub> 的关系判断沉淀生成与溶解的方法。"},{"t":"p","text":"观察同离子效应、配位效应对溶解平衡的影响，理解 AgCl → AgI → Ag₂S 的沉淀转化规律。"},{"t":"p","text":"学习恒温配制饱和溶液、准确吸取上层清液的操作，测定 AgCl 的溶解度与溶度积。"},{"t":"h","text":"核心关系","level":3},{"t":"p","text":"AgCl(s) ⇌ Ag⁺(aq) + Cl⁻(aq)，Ksp = [Ag⁺][Cl⁻]；Q > Ksp 生成沉淀，Q < Ksp 沉淀溶解，Q = Ksp 达到平衡。","html":"AgCl(s) ⇌ Ag⁺(aq) + Cl⁻(aq)，K<sub>sp</sub> = [Ag⁺][Cl⁻]；Q &gt; K<sub>sp</sub> 生成沉淀，Q &lt; K<sub>sp</sub> 沉淀溶解，Q = K<sub>sp</sub> 达到平衡。"}],"count":5},{"id":"procedure","title":"实验流程","hint":"按顺序做什么","blocks":[{"t":"h","text":"实验流程","level":2},{"t":"p","text":"1. 沉淀生成：向试管中加入少量 0.1 mol/L AgNO₃ 溶液，逐滴加入 0.1 mol/L NaCl 溶液至不再产生白色沉淀（AgCl），建立沉淀溶解平衡。"},{"t":"p","text":"2. 沉淀溶解与转化：取部分浊液滴加浓氨水（或 Na₂S₂O₃ 溶液）观察沉淀溶解；向新生成 AgCl 浊液中依次滴加 KI 溶液、Na₂S 溶液，观察白色→黄色→黑色的颜色变化。"},{"t":"fig","src":"assets/exps/e04/i01.png","caption":"图 4　沉淀的生成与转化：AgCl 白色 → AgI 黄色 → Ag₂S 黑色（教材示意）","alt":"","w":260,"h":103},{"t":"p","text":"3. 溶度积测定（定量）：恒温下配制饱和溶液并静置沉降，用恒温移液管吸取上层清液，经滴定法或电导法测定饱和浓度，计算溶解度 S 与溶度积 Ksp。","html":"3. 溶度积测定（定量）：恒温下配制饱和溶液并静置沉降，用恒温移液管吸取上层清液，经滴定法或电导法测定饱和浓度，计算溶解度 S 与溶度积 K<sub>sp</sub>。"},{"t":"h","text":"补充材料：实验工具","level":3},{"t":"p","text":"AI可以帮助我们更快速地计算硝酸银溶度积。如下图所示的二维码中即是一款溶度积计算器，输入AgNO_{3}溶液和NaCl溶液的体积(单位：ml)和浓度(单位：mol·L^{-1})即可快速获得AgCl的溶度积数据\n（计算其它溶液时，请按实际情况进行替换）。"},{"t":"fig","src":"assets/exps/e04/i06.png","caption":"图 5　溶度积计算器二维码（第三方在线工具）"},{"t":"kv","k":"工具","v":"溶度积计算器：输入 AgNO₃ 与 NaCl 溶液的体积和浓度，得出 AgCl 的溶度积。"}],"count":7},{"id":"thinking","title":"实验思考","hint":"做完再想一遍","blocks":[{"t":"h","text":"如何用离子积 Q 与 Ksp 的关系判断沉淀的生成与溶解？","level":3},{"t":"p","text":"Q > Ksp 时生成沉淀，Q = Ksp 时达到饱和平衡，Q < Ksp 时沉淀溶解。改变溶液中某一离子的浓度，就会改变 Q，从而使平衡向生成或溶解的方向移动。","html":"Q &gt; K<sub>sp</sub> 时生成沉淀，Q = K<sub>sp</sub> 时达到饱和平衡，Q &lt; K<sub>sp</sub> 时沉淀溶解。改变溶液中某一离子的浓度，就会改变 Q，从而使平衡向生成或溶解的方向移动。"},{"t":"h","text":"同离子效应如何影响难溶电解质的溶解度？","level":3},{"t":"p","text":"加入含有相同离子的强电解质，会使溶解平衡向生成沉淀方向移动，溶解度降低。例如在 AgCl 饱和溶液中加入 NaCl，AgCl 的溶解度明显下降。"},{"t":"h","text":"沉淀转化的方向由什么决定？","level":3},{"t":"p","text":"由两种难溶物溶度积的相对大小决定：一般 Ksp 大的难溶物转化为 Ksp 小的难溶物，如 AgCl（白）→ AgI（黄）→ Ag₂S（黑）。转化能否发生还取决于两种沉淀剂浓度的相对大小。","html":"由两种难溶物溶度积的相对大小决定：一般 K<sub>sp</sub> 大的难溶物转化为 K<sub>sp</sub> 小的难溶物，如 AgCl（白）→ AgI（黄）→ Ag₂S（黑）。转化能否发生还取决于两种沉淀剂浓度的相对大小。"},{"t":"h","text":"为什么测定 Ksp 时必须恒温并取上层清液？","level":3},{"t":"p","text":"难溶电解质的溶解度随温度变化，必须恒温静置使体系达到平衡；取上层清液可避免吸入底部固体。若吸入固体，测得的溶液浓度偏高，Ksp 计算结果偏大。","html":"难溶电解质的溶解度随温度变化，必须恒温静置使体系达到平衡；取上层清液可避免吸入底部固体。若吸入固体，测得的溶液浓度偏高，K<sub>sp</sub> 计算结果偏大。"},{"t":"h","text":"为什么不同电解质类型的 Ksp 不能直接比较？","level":3},{"t":"p","text":"Ksp 与溶解度 S 的换算关系随电解质类型不同：AB 型 Ksp = S²，A₂B 型 Ksp = 4S³。只有同类型电解质才能用 Ksp 直接比较溶解度大小。","html":"K<sub>sp</sub> 与溶解度 S 的换算关系随电解质类型不同：AB 型 K<sub>sp</sub> = S²，A₂B 型 K<sub>sp</sub> = 4S³。只有同类型电解质才能用 K<sub>sp</sub> 直接比较溶解度大小。"},{"t":"h","text":"配位溶解为什么能使沉淀溶解？","level":3},{"t":"p","text":"配位剂与沉淀中的金属离子生成稳定配离子，使金属离子浓度大幅降低，Q < Ksp，沉淀随之溶解。例如 AgCl 可溶于氨水生成 [Ag(NH₃)₂]⁺。","html":"配位剂与沉淀中的金属离子生成稳定配离子，使金属离子浓度大幅降低，Q &lt; K<sub>sp</sub>，沉淀随之溶解。例如 AgCl 可溶于氨水生成 [Ag(NH₃)₂]⁺。"}],"count":6,"qa":[{"q":"如何用离子积 Q 与 Ksp 的关系判断沉淀的生成与溶解？","a":"Q > Ksp 时生成沉淀，Q = Ksp 时达到饱和平衡，Q < Ksp 时沉淀溶解。改变溶液中某一离子的浓度，就会改变 Q，从而使平衡向生成或溶解的方向移动。"},{"q":"同离子效应如何影响难溶电解质的溶解度？","a":"加入含有相同离子的强电解质，会使溶解平衡向生成沉淀方向移动，溶解度降低。例如在 AgCl 饱和溶液中加入 NaCl，AgCl 的溶解度明显下降。"},{"q":"沉淀转化的方向由什么决定？","a":"由两种难溶物溶度积的相对大小决定：一般 Ksp 大的难溶物转化为 Ksp 小的难溶物，如 AgCl（白）→ AgI（黄）→ Ag₂S（黑）。转化能否发生还取决于两种沉淀剂浓度的相对大小。"},{"q":"为什么测定 Ksp 时必须恒温并取上层清液？","a":"难溶电解质的溶解度随温度变化，必须恒温静置使体系达到平衡；取上层清液可避免吸入底部固体。若吸入固体，测得的溶液浓度偏高，Ksp 计算结果偏大。"},{"q":"为什么不同电解质类型的 Ksp 不能直接比较？","a":"Ksp 与溶解度 S 的换算关系随电解质类型不同：AB 型 Ksp = S²，A₂B 型 Ksp = 4S³。只有同类型电解质才能用 Ksp 直接比较溶解度大小。"},{"q":"配位溶解为什么能使沉淀溶解？","a":"配位剂与沉淀中的金属离子生成稳定配离子，使金属离子浓度大幅降低，Q < Ksp，沉淀随之溶解。例如 AgCl 可溶于氨水生成 [Ag(NH₃)₂]⁺。"}]}],"qa":[{"q":"如何用离子积 Q 与 Ksp 的关系判断沉淀的生成与溶解？","a":"Q > Ksp 时生成沉淀，Q = Ksp 时达到饱和平衡，Q < Ksp 时沉淀溶解。改变溶液中某一离子的浓度，就会改变 Q，从而使平衡向生成或溶解的方向移动。"},{"q":"同离子效应如何影响难溶电解质的溶解度？","a":"加入含有相同离子的强电解质，会使溶解平衡向生成沉淀方向移动，溶解度降低。例如在 AgCl 饱和溶液中加入 NaCl，AgCl 的溶解度明显下降。"},{"q":"沉淀转化的方向由什么决定？","a":"由两种难溶物溶度积的相对大小决定：一般 Ksp 大的难溶物转化为 Ksp 小的难溶物，如 AgCl（白）→ AgI（黄）→ Ag₂S（黑）。转化能否发生还取决于两种沉淀剂浓度的相对大小。"},{"q":"为什么测定 Ksp 时必须恒温并取上层清液？","a":"难溶电解质的溶解度随温度变化，必须恒温静置使体系达到平衡；取上层清液可避免吸入底部固体。若吸入固体，测得的溶液浓度偏高，Ksp 计算结果偏大。"},{"q":"为什么不同电解质类型的 Ksp 不能直接比较？","a":"Ksp 与溶解度 S 的换算关系随电解质类型不同：AB 型 Ksp = S²，A₂B 型 Ksp = 4S³。只有同类型电解质才能用 Ksp 直接比较溶解度大小。"},{"q":"配位溶解为什么能使沉淀溶解？","a":"配位剂与沉淀中的金属离子生成稳定配离子，使金属离子浓度大幅降低，Q < Ksp，沉淀随之溶解。例如 AgCl 可溶于氨水生成 [Ag(NH₃)₂]⁺。"}],"order":4,"hidden":false,"visibleAt":""},"inorganic/e05":{"id":"e05","no":5,"name":"电导率与解离平衡","full":"电导率法测定解离常数 · 解离平衡及水解反应","cards":[{"id":"safety","title":"安全教育","hint":"进实验室前先读完","blocks":[{"t":"h","text":"本实验安全要点","level":3},{"t":"kv","k":"要点1","v":"电导电极（铂黑/石墨）易碎且怕污染，取放轻稳，测量前冲洗并排除气泡。"},{"t":"kv","k":"要点2","v":"配制低浓度溶液用水须高纯，容器洁净，避免手触电极片。"},{"t":"kv","k":"要点3","v":"强酸强碱稀释按“酸入水”操作，戴护目镜与手套。"},{"t":"kv","k":"要点4","v":"废液按酸、碱、重金属分类收集，不倒水槽。"},{"t":"h","text":"实验安全","level":2},{"t":"p","text":"进入实验室前请先阅读以下三项安全要点，测量过程中需严格遵守。"},{"t":"p","text":"**1. 个人防护**\n有条件的情况下全程佩戴护目镜，禁止裸手揉搓眼睛。\n醋酸有腐蚀性，接触溶液时佩戴乳胶手套。\n实验室内严禁饮食；长发束起，穿合身实验服。"},{"t":"p","text":"**2. 试剂安全与废液处理**\n醋酸沾到皮肤：立即用大量流动清水冲洗。\n溅入眼睛：持续流水冲洗，并及时报告教师就医。\n废液严禁直接倒入下水道，统一收集到废液回收容器。\n溶液洒落及时擦净，防止地面湿滑跌倒。"},{"t":"p","text":"**3. 仪器用电与电极保护**\n仪器为 220V 交流供电，手须干燥，禁止湿手插拔插头。\n电极精密易碎，轻拿轻放，避免碰撞跌落。\n铂黑电极禁止纸巾用力擦拭镀层，只用去离子水冲洗。\n吸水纸轻轻吸干电极表面，不摩擦铂片。\n仪器漏电或故障：立即断电拔插头，报告教师处理。"},{"t":"h","text":"实验重点难点与安全隐患","level":2},{"t":"p","text":"重点难点：①弱电解质的电离平衡——适当选取指示剂，掌握不同指示剂的变色范围以及观察指示剂的颜色变化，并解释原因。\n不同指示剂的变色范围如下。"},{"t":"fig","src":"assets/exps/e05/i04.jpeg","caption":"图 1　酚酞与甲基橙的变色范围","alt":"","w":951,"h":407},{"t":"p","text":"②盐类水解——掌握“谁弱谁水解、谁强显谁性、都强不水解”的规律及温度、浓度、双水解对水解程度的影响，正确判断双水解的产物、把握加热与酚酞显色的程度，避免把溶液暴沸误认为水解被促进。"},{"t":"p","text":"安全隐患：1.氢氧化钠溶解强烈放热、浓氨水与浓盐酸强腐蚀且易挥发刺激，取用、稀释必须在通风橱进行并做好防溅灼伤，溅到皮肤立即大量清水冲洗。"},{"t":"fig","src":"assets/exps/e05/i05.jpg","caption":"图 2　通风橱内取用挥发性试剂","alt":"","w":536,"h":512},{"t":"p","text":"2.加热碳酸钠溶液及水浴升温时注意防烫伤，徒手不触碰加热区。"}],"count":14},{"id":"purpose","title":"实验目的","hint":"为什么做、依据是什么","blocks":[{"t":"h","text":"==1/2 电导率法测定 HAc 解离常数==","level":3},{"t":"h","text":"实验目的","level":2},{"t":"p","text":"**1. **巩固弱电解质解离度 α、解离常数 K_{a} 与溶液浓度 c 之间的关系。\n**2. **学习 DDS-11A 型电导率仪的校正、测量与结束整理。\n**3. **练习由电导率计算摩尔电导率、解离度与 K_{a}，并分析误差来源。"},{"t":"h","text":"实验原理","level":2},{"t":"p","text":"醋酸的解离常数、解离度与浓度的关系为："},{"t":"p","text":"Ka = c · α² / (1 − α)","html":"K<sub>a</sub> = c · α² / (1 − α)"},{"t":"p","text":"为比较不同电解质溶液的导电能力，需要引入摩尔电导率："},{"t":"p","text":"Λm = (γ / c) × 10⁻³"},{"t":"p","text":"弱电解质解离度为极限摩尔电导率与摩尔电导率之比："},{"t":"p","text":"α = Λ_{m} / Λ_{m∞}"},{"t":"p","text":"代入解离平衡式，得到解离常数计算式："},{"t":"p","text":"K_{a} = c · Λ_{m}² / [Λ_{m∞}(Λ_{m∞} − Λ_{m})]"},{"t":"p","text":"25 ℃ 时 HAc 极限摩尔电导率 Λ_{m∞} = 0.03907 S·m²·mol⁻¹。"},{"t":"p","text":"原理链条：测电导率 → 摩尔电导率 → 解离度 → 解离常数 Ka。","html":"原理链条：测电导率 → 摩尔电导率 → 解离度 → 解离常数 K<sub>a</sub>。"},{"t":"fig","src":"assets/exps/e05/i01.jpeg","caption":"图 3　电导率仪工作原理框图","w":846,"h":278},{"t":"h","text":"仪器与药品","level":2},{"t":"p","text":"**仪器**"},{"t":"p","text":"DDS-11A 型电导率仪、6 孔井穴板、烧杯、洗瓶、吸水纸。"},{"t":"p","text":"**药品**"},{"t":"p","text":"五种不同浓度的醋酸（HAc）溶液、去离子水（蒸馏水，用于冲洗电极）"},{"t":"h","text":"数据记录与处理","level":2},{"t":"table","rows":[["编号","c /(mol·L⁻¹)","γ /(S·m⁻¹)","Λm /(S·m²·mol⁻¹)","α","Ka"],["1","","","","",""],["2","","","","",""],["3","","","","",""],["4","","","","",""],["5","","","","",""]],"header":true},{"t":"p","text":"处理要求："},{"t":"p","text":"1. 按公式分别计算每组 Λ_{m}、α、K_{a}。\n2. 求五次 K_{a} 的平均值，再与化学手册标准值对比。\n3. 分析实测值与手册值不同的原因（温度、电极校正、读数、污染等）。"},{"t":"h","text":"==2/2 电离平衡==","level":3},{"t":"h","text":"实验目的","level":2},{"t":"p","text":"1．加强对解离平衡、同离子效应理论的理解；\n2．掌握缓冲溶液的原理及其配制方法；\n3．掌握盐类水解反应，并会用平衡移动的原理解释实验现象；\n4．复习指示剂及 pH 试纸的使用方法。"},{"t":"h","text":"实验原理","level":3},{"t":"p","text":"（一）弱电解质的解离平衡：弱酸或弱碱在水中部分解离，存在解离平衡 AB ⇌ A⁺ + B⁻。温度、弱电解质浓度 c(AB) 及溶液中 A⁺、B⁻ 浓度都会影响平衡移动。解离反应吸热，升温使平衡向解离方向移动；增大 A⁺、B⁻ 浓度则使平衡向生成 AB 的方向移动，这种影响称为同离子效应——利用同离子效应可以降低弱电解质的解离度，也能降低难溶电解质的溶解度。"},{"t":"p","text":"（二）缓冲溶液：弱酸及其盐（或弱碱及其盐）可组成缓冲溶液，能抵御少量外来酸碱而保持 pH 基本不变。pH = pKₐ + lg(c_{盐}/c_{酸})，pOH = pK_{b} + lg(c_{盐}/c_{碱})；当 c_{盐}/c_{酸} 或 c_{盐}/c_{碱} 的比例在 0.1~10 之间时缓冲作用较大，即 pH = pKₐ ± 1；缓冲能力有限，大量外来酸碱会破坏其缓冲能力。"},{"t":"p","text":"（三）盐类水解：盐电离出的弱酸根或弱碱阳离子与水电离出的 H⁺ 或 OH⁻ 结合生成弱电解质，破坏水的电离平衡，使溶液显酸性或碱性。强碱弱酸盐显碱性、强酸弱碱盐显酸性、弱酸弱碱盐的酸碱性由 Kₐ 与 K_{b} 的相对大小决定（如 NH₄Ac 近中性，而 (NH₄)₂S 显碱性）。水解吸热，升温促进水解；加酸或加碱可抑制水解，如 BiCl₃ + H₂O ⇌ BiOCl↓（白）+ 2HCl，为防止水解需先将 BiCl₃ 溶于浓盐酸再稀释。两种相互促进水解的盐混合可发生双水解，如 2Al³⁺ + 3CO₃²⁻ + 6H₂O ⇌ 2Al(OH)₃↓ + 3CO₂↑ + 3H₂O。"},{"t":"h","text":"仪器和药品","level":2},{"t":"p","text":"**仪器**\n试管、试管夹、10 mL 量筒、烧杯、酒精灯、点滴板、药匙、玻璃棒。"},{"t":"p","text":"**药品**\n氨水（0.1、2 mol·L⁻¹）；NaOH（0.1、6 mol·L⁻¹）；HCl（0.1、2、6 mol·L⁻¹）；HAc（0.1、2 mol·L⁻¹）；NaAc（0.1、2 mol·L⁻¹）；Al₂(SO₄)₃（0.1 mol·L⁻¹）；NaHCO₃（0.5 mol·L⁻¹）；NH₄Ac（s）；酚酞；甲基橙。"}],"count":25},{"id":"procedure","title":"实验流程","hint":"按顺序做什么","blocks":[{"t":"h","text":"==1/2 电导率法测定 HAc 解离常数==","level":3},{"t":"h","text":"实验步骤","level":2},{"t":"p","text":"**1. 准备与校正**"},{"t":"p","text":"接通电源，仪器预热 5 min。\n按待测液电导率范围选择对应电极，插入插口并旋紧。\n调节温度补偿旋钮，指示值与溶液温度相同。\n开关置“校正”挡，调节常数校正钮，显示电极实际常数。"},{"t":"fig","src":"assets/exps/e05/i02.jpeg","caption":"图 4　DDS-11A 数字型电导率仪正面面板","w":1204,"h":727},{"t":"p","text":"电极选型：电导率低于 10 用光亮电极；10～10⁴ 用铂黑电极；大于 10⁴ 用 DJS-10 铂黑电极，读数乘以 10。"},{"t":"p","text":"**2. 样品测量**"},{"t":"p","text":"井穴板 1～5 号孔各加入约 4 mL 不同浓度 HAc 溶液。\n电极用去离子水洗净，吸水纸轻吸干后插入待测液。\n开关置“测量”挡，选合适量程，轻轻搅动使溶液混匀。\n待数字稳定后读取并记录电导率；首位显示“1”为溢出，换高一挡量程。\n测下一个样品前，电极必须再次冲洗、吸干，避免交叉污染。"},{"t":"p","text":"**3. 结束整理**"},{"t":"p","text":"量程还原到最高挡，开关拨回“校正”，关闭仪器电源。\n取出电极，去离子水冲洗吸干，放回电极盒妥善存放。\n全部废液倒入废液回收桶，不得直接排入下水道。\n清洗井穴板、烧杯等器具，擦净台面并整理归位。"},{"t":"fig","src":"assets/exps/e05/i03.jpg","caption":"图 5　用电导电极在井穴板中测量溶液电导率（示意图，AI 生成）","alt":"","w":1152,"h":864},{"t":"h","text":"补充材料：实验工具","level":3},{"t":"fig","src":"assets/exps/e05/x04.png","caption":"图 6　HAc 解离常数计算器二维码（第三方在线工具）","alt":"","w":370,"h":370},{"t":"kv","k":"工具","v":"解离常数计算器：由电导率数据计算弱电解质的解离常数 Ka。"},{"t":"h","text":"实验图示","level":3},{"t":"fig","src":"assets/exps/e05/x02.jpeg","caption":"图 7　醋酸（HAc）试剂","alt":"","w":448,"h":299},{"t":"fig","src":"assets/exps/e05/x03.jpg","caption":"图 8　台式电导率仪与测量电极","alt":"","w":642,"h":635},{"t":"h","text":"==2/2 解离平衡及水解反应==","level":2},{"t":"p","text":"**1．弱电解质的解离平衡**"},{"t":"p","text":"① 在试管中加入 10 滴 0.1 mol·L⁻¹ 氨水，滴入 1 滴酚酞，观察颜色；再加入少量 NH₄Ac 固体，振荡试管，观察颜色变化并解释原因。\n② 在试管中加入 10 滴 0.1 mol·L⁻¹ HAc 溶液，滴入 1 滴甲基橙，观察颜色；再加入少量 NH₄Ac 固体，振荡，观察颜色变化并解释原因。"},{"t":"p","text":"**2．缓冲溶液**"},{"t":"p","text":"① 按表 3.5 在两只烧杯中配制两组缓冲溶液，搅拌均匀后用 pH 试纸测定 pH，并与计算值比较。"},{"t":"table","rows":[["实验编号","酸（10 mL）","盐（10 mL）","计算 pH","实测 pH"],["1","2 mol·L⁻¹ HAc 溶液","2 mol·L⁻¹ NaAc 溶液","",""],["2","0.1 mol·L⁻¹ HAc 溶液","0.1 mol·L⁻¹ NaAc 溶液","",""]]},{"t":"p","text":"② 把上述两组液体各分为五份，分别取组一、组二及等量蒸馏水，依次加入 0.5 mL 去离子水、0.1 mol·L⁻¹ HAc、0.1 mol·L⁻¹ NaOH，测定 pH 并填入表 3.6，体会“缓冲能力是有限的”。"},{"t":"table","rows":[["实验内容","组一","组二","蒸馏水"],["加入 0.5 mL 去离子水","","",""],["加入 0.5 mL 0.1 mol·L⁻¹ HAc 溶液","","",""],["加入 0.5 mL 0.1 mol·L⁻¹ NaOH 溶液","","",""]]},{"t":"p","text":"③ 自行设计实验，配制 pH = 10 的缓冲溶液，并证明其 pH 与缓冲能力。"},{"t":"p","text":"**3．盐类水解**"},{"t":"p","text":"① 在试管中加入 3 mL 2 mol·L⁻¹ NaAc 溶液，滴入 1 滴酚酞，观察颜色；缓慢加热至沸腾，观察颜色变化，冷却试管后再观察并解释现象。\n② 取两支试管，分别加入 1 mL 0.1 mol·L⁻¹ Al₂(SO₄)₃ 溶液和 1 mL 0.5 mol·L⁻¹ NaHCO₃ 溶液，用 pH 试纸测定 pH，再把两种溶液混合，观察并解释现象。"}],"count":23},{"id":"thinking","title":"实验思考","hint":"做完再想一遍","blocks":[{"t":"h","text":"==电导率 · 思考题==","level":3},{"t":"h","text":"电导率法测定弱电解质解离常数的基本原理是什么？","level":3},{"t":"p","text":"弱电解质溶液的电导率由已解离离子的浓度与迁移速率决定。测得一定浓度溶液的摩尔电导率，结合无限稀释摩尔电导率，可求出解离度 α，再代入稀释定律即可得到解离常数 Ka。","html":"弱电解质溶液的电导率由已解离离子的浓度与迁移速率决定。测得一定浓度溶液的摩尔电导率，结合无限稀释摩尔电导率，可求出解离度 α，再代入稀释定律即可得到解离常数 K<sub>a</sub>。"},{"t":"h","text":"为什么实验中要扣除水的电导率？","level":3},{"t":"p","text":"高纯水本身也有微弱电导（溶解的 CO₂ 与微量离子），在低浓度区其贡献不可忽略。测定溶液电导率时应扣除同温度下纯水的电导率，否则浓度越低误差越大。"},{"t":"h","text":"温度对电导率与解离常数有什么影响？","level":3},{"t":"p","text":"温度升高，离子迁移速率增大，电导率上升；同时弱电解质的解离是吸热过程，Ka 随温度升高而增大。因此测定过程中必须恒温，并记录实验温度。","html":"温度升高，离子迁移速率增大，电导率上升；同时弱电解质的解离是吸热过程，K<sub>a</sub> 随温度升高而增大。因此测定过程中必须恒温，并记录实验温度。"},{"t":"h","text":"强电解质与弱电解质的电导行为有何差异？","level":3},{"t":"p","text":"强电解质完全解离，浓度降低时摩尔电导率仅因离子间相互作用减弱而缓慢上升；弱电解质解离度随浓度降低而显著增大，摩尔电导率上升更明显。这一差异可用于判断电解质强弱。"},{"t":"h","text":"为什么测 Ka 时要保证电极洁净并避免气泡？","level":3},{"t":"p","text":"电极表面污染或附着气泡会改变有效电极面积与电流路径，使电导率读数偏低甚至跳动。测量前应冲洗电极、轻摇排除气泡，并避免手触电极片。"},{"t":"h","text":"实验中为什么要配制多个不同浓度的溶液？","level":3},{"t":"p","text":"由多个浓度点得到的 Ka 可相互校验，并检验公式适用性；单一浓度点的偶然误差无法判断。作 Ka 与浓度关系可发现系统误差。","html":"由多个浓度点得到的 K<sub>a</sub> 可相互校验，并检验公式适用性；单一浓度点的偶然误差无法判断。作 K<sub>a</sub> 与浓度关系可发现系统误差。"},{"t":"h","text":"==解离平衡及水解反应 · 思考题==","level":2},{"t":"h","text":"什么叫同离子效应？哪些情况会产生同离子效应？在 CaCO₃ 饱和溶液中加入 Na₂CO₃ 是否会产生同离子效应，有何现象？","level":3},{"t":"p","text":"在弱电解质溶液中加入含有相同离子的强电解质，使其解离平衡向生成弱电解质的方向移动、解离度降低的现象叫同离子效应。弱酸/弱碱与其盐、难溶电解质与其沉淀剂都会产生同离子效应。向 CaCO₃ 饱和溶液加入 Na₂CO₃ 时，CO₃²⁻ 浓度增大使 CaCO₃ 溶解平衡左移，溶解度降低，会有 CaCO₃ 沉淀析出。"},{"t":"h","text":"何谓缓冲溶液？NaH₂PO₄ 与 Na₂HPO₄ 的混合溶液是缓冲溶液吗？","level":3},{"t":"p","text":"由弱酸及其盐（或弱碱及其盐）组成的、能抵抗少量外加强酸强碱而保持 pH 基本不变的溶液叫缓冲溶液。NaH₂PO₄ 与 Na₂HPO₄ 构成 H₂PO₄⁻/HPO₄²⁻ 共轭酸碱对，是典型的缓冲溶液（pH ≈ pKₐ₂ ≈ 7.2）。"},{"t":"h","text":"盐类水解是怎样产生的？怎样防止盐类水解？","level":3},{"t":"p","text":"盐溶于水后电离出的弱酸根或弱碱阳离子与水电离出的 H⁺ 或 OH⁻ 结合生成弱电解质，使水的电离平衡右移，溶液显酸性或碱性，这就是盐类水解。防止方法：加相应的酸或碱抑制（如配制 BiCl₃ 溶液时加盐酸）、降低温度、减少稀释；需要完全水解时则相反，可加热或稀释促进。"},{"t":"h","text":"欲配制 BiCl₃ 溶液，能否将 BiCl₃ 固体直接溶于水？","level":3},{"t":"p","text":"不能。BiCl₃ 遇水迅速水解：BiCl₃ + H₂O ⇌ BiOCl↓（白色）+ 2HCl，溶液浑浊。应先把 BiCl₃ 固体溶于少量浓盐酸中，再用水稀释到所需浓度；若已出现 BiOCl 沉淀，可补加浓盐酸使沉淀重新溶解。"}],"count":10,"qa":[{"q":"电导率法测定弱电解质解离常数的基本原理是什么？","a":"弱电解质溶液的电导率由已解离离子的浓度与迁移速率决定。测得一定浓度溶液的摩尔电导率，结合无限稀释摩尔电导率，可求出解离度 α，再代入稀释定律即可得到解离常数 Ka。"},{"q":"为什么实验中要扣除水的电导率？","a":"高纯水本身也有微弱电导（溶解的 CO₂ 与微量离子），在低浓度区其贡献不可忽略。测定溶液电导率时应扣除同温度下纯水的电导率，否则浓度越低误差越大。"},{"q":"温度对电导率与解离常数有什么影响？","a":"温度升高，离子迁移速率增大，电导率上升；同时弱电解质的解离是吸热过程，Ka 随温度升高而增大。因此测定过程中必须恒温，并记录实验温度。"},{"q":"强电解质与弱电解质的电导行为有何差异？","a":"强电解质完全解离，浓度降低时摩尔电导率仅因离子间相互作用减弱而缓慢上升；弱电解质解离度随浓度降低而显著增大，摩尔电导率上升更明显。这一差异可用于判断电解质强弱。"},{"q":"为什么测 Ka 时要保证电极洁净并避免气泡？","a":"电极表面污染或附着气泡会改变有效电极面积与电流路径，使电导率读数偏低甚至跳动。测量前应冲洗电极、轻摇排除气泡，并避免手触电极片。"},{"q":"实验中为什么要配制多个不同浓度的溶液？","a":"由多个浓度点得到的 Ka 可相互校验，并检验公式适用性；单一浓度点的偶然误差无法判断。作 Ka 与浓度关系可发现系统误差。"}]}],"qa":[{"q":"电导率法测定弱电解质解离常数的基本原理是什么？","a":"弱电解质溶液的电导率由已解离离子的浓度与迁移速率决定。测得一定浓度溶液的摩尔电导率，结合无限稀释摩尔电导率，可求出解离度 α，再代入稀释定律即可得到解离常数 Ka。"},{"q":"为什么实验中要扣除水的电导率？","a":"高纯水本身也有微弱电导（溶解的 CO₂ 与微量离子），在低浓度区其贡献不可忽略。测定溶液电导率时应扣除同温度下纯水的电导率，否则浓度越低误差越大。"},{"q":"温度对电导率与解离常数有什么影响？","a":"温度升高，离子迁移速率增大，电导率上升；同时弱电解质的解离是吸热过程，Ka 随温度升高而增大。因此测定过程中必须恒温，并记录实验温度。"},{"q":"强电解质与弱电解质的电导行为有何差异？","a":"强电解质完全解离，浓度降低时摩尔电导率仅因离子间相互作用减弱而缓慢上升；弱电解质解离度随浓度降低而显著增大，摩尔电导率上升更明显。这一差异可用于判断电解质强弱。"},{"q":"为什么测 Ka 时要保证电极洁净并避免气泡？","a":"电极表面污染或附着气泡会改变有效电极面积与电流路径，使电导率读数偏低甚至跳动。测量前应冲洗电极、轻摇排除气泡，并避免手触电极片。"},{"q":"实验中为什么要配制多个不同浓度的溶液？","a":"由多个浓度点得到的 Ka 可相互校验，并检验公式适用性；单一浓度点的偶然误差无法判断。作 Ka 与浓度关系可发现系统误差。"}],"order":5,"hidden":false,"visibleAt":""},"inorganic/e06":{"id":"e06","no":6,"name":"氧化还原与原电池","full":"氧化还原与原电池","cards":[{"id":"safety","title":"安全教育","hint":"进实验室前先读完","blocks":[{"t":"h","text":"本实验安全要点","level":3},{"t":"kv","k":"要点1","v":"KMnO₄、KClO₃ 等强氧化剂不得研磨、烘烤，远离有机物与还原剂。"},{"t":"kv","k":"要点2","v":"浓盐酸、KMnO₄ 等强氧化剂与还原性物质（KI、SnCl₂、FeSO₄）分开存放，不得混放。"},{"t":"kv","k":"要点3","v":"涉及 Cl₂ 等有毒气体的操作在通风橱内进行，出口接尾气吸收。"},{"t":"kv","k":"要点4","v":"还原性溶液（FeSO₄、KI、SnCl₂ 等）应现配现用或隔绝空气保存，避免被空气氧化。"},{"t":"h","text":"试剂的使用与保存","level":3},{"t":"p","text":"· 强氧化剂远离可燃物、还原性物质与有机物，不得混放；\n· 各类试剂按标签正确取用；用后及时盖好，分类存放；\n· 见光易分解的试剂装棕色瓶、避光保存。"},{"t":"h","text":"有毒气体与通风","level":3},{"t":"p","text":"· 涉及 Cl₂ 等有毒气体的操作在通风橱内进行；\n· 装置出口接尾气吸收处理，不得直接排入室内；\n· 闻气体气味时用手轻扇，不可直接对瓶口吸气。"},{"t":"h","text":"操作规范","level":3},{"t":"p","text":"· 加热试管时管口不对人，先预热后集中加热，防止暴沸溅出；\n· 还原性溶液现配现用，或通保护气隔绝空气；\n· 酸化用稀硫酸，不用盐酸（避免 Cl⁻ 被氧化引入干扰）；\n· 不要用嘴吹酒精灯，用灯帽盖灭。"},{"t":"h","text":"危险品与应急处置","level":3},{"t":"p","text":"· KMnO₄、KClO₃、K₂Cr₂O₇ 受热或与有机物混合易反应，不得研磨、烘烤；\n· 强氧化剂与还原性物质、可燃物分开存放，不得混放；\n· 酒精洒出着火用湿抹布盖灭，切勿用水冲。"}],"count":8},{"id":"purpose","title":"实验目的","hint":"为什么做、依据是什么","blocks":[{"t":"h","text":"实验目的","level":3},{"t":"p","text":"**1.** 了解电极电势 E 与氧化还原反应方向的关系：E(氧化剂电对) > E(还原剂电对) 时，反应自发正向进行，差值越大反应进行越完全。\n**2.** 了解浓度、介质酸（碱）度对氧化还原反应的影响。\n**3.** 了解难溶物、配合物的生成对氧化还原反应的影响。\n**4. **了解原电池的构成与电动势的测定方法。\n**5.** 练习 KI-淀粉试纸的使用。"},{"t":"h","text":"核心判据","level":3},{"t":"p","text":"一切判断都回到这一条：氧化剂的电极电势高于还原剂，反应才自发。E 是强度性质，与物质数量无关。"},{"t":"h","text":"实验原理","level":3},{"t":"p","text":"**电极电势与反应方向**\n· 氧化还原反应进行的方向与程度，与氧化还原电对的电极电势 E 有关；\n· E(氧化剂电对) > E(还原剂电对) → 反应自发正向进行；反之则逆向进行；\n· 二者差值越大，反应进行的程度越大。"},{"t":"p","text":"**原电池与电解池**\n· 原电池：化学能转变为电能的装置；\n· 电解池：电能转变为化学能的装置；\n· 电动势是衡量原电池做功能力的重要物理量。"}],"count":4},{"id":"procedure","title":"实验流程","hint":"按顺序做什么","blocks":[{"t":"kv","k":"核心判据","v":"E(氧化剂电对) > E(还原剂电对) → 反应自发正向进行；差值越大，反应进行的程度越大"},{"t":"h","text":"影响电极电势的因素","level":3},{"t":"p","text":"**1 介质酸度**\n· 对含氧化物、含氧酸及其盐参与的氧化还原反应影响显著；\n· 含氧化合物的氧化性随介质酸度增大而增强；\n· 影响反应的方向、速率和产物。\n**2 沉淀生成**\n· 电对中某离子与沉淀剂形成沉淀；\n· 该离子浓度大为降低，电对电极电势显著改变；\n· 从而增强或削弱该离子的氧化性／还原性。\n**3 配合物生成**\n· 电对中某离子与配位剂形成配合物；\n· 离子有效浓度大幅降低，电极电势发生显著变化；\n· 类似沉淀效应，改变氧化还原能力。"},{"t":"h","text":"仪器与药品","level":3},{"t":"kv","k":"仪器","v":"石墨电极（铅笔芯）×2；铜电极、锌电极、铁电极（长 2 cm、宽 0.5 cm）；电位差计、U 形管（盐桥）；试管、烧杯（100 mL）"},{"t":"kv","k":"药品","v":"酸类：H₂SO₄（1／0.1／2 mol·L⁻¹）、HCl（1／0.1 mol·L⁻¹／浓）、HAc（6 mol·L⁻¹）；碱类：NH₃·H₂O（浓）、NaOH（6 mol·L⁻¹）；盐溶液：FeCl₃、FeSO₄、CuSO₄、ZnSO₄、SnCl₂、KI、KBr、K₂Cr₂O₇、KMnO₄（均 0.1 mol·L⁻¹）；其他：碘水、淀粉溶液、CCl₄、AgNO₃、(NH₄)₂Fe(SO₄)₂、Na₂SO₃、饱和 KCl、饱和食盐水、酚酞、MnO₂(s)、NaF(s)、KI-淀粉试纸"},{"t":"h","text":"电极电势与氧化还原反应方向","level":3},{"t":"p","text":"通过三步反应验证电极电势大小顺序：MnO₄⁻/Mn²⁺ > Fe³⁺/Fe²⁺ > I₂/I⁻ > Sn⁴⁺/Sn²⁺"},{"t":"p","text":"**1 Fe³⁺ 氧化 I⁻**\n\n**操作**\tKI 溶液 + 淀粉 + FeCl₃ 溶液\n**现象**\t溶液变蓝（生成 I₂ 使淀粉显色）\n**结论**\tE(Fe³⁺/Fe²⁺) > E(I₂/I⁻)，反应 2Fe³⁺ + 2I⁻ → 2Fe²⁺ + I₂ 正向进行　2 Sn²⁺ 还原 I₂\n\n**操作**\t向蓝色溶液中逐滴加入 SnCl₂ 溶液\n**现象**\t蓝色消失\n**结论**\tE(I₂/I⁻) > E(Sn⁴⁺/Sn²⁺)，反应 I₂ + Sn²⁺ → 2I⁻ + Sn⁴⁺ 正向进行　3 Fe²⁺ 还原 MnO₄⁻\n\n**操作**\tKMnO₄ + H₂SO₄ + 滴加 FeSO₄ 溶液\n**现象**\t溶液紫色消失\n**结论**\tE(MnO₄⁻/Mn²⁺) > E(Fe³⁺/Fe²⁺)，酸性条件下 MnO₄⁻ 氧化 Fe²⁺"},{"t":"p","text":"结论排序：MnO₄⁻/Mn²⁺ > Fe³⁺/Fe²⁺ > I₂/I⁻ > Sn⁴⁺/Sn²⁺"},{"t":"h","text":"酸度对氧化还原反应的影响","level":3},{"t":"p","text":"① 对比实验：MnO₂ + HCl\n\n**步骤 1**\t两支试管各加少量 MnO₂ 固体\n**步骤 2**\t分别加入 1 mol·L⁻¹ HCl 与浓 HCl\n**步骤 3**\t用 KI-淀粉试纸覆盖管口检测 Cl₂\n\n**现象**\t浓 HCl 管口试纸变蓝（产生 Cl₂），稀 HCl 管口不变色\n**结论**\t浓盐酸酸度更高，MnO₂ 可氧化 Cl⁻ 生成 Cl₂；稀盐酸则不能　② 对比实验：K₂Cr₂O₇ + HCl\n\n**步骤 1**\t两支试管各加 K₂Cr₂O₇ 溶液\n**步骤 2**\t分别加入 1 mol·L⁻¹ HCl 与浓 HCl\n**步骤 3**\t用 KI-淀粉试纸检查是否产生 Cl₂\n\n**现象**\t浓 HCl 条件下试纸变色，验证强酸性增强了 Cr₂O₇²⁻ 的氧化性\n**结论**\t强酸性条件下 Cr₂O₇²⁻ 可氧化 Cl⁻ 产生 Cl₂，酸度降低则反应减弱"},{"t":"h","text":"浓度对氧化还原反应的影响","level":3},{"t":"p","text":"**Fe³⁺ 浓度对反应的影响**","level":3},{"t":"p","text":"· FeCl₃ + KI → I₂（加 CCl₄ 萃取后观察紫色深浅）\n· 对照组加入 FeSO₄ 稀释 Fe³⁺ → CCl₄ 层紫色变浅\n结论\tFe³⁺ 浓度降低，E(Fe³⁺/Fe²⁺) 降低，氧化能力减弱"},{"t":"p","text":"**沉淀对反应的影响**","level":3},{"t":"p","text":"· 碘水 + (NH₄)₂Fe(SO₄)₂ → 无明显颜色变化"},{"t":"p","text":"· 加 AgNO₃ 生成 AgI↓ 沉淀 → 溶液变黄（Fe³⁺ 的颜色）"},{"t":"p","text":"结论\tI⁻ 被沉淀除去，使反应 2Fe³⁺ + 2I⁻ → I₂ + 2Fe²⁺ 逆转"},{"t":"p","text":"**配合物对反应的影响**","level":3},{"t":"p","text":"· FeCl₃ + KI → 蓝色出现（I₂-淀粉显色）\n· 加 NaF 固体 → 蓝色消失\n结论\tF⁻ 与 Fe³⁺ 形成 [FeF₆]³⁻ 配合物，E 降低，Fe³⁺ 无法氧化 I⁻"},{"t":"h","text":"原电池的构成与电动势","level":3},{"t":"p","text":"Cu-Zn 双半电池：U 形管盐桥连接，电位差计测电动势　CuSO₄ 加浓氨水前后：浅蓝 → 深蓝铜氨络离子"},{"t":"p","text":"**① 三种原电池的构建**\n· Cu-Zn：Cu | CuSO₄ ‖ ZnSO₄ | Zn\n· Cu-Fe：Fe | FeSO₄ ‖ CuSO₄ | Cu\n· Fe-Zn：Zn | ZnSO₄ ‖ FeSO₄ | Fe\nU 形管盐桥连接两个半电池，电位差计测电动势\n**② 浓度对电动势的影响**\n· CuSO₄ 端加浓氨水 → Cu(NH₃)₄²⁺ 生成，E(Cu²⁺/Cu)↓ → 电动势减小\n· ZnSO₄ 端加浓氨水 → Zn(NH₃)₄²⁺ 生成，E(Zn²⁺/Zn)↓ → 电动势增大\n**③ 酸度对电动势的影响**\n· K₂Cr₂O₇ ‖ FeSO₄ 原电池（石墨电极）\n· 加 H₂SO₄ → Cr₂O₇²⁻ 氧化性增强 → 电动势增大\n· 加 NaOH → 酸度降低 → 电动势减小"},{"t":"h","text":"电解饱和 CuCl₂ 溶液","level":3},{"t":"p","text":"**① 实验装置与操作**\n步骤 1\tU 形管中加入饱和 CuCl₂ 溶液\n步骤 2\t两端分别插入石墨电极，连接外接电源\n步骤 3\t用 KI-淀粉试纸检验阳极产物\n**② 电极反应与现象**\n电解时阳极产生 Cl₂、阴极析出 Cu，溶液蓝色逐渐变浅。"},{"t":"kv","k":"总反应（电能驱动）","v":"CuCl₂ → Cu + Cl₂↑"},{"t":"h","text":"实验图示","level":3},{"t":"fig","src":"assets/exps/e06/x01.jpg","caption":"图 1　Cu-Zn 原电池：U 形管盐桥连接两个半电池，电位差计测电动势（示意图，AI 生成）","alt":"","w":1152,"h":864},{"t":"fig","src":"assets/exps/e06/x03.jpg","caption":"图 2　电解饱和 CuCl₂ 溶液：U 形管 + 石墨电极","alt":"","w":1152,"h":864},{"t":"fig","src":"assets/exps/e06/x04.jpg","caption":"图 3　Fe³⁺ 氧化 I⁻：I₂ 使淀粉溶液变蓝（示意图，AI 生成）","alt":"","w":1152,"h":864},{"t":"fig","src":"assets/exps/e06/x10.jpg","caption":"图 4　原电池电动势的测定：两个半电池 + 电极 + 电位差计","alt":"","w":1152,"h":864}],"count":24},{"id":"thinking","title":"实验思考","hint":"做完再想一遍","blocks":[{"t":"h","text":"如何用电极电势判断氧化还原反应的方向？","level":3},{"t":"p","text":"比较氧化剂电对与还原剂电对的电极电势：E(氧化剂电对) > E(还原剂电对) 时反应自发正向进行，差值越大反应进行程度越大。这是判断氧化还原方向的核心判据。"},{"t":"h","text":"介质酸度为什么会影响氧化性？","level":3},{"t":"p","text":"含氧酸及其盐参与的半反应中有 H⁺ 或 OH⁻ 参加，改变酸度会改变电极电势。一般含氧化合物在酸性介质中氧化性更强，碱性介质中减弱，甚至改变反应产物。"},{"t":"h","text":"沉淀或配合物的生成如何改变电极电势？","level":3},{"t":"p","text":"若电对中的某种离子与沉淀剂或配位剂结合，其有效浓度大幅降低，电极电势随之改变，可能增强或削弱该物质的氧化还原能力。例如 Ag⁺ 生成 AgCl 后，Ag⁺/Ag 的电极电势明显下降。"},{"t":"h","text":"原电池与电解池有什么区别？盐桥起什么作用？","level":3},{"t":"p","text":"原电池把化学能转变为电能，电解池把电能转变为化学能。盐桥用于沟通两个半电池、保持电中性并减小液接电势，使电池能持续放电。"},{"t":"h","text":"为什么说电极电势是强度性质？","level":3},{"t":"p","text":"电极电势与电对的本性和浓度（活度）有关，而与物质的数量无关。因此同一电对无论取多少，其电极电势不变；这与电极反应中转移的电子数无关。"},{"t":"h","text":"本实验常见的失败原因有哪些？","level":3},{"t":"p","text":"试剂浓度配错或变质（如 Sn²⁺ 被氧化、Fe²⁺ 被空气氧化）；加入顺序或用量不当；电极表面氧化或沾污；盐桥干涸或漏液；观察颜色变化时背景光不合适。"},{"t":"h","text":"影响电极电势的因素有哪些？","level":3},{"t":"p","text":"浓度、温度、介质酸度、沉淀、配合物。"},{"t":"h","text":"为什么 MnO₂ 能与浓盐酸反应而不能与稀盐酸反应？","level":3},{"t":"p","text":"酸度影响 MnO₂/Mn²⁺ 电对的电极电势，浓酸中 E 足够大，可以氧化 Cl⁻。"},{"t":"h","text":"为什么 2Fe²⁺ + I₂ + 2Ag⁺ → 2AgI↓ + 2Fe³⁺ 正向进行，而 2[FeF₆]³⁻ + 2I⁻ → I₂ + 2Fe²⁺ + 6F⁻ 不能？","level":3},{"t":"p","text":"AgI 沉淀降低 I⁻ 浓度使反应正向；[FeF₆]³⁻ 配合物降低了 Fe³⁺ 的有效浓度，使 Fe³⁺/Fe²⁺ 电对的电极电势显著下降，Fe³⁺ 不能氧化 I⁻。"},{"t":"h","text":"==核心知识点回顾==","level":3},{"t":"p","text":"· 电极电势判断反应方向：E(氧化剂) > E(还原剂) → 正向自发\n· 酸度升高 → 含氧氧化剂的氧化性增强\n· 沉淀／配合物生成 → 离子有效浓度降低 → 电极电势改变 → 反应方向可能逆转\n· 原电池：化学能 → 电能；电解池：电能 → 化学能"}],"count":10,"qa":[{"q":"如何用电极电势判断氧化还原反应的方向？","a":"比较氧化剂电对与还原剂电对的电极电势：E(氧化剂电对) > E(还原剂电对) 时反应自发正向进行，差值越大反应进行程度越大。这是判断氧化还原方向的核心判据。"},{"q":"介质酸度为什么会影响氧化性？","a":"含氧酸及其盐参与的半反应中有 H⁺ 或 OH⁻ 参加，改变酸度会改变电极电势。一般含氧化合物在酸性介质中氧化性更强，碱性介质中减弱，甚至改变反应产物。"},{"q":"沉淀或配合物的生成如何改变电极电势？","a":"若电对中的某种离子与沉淀剂或配位剂结合，其有效浓度大幅降低，电极电势随之改变，可能增强或削弱该物质的氧化还原能力。例如 Ag⁺ 生成 AgCl 后，Ag⁺/Ag 的电极电势明显下降。"},{"q":"原电池与电解池有什么区别？盐桥起什么作用？","a":"原电池把化学能转变为电能，电解池把电能转变为化学能。盐桥用于沟通两个半电池、保持电中性并减小液接电势，使电池能持续放电。"},{"q":"为什么说电极电势是强度性质？","a":"电极电势与电对的本性和浓度（活度）有关，而与物质的数量无关。因此同一电对无论取多少，其电极电势不变；这与电极反应中转移的电子数无关。"},{"q":"本实验常见的失败原因有哪些？","a":"试剂浓度配错或变质（如 Sn²⁺ 被氧化、Fe²⁺ 被空气氧化）；加入顺序或用量不当；电极表面氧化或沾污；盐桥干涸或漏液；观察颜色变化时背景光不合适。"}]}],"qa":[{"q":"如何用电极电势判断氧化还原反应的方向？","a":"比较氧化剂电对与还原剂电对的电极电势：E(氧化剂电对) > E(还原剂电对) 时反应自发正向进行，差值越大反应进行程度越大。这是判断氧化还原方向的核心判据。"},{"q":"介质酸度为什么会影响氧化性？","a":"含氧酸及其盐参与的半反应中有 H⁺ 或 OH⁻ 参加，改变酸度会改变电极电势。一般含氧化合物在酸性介质中氧化性更强，碱性介质中减弱，甚至改变反应产物。"},{"q":"沉淀或配合物的生成如何改变电极电势？","a":"若电对中的某种离子与沉淀剂或配位剂结合，其有效浓度大幅降低，电极电势随之改变，可能增强或削弱该物质的氧化还原能力。例如 Ag⁺ 生成 AgCl 后，Ag⁺/Ag 的电极电势明显下降。"},{"q":"原电池与电解池有什么区别？盐桥起什么作用？","a":"原电池把化学能转变为电能，电解池把电能转变为化学能。盐桥用于沟通两个半电池、保持电中性并减小液接电势，使电池能持续放电。"},{"q":"为什么说电极电势是强度性质？","a":"电极电势与电对的本性和浓度（活度）有关，而与物质的数量无关。因此同一电对无论取多少，其电极电势不变；这与电极反应中转移的电子数无关。"},{"q":"本实验常见的失败原因有哪些？","a":"试剂浓度配错或变质（如 Sn²⁺ 被氧化、Fe²⁺ 被空气氧化）；加入顺序或用量不当；电极表面氧化或沾污；盐桥干涸或漏液；观察颜色变化时背景光不合适。"}],"order":6,"hidden":false,"visibleAt":""}}};
